-- 0012 — as três trilhas que estavam no código.
--
-- Geradas a partir de src/lib/trilhas/<id>/index.js, com o conteúdo
-- montado exatamente como a tela o recebia: ROADMAP (com as etapas já
-- na ordem do index.js), PROJETOS, RECURSOS, LEGENDA, ESTADOS e
-- CRITERIOS. Isto é mudança de lugar, não de conteúdo.
--
-- As contagens não vêm daqui: o gatilho trilha_contagem as calcula, e
-- é por isso que elas deixam de divergir do que está escrito.

insert into public.trilha (id, rotulo, cor, rota, ordem, conteudo)
values
  ('ml', 'Machine Learning', '#2d6a8a',
   '[[32,198],[96,168],[152,118],[216,94],[272,46]]'::jsonb, 0,
   '{"ROADMAP":{"titulo":"Machine Learning","subtitulo":"A ordem completa — 2026","fonte":{"rotulo":"r/learnmachinelearning — how to learn machine learning in 2026","url":"https://www.reddit.com/r/learnmachinelearning/comments/1wn850o/how_to_learn_machine_learning_in_2026_the/","consultadoEm":"2026-10-09"},"etapas":[{"id":"python","numero":1,"titulo":"Python","objetivo":"Dominar o subconjunto de Python usado em pipelines de ML.","descricao":"Você não precisa de Python inteiro. Precisa do pedaço que aparece em pipeline de ML: manipular estruturas de dados, escrever funções e classes legíveis, ler um traceback sem pânico e montar um ambiente que outra pessoa consiga reproduzir. Quase todo bug difícil de ML que parece matemático é, na verdade, um erro de Python — um shape errado, uma lista copiada por referência, um caminho relativo que mudou. Esta etapa é o que te permite distinguir os dois casos.","preRequisitos":"Nenhum","duracao":null,"grupos":[{"id":"g-python","titulo":null,"topicos":[{"id":"py-01","titulo":"Começar","prioridade":"fundamental","desc":"Instalar Python, escolher editor, executar um script.","detalhe":"Instale uma versão recente pelo site oficial ou por um gerenciador (pyenv, uv). Evite o Python que já veio com o sistema operacional: ele pertence ao SO e atualizá-lo pode quebrar outras coisas. Confirme com `python --version` e rode um arquivo `.py` pelo terminal, não só pelo botão do editor — saber invocar o interpretador na mão é o que te salva quando o editor não ajuda."},{"id":"py-02","titulo":"Ambientes","prioridade":"fundamental","desc":"venv/conda, gerenciadores de pacotes, layout de projeto, regras de importação.","detalhe":"Um ambiente virtual é um diretório com seu próprio Python e suas próprias bibliotecas. Sem ele, dois projetos que pedem versões diferentes de torch entram em conflito e você perde horas. Crie um por projeto, ative antes de instalar qualquer coisa e congele as versões (`pip freeze > requirements.txt`). Sobre imports: Python resolve módulos a partir do diretório de onde você executou o script, não de onde o arquivo está — é a origem da maioria dos `ModuleNotFoundError` em projeto com subpastas."},{"id":"py-03","titulo":"Variáveis e objetos","prioridade":"fundamental","desc":"Números, booleanos, None, comparações.","detalhe":"Em Python toda variável é um nome apontando para um objeto, nunca uma caixa com um valor dentro. Isso explica comportamentos que surpreendem: atribuir `b = a` não copia nada, só cria um segundo nome para o mesmo objeto. `None` é o objeto que representa ausência — compare com `is None`, não com `==`. Cuidado com float: `0.1 + 0.2 != 0.3`, e isso vai reaparecer quando você comparar losses."},{"id":"py-04","titulo":"Strings","prioridade":"fundamental","desc":"Literais, fatiamento, imutabilidade, métodos, f-strings.","detalhe":"Strings são imutáveis: todo método que parece alterar (`.upper()`, `.replace()`) devolve uma nova. Concatenar dentro de um laço cria uma string nova a cada volta e fica lento; use `''''.join(lista)`. As f-strings (`f\"loss={loss:.4f}\"`) são a forma moderna de formatar e o `:.4f` controla casas decimais — você vai usar isso em todo log de treinamento."},{"id":"py-05","titulo":"Listas","prioridade":"fundamental","desc":"Criação, mutação, aninhamento, armadilhas de cópia.","detalhe":"Lista é mutável e ordenada, e é por isso que as armadilhas de cópia existem. `b = a` compartilha a mesma lista; `b = a[:]` ou `list(a)` copia o nível de cima, mas as listas internas continuam compartilhadas (cópia rasa) — para listas aninhadas use `copy.deepcopy`. Outra armadilha clássica: `[[0]*3]*3` cria três referências para a MESMA linha, então alterar uma altera as três."},{"id":"py-06","titulo":"Tuplas e conjuntos","prioridade":"importante","desc":"Uso básico, imutabilidade, operações de conjunto.","detalhe":"Tupla é a lista imutável: use quando a coleção não deve mudar, como o shape de um tensor ou o retorno de uma função com vários valores. Por ser imutável, pode ser chave de dicionário. Set não tem ordem nem repetição e testa pertencimento em tempo constante — verificar se um id já foi visto num set é instantâneo, numa lista é linear. Use sets para achar diferença entre conjuntos de ids de treino e teste; é a forma mais rápida de detectar vazamento."},{"id":"py-07","titulo":"Dicionários","prioridade":"fundamental","desc":"Criação, acesso seguro, iteração, dicionários aninhados, comprehensions.","detalhe":"Dicionário é a estrutura mais usada em ML: configuração de experimento, `state_dict` de modelo, mapeamento de rótulo para índice, histórico de métricas. Prefira `.get(chave, padrão)` a indexar direto quando a chave pode faltar, e `.items()` para iterar chave e valor juntos. Desde o Python 3.7 a ordem de inserção é preservada, o que importa quando você serializa um dicionário de hiperparâmetros e espera o mesmo arquivo nas duas vezes."},{"id":"py-08","titulo":"Fluxo de controle","prioridade":"fundamental","desc":"if/elif/else, for, while, enumerate, zip.","detalhe":"O `for` de Python percorre elementos, não índices. Quando precisar do índice, use `enumerate(lista)`; quando precisar percorrer duas sequências em paralelo, `zip(a, b)` — e lembre que `zip` para na mais curta, silenciosamente, o que já escondeu muito bug de dataset desalinhado. Em ML, a regra prática é a oposta da intuição: laço explícito sobre números é sinal de que você deveria estar usando NumPy ou PyTorch vetorizado."},{"id":"py-09","titulo":"Comprehensions e iteradores","prioridade":"importante","desc":"list/set/dict comprehensions, expressões geradoras, iter, next.","detalhe":"Comprehension é a forma idiomática de transformar uma coleção: `[f(x) for x in dados if cond(x)]`. Mais legível e mais rápida que o laço equivalente com `.append()`. Troque os colchetes por parênteses e você tem um gerador: ele produz um item por vez em vez de materializar tudo na memória — é exatamente isso que um `DataLoader` faz com um dataset que não cabe na RAM. Entender `iter`/`next` é entender por que um gerador se esgota e não pode ser percorrido duas vezes."},{"id":"py-10","titulo":"Funções","prioridade":"fundamental","desc":"Definição, *args, **kwargs, escopo, expressões lambda.","detalhe":"`*args` coleta posicionais extras numa tupla e `**kwargs` coleta nomeados num dicionário; é assim que bibliotecas repassam configuração sem enumerar cada parâmetro. A armadilha a decorar: nunca use valor mutável como padrão (`def f(x=[])`) — o objeto é criado uma única vez, na definição, e é compartilhado entre todas as chamadas. Use `None` como padrão e crie dentro da função."},{"id":"py-11","titulo":"Anotações de tipo","prioridade":"importante","desc":"Leitura e escrita de anotações typing.","detalhe":"Anotações não são verificadas em tempo de execução — Python as ignora. Servem para quem lê o código e para ferramentas (mypy, autocomplete do editor). Em ML o valor prático é documentar o que entra e o que sai de cada função: `def treinar(modelo: nn.Module, dl: DataLoader) -> dict[str, float]` já conta metade da história. Saber ler `Optional[X]`, `list[X]` e `Callable` é suficiente para navegar na documentação de qualquer biblioteca."},{"id":"py-12","titulo":"Classes","prioridade":"fundamental","desc":"Definição, herança, métodos dunder, @dataclass, decoradores.","detalhe":"Você vai escrever classes em ML principalmente por herança de framework: todo modelo em PyTorch é uma subclasse de `nn.Module` e todo dataset customizado implementa `__len__` e `__getitem__`. Esses métodos com underscore duplo (\"dunder\") são o contrato que faz seu objeto funcionar com `len()` e com `obj[i]`. `@dataclass` elimina o `__init__` repetitivo e é ideal para objetos de configuração."},{"id":"py-13","titulo":"Erros e exceções","prioridade":"importante","desc":"try/except, leitura de tracebacks, exceções customizadas, gerenciadores de contexto.","detalhe":"Leia o traceback de baixo para cima: a última linha diz o tipo do erro e a penúltima seção diz onde no SEU código ele nasceu — o topo costuma ser código de biblioteca. Nunca escreva `except:` vazio ou `except Exception: pass`; isso engole inclusive o seu Ctrl+C e transforma uma falha ruidosa numa falha silenciosa, que é a pior espécie num treinamento de 6 horas. Gerenciadores de contexto (`with`) garantem limpeza mesmo com erro — é o mesmo mecanismo por trás de `with torch.no_grad():`."},{"id":"py-14","titulo":"I/O de arquivos","prioridade":"fundamental","desc":"Leitura/escrita de texto, binário, pathlib, JSON, CSV.","detalhe":"Use `pathlib.Path` em vez de concatenar strings com barras: funciona igual em Windows e Linux e tem `.exists()`, `.mkdir(parents=True)` e `.glob()` embutidos. Sempre abra texto com `encoding=''utf-8''` explícito — o padrão varia por sistema e é o motivo de um CSV com acentos abrir certo na sua máquina e corrompido na do colega. JSON serve para configuração e métricas; para dataset tabular grande, prefira parquet a CSV."},{"id":"py-15","titulo":"Biblioteca padrão e ecossistema","prioridade":"importante","desc":"Imports, scripts como módulos, visão geral de numpy, pandas, scikit-learn e torch.","detalhe":"Saiba a divisão de trabalho antes de escolher a ferramenta: NumPy é array numérico na CPU; pandas é tabela com rótulos, para explorar e limpar dados; scikit-learn é o conjunto de modelos clássicos e, mais importante, o padrão de API `fit`/`predict`/`transform`; PyTorch é tensor com autograd e GPU. Da biblioteca padrão, conheça `pathlib`, `json`, `csv`, `random`, `logging`, `argparse` e `dataclasses` — cobrem quase tudo de infraestrutura de um script de treino."},{"id":"py-16","titulo":"Padrões Python para ML","prioridade":"opcional","desc":"Decoradores para logging, acesso dinâmico a atributos, idiomatismo comum, hábitos de depuração.","detalhe":"Um decorador é uma função que embrulha outra; em ML aparece como `@torch.no_grad()`, `@staticmethod` e em cronômetros de execução que você mesmo escreve. Para depurar, troque `print` por `breakpoint()`: abre um debugger no ponto exato e deixa você inspecionar shapes ao vivo. Use o módulo `logging` em vez de `print` em scripts de treino longos — ele carimba horário, tem níveis e grava em arquivo sem você reescrever nada."}]}]},{"id":"matematica","numero":2,"titulo":"Matemática","objetivo":"Adquirir fundamentos de álgebra linear, cálculo, probabilidade, teoria da informação e computação numérica usados por ML.","descricao":"O objetivo aqui não é virar matemático, é parar de tratar o modelo como caixa-preta. Cada bloco desta etapa responde a uma pergunta que vai aparecer depois: álgebra linear explica o que uma camada faz com os dados; cálculo explica como o treino sabe para onde andar; probabilidade explica de onde vem cada função de perda; teoria da informação explica por que cross-entropy é a perda natural de classificação; computação numérica explica por que o loss virou NaN. Estude com código ao lado: implemente o conceito em NumPy e compare com a função pronta.","preRequisitos":"Etapa 1","duracao":"~9 semanas","grupos":[{"id":"g-ferramentas","titulo":"Ferramentas matemáticas","duracao":"1 sem","descricao":"A notação que todo paper e toda documentação assume que você lê sem traduzir.","topicos":[{"id":"mt-01","titulo":"Notação","prioridade":"fundamental","desc":"Funções, composição, inversas, chapéus e tils (ŷ, x̃), pertinência a conjuntos, notação big-O.","detalhe":"Convenções que se repetem em todo texto de ML: `ŷ` (y com chapéu) é a predição e `y` é o valor verdadeiro; `θ` é o conjunto de parâmetros; `x ∈ ℝⁿ` diz que x é um vetor de n números reais; `f ∘ g` é composição, que é literalmente o que empilhar camadas significa. A notação big-O descreve como o custo cresce com o tamanho da entrada — você vai usar para comparar atenção (O(n²)) com convolução (O(n))."},{"id":"mt-02","titulo":"Expoentes, logaritmos e trigonometria","prioridade":"fundamental","desc":"Expoentes, logaritmos, trigonometria básica, círculo unitário.","detalhe":"Logaritmo é a ferramenta central e por um motivo prático: transforma produto em soma. Como verossimilhança é um produto de muitas probabilidades menores que 1, ela vira zero por underflow — trabalhar com log resolve, e é por isso que quase toda perda tem um `log` dentro. Exponencial aparece em softmax e em decaimento de learning rate; trigonometria aparece em similaridade cosseno e em positional encoding de transformers."},{"id":"mt-03","titulo":"Somatórios e combinatória","prioridade":"importante","desc":"Notação de somatórios e produtos, argmin/argmax, combinatória.","detalhe":"Distinga `max` de `argmax`: o primeiro devolve o maior valor, o segundo devolve ONDE ele está. A predição de um classificador é um argmax sobre as probabilidades de classe, não o max. Σ e Π traduzem direto para laços — e, em NumPy, para `.sum()` e `.prod()` com um eixo. Saber ler o índice do somatório é saber qual eixo reduzir, que é a origem de metade dos erros de shape."}]},{"id":"g-algebra","titulo":"Álgebra linear","duracao":"3 sem","descricao":"A linguagem em que os dados e o modelo são escritos. Dado é matriz, camada é multiplicação de matriz, e a GPU existe porque essa operação paraleliza bem.","topicos":[{"id":"al-01","titulo":"Vetores, matrizes e bases","prioridade":"fundamental","desc":"Escalares, vetores, matrizes, span (espaço gerado), bases, independência linear, colinearidade, multiplicação matricial como transformação linear, transposta, produto externo (outer product), produto Hadamard, identidade, diagonal, simétrica.","detalhe":"A ideia que destrava tudo: uma matriz não é uma tabela de números, é uma função que transforma vetores. `Wx` leva x de um espaço para outro, e é exatamente isso que uma camada densa faz. Independência linear e colinearidade têm consequência direta em dados: duas features perfeitamente correlacionadas são colineares e tornam a solução instável ou não-única. Atenção à distinção entre produto matricial (`@`) e produto Hadamard, elemento a elemento (`*`) — confundir os dois em NumPy não dá erro, dá resultado errado."},{"id":"al-02","titulo":"Sistemas lineares e posto","prioridade":"fundamental","desc":"Sistemas lineares, eliminação de Gauss, determinante, inversa, singularidade, posto (rank), espaço coluna e nulo, traço.","detalhe":"Posto é quanta informação independente a matriz realmente carrega. Uma matriz de dados com posto menor que o número de colunas tem features redundantes. Matriz singular é a que não tem inversa — e é por isso que a solução fechada da regressão linear quebra quando há colinearidade perfeita, o que por sua vez motiva a regularização (somar λI à diagonal torna o sistema resolvível). Na prática você quase nunca inverte uma matriz: resolve o sistema, que é mais estável e mais barato."},{"id":"al-03","titulo":"Produto escalar, normas e projeções","prioridade":"fundamental","desc":"Produto escalar, normas, distâncias, ângulos, similaridade cosseno, produto vetorial, ortogonalidade, matrizes ortogonais, projeções ortogonais, bases ortonormais, mínimos quadrados.","detalhe":"Produto escalar mede alinhamento entre dois vetores, e é a operação atômica de toda rede neural e de todo mecanismo de atenção. Similaridade cosseno é o produto escalar normalizado: compara direção ignorando magnitude, que é o que você quer ao comparar embeddings de tamanhos diferentes. Normas medem tamanho — L2 penaliza outliers mais que L1, e essa única diferença explica por que regularização L1 gera pesos esparsos e L2 não. Mínimos quadrados é projeção ortogonal: a predição é a sombra de y no espaço que o modelo consegue alcançar."},{"id":"al-04","titulo":"Autovalores, SVD e fatorações","prioridade":"importante","desc":"Autovalores e autovetores, mudança de base, decomposição espectral, matrizes PSD, quociente de Rayleigh, número de condição, SVD, aproximação de posto baixo (low-rank), fatorações QR e Cholesky.","detalhe":"Autovetor é a direção que a matriz só estica, sem girar; o autovalor é o quanto estica. PCA é exatamente isso aplicado à matriz de covariância: as direções de maior variância dos seus dados. SVD generaliza para qualquer matriz e dá a melhor aproximação de posto baixo — a base de compressão, de sistemas de recomendação e, hoje, do LoRA, que faz fine-tuning treinando apenas duas matrizes finas. Número de condição alto significa problema mal-condicionado: pequenas mudanças na entrada provocam grandes mudanças na saída, e o treino fica instável."},{"id":"al-05","titulo":"Tensores e broadcasting","prioridade":"importante","desc":"Tensores, broadcasting, notação einsum.","detalhe":"Tensor aqui é só array de N dimensões. O shape típico de um batch é `(batch, canais, altura, largura)` e saber ler isso é metade do trabalho. Broadcasting é a regra que permite somar shapes diferentes esticando dimensões de tamanho 1 — poderoso e perigoso: somar `(32, 1)` com `(32,)` produz silenciosamente `(32, 32)` em vez de erro. Quando um loss ficar estranho sem motivo, suspeite disso. `einsum` escreve qualquer contração de índices de forma explícita e é a melhor defesa contra esse tipo de bug."}]},{"id":"g-calculo","titulo":"Cálculo e otimização","duracao":"2 sem","descricao":"Como o modelo aprende. Treinar é descer uma superfície de erro, e derivada é a bússola que diz para onde.","topicos":[{"id":"ca-01","titulo":"Derivadas e regra da cadeia","prioridade":"fundamental","desc":"Limites, continuidade, derivadas, derivadas parciais, gradientes, Jacobiano, regra da cadeia, cálculo matricial, backpropagation em camada linear, diferenciação automática.","detalhe":"Gradiente é o vetor das derivadas parciais: aponta na direção de maior aumento, então você anda no sentido oposto para reduzir o erro. A regra da cadeia é o coração de tudo: uma rede é composição de funções, e a derivada da composição é o produto das derivadas. Backpropagation é só a aplicação organizada disso, da saída para a entrada, reaproveitando cálculos. Diferenciação automática é como PyTorch faz isso sozinho: cada operação registra no grafo como derivar a si mesma, e `.backward()` percorre o grafo ao contrário. Entender isso é o que te permite diagnosticar gradiente que some ou que explode."},{"id":"ca-02","titulo":"Hessiana e convexidade","prioridade":"importante","desc":"Hessiana, expansão de Taylor, funções convexas, pontos críticos, mínimos locais vs sela, definitude via autovalores.","detalhe":"A Hessiana é a matriz das segundas derivadas: descreve a curvatura. Gradiente zero não garante mínimo — pode ser máximo ou ponto de sela, e são os autovalores da Hessiana que distinguem. Em alta dimensão, selas são muito mais comuns que mínimos locais ruins, o que é uma das razões de redes profundas treinarem melhor do que a intuição 2D sugere. Função convexa tem um único mínimo (regressão linear e logística são convexas); rede neural não é, e por isso o resultado depende da inicialização e da seed."}]},{"id":"g-probabilidade","titulo":"Probabilidade e estatística","duracao":"3 sem","descricao":"De onde vêm as funções de perda e como não se enganar com um número de validação. ML é, em boa medida, estatística aplicada com mais parâmetros.","topicos":[{"id":"pb-01","titulo":"Variáveis aleatórias e Bayes","prioridade":"fundamental","desc":"Variáveis aleatórias, PMF/PDF, conjunta, marginal e condicional, independência, regras de soma e produto, união, regra da cadeia da probabilidade, Teorema de Bayes.","detalhe":"Classificação é estimar `P(classe | entrada)` — uma probabilidade condicional. Bayes é a regra que inverte condicionais e explica por que um teste com 99% de acerto para uma doença rara ainda produz mais falsos positivos que verdadeiros: a prevalência (o prior) domina. Essa mesma aritmética explica por que acurácia engana em dataset desbalanceado. Guarde a distinção entre PMF (discreta) e PDF (contínua): numa PDF o valor pode passar de 1, porque o que vale 1 é a área, não a altura."},{"id":"pb-02","titulo":"Distribuições","prioridade":"fundamental","desc":"Discretas (Bernoulli, Binomial, Poisson) e contínuas (Gaussiana, Beta, Exponencial e outras).","detalhe":"Cada distribuição é uma hipótese sobre como seus dados foram gerados, e essa hipótese escolhe a função de perda. Bernoulli (sim/não) leva a binary cross-entropy; categórica leva a cross-entropy; Gaussiana leva a MSE. A Gaussiana domina por causa do Teorema Central do Limite, não porque a natureza goste dela. Poisson modela contagens por intervalo; Beta modela uma probabilidade desconhecida e aparece em calibração."},{"id":"pb-03","titulo":"Momentos e covariância","prioridade":"importante","desc":"Esperança (valor esperado), variância, covariância, correlação, Gaussiana multivariada, distância de Mahalanobis.","detalhe":"Média e variância são o que você calcula para normalizar features — e precisam ser calculadas SÓ no conjunto de treino, senão é vazamento. Correlação mede associação linear e tem dois limites que importam: não implica causalidade, e não captura relação não linear (duas variáveis podem ter correlação zero e dependência total). Mahalanobis é distância que leva em conta a covariância: mede o quanto um ponto é atípico considerando o formato da nuvem de dados, e serve de detector de outliers."},{"id":"pb-04","titulo":"LGN, TCL e testes","prioridade":"importante","desc":"Lei dos Grandes Números, Teorema Central do Limite, intervalos de confiança, testes de hipótese, p-values.","detalhe":"O TCL é a razão de a média de qualquer coisa tender à Gaussiana, e portanto a razão de intervalos de confiança funcionarem. O uso prático em ML é sóbrio e muito necessário: seu conjunto de validação é uma amostra, então a métrica tem incerteza. Com 200 exemplos de validação, uma diferença de 1% entre dois modelos provavelmente é ruído. Rode com várias seeds e reporte média e desvio — comparar dois números únicos é o erro mais comum de quem está começando."},{"id":"pb-05","titulo":"MLE, MAP e inferência bayesiana","prioridade":"importante","desc":"Máxima verossimilhança (MLE), estimativa MAP, inferência bayesiana, priors e posteriors, preditiva posterior, priors conjugados, viés-variância.","detalhe":"MLE é o princípio que unifica as perdas: escolher os parâmetros que tornam os dados observados mais prováveis. Minimizar MSE é MLE sob ruído gaussiano; minimizar cross-entropy é MLE sob distribuição categórica. Não são escolhas arbitrárias. MAP acrescenta um prior, e aqui está a conexão bonita: usar um prior gaussiano sobre os pesos é matematicamente idêntico a regularização L2. Regularizar é declarar uma crença prévia de que os pesos devem ser pequenos."},{"id":"pb-06","titulo":"Monte Carlo e amostragem","prioridade":"opcional","desc":"Monte Carlo, amostragem de importância, amostragem por rejeição, MCMC, truque de reparametrização, bootstrap.","detalhe":"Monte Carlo é estimar o que não se consegue calcular, amostrando. O item com maior retorno imediato aqui é o bootstrap: reamostrar seu conjunto de teste com reposição várias vezes dá um intervalo de confiança para a métrica sem nenhuma suposição — é a forma mais honesta e mais barata de dizer se a diferença entre dois modelos é real. O truque de reparametrização é o que permite treinar VAEs por gradiente, e MCMC aparece quando você faz inferência bayesiana de verdade."}]},{"id":"g-informacao","titulo":"Teoria da informação","duracao":"3 dias","descricao":"Curto, mas é o bloco que explica a função de perda mais usada em classificação.","topicos":[{"id":"ti-01","titulo":"Entropia e divergência KL","prioridade":"importante","desc":"Autoinformação, entropia, entropia diferencial, princípio da máxima entropia, cross-entropy, divergência KL, informação mútua.","detalhe":"Informação é surpresa: evento improvável carrega mais bits. Entropia é a surpresa média de uma distribuição — quanta incerteza ela tem. Cross-entropy é a surpresa média quando você usa a distribuição prevista para codificar dados que na verdade seguem outra. Minimizá-la é aproximar a previsão da verdade, e é literalmente a loss de classificação. KL é cross-entropy menos entropia: o custo extra de ter errado a distribuição. Como a entropia dos rótulos verdadeiros é constante, minimizar cross-entropy e minimizar KL são a mesma coisa. Informação mútua mede dependência de qualquer tipo, não só linear, e serve para seleção de features."}]},{"id":"g-numerica","titulo":"Computação numérica","duracao":"2 dias","descricao":"Pequeno e muito rentável: é o bloco que explica NaN, inf e loss que trava.","topicos":[{"id":"cn-01","titulo":"Ponto flutuante e estabilidade","prioridade":"importante","desc":"Representação em ponto flutuante, overflow e underflow, truque log-sum-exp, média móvel exponencial.","detalhe":"Float tem precisão finita: float32 guarda cerca de 7 dígitos significativos. `exp(1000)` estoura para infinito e `log(0)` vai para menos infinito — as duas fontes mais comuns de NaN no treino. O truque log-sum-exp (subtrair o máximo antes de exponenciar) resolve, e é por isso que você deve passar logits para `CrossEntropyLoss` em vez de aplicar softmax antes: a versão combinada é numericamente estável. Média móvel exponencial aparece em Adam, em batch norm e em qualquer métrica suavizada que você plotar."}]}]},{"id":"pytorch","numero":3,"titulo":"PyTorch","objetivo":"Tornar-se fluente com tensores, autograd e utilitários básicos.","descricao":"Esta etapa é deliberadamente curta: o objetivo é fluência com tensores, não com redes. Você ainda não vai treinar nada. A ideia é que, quando chegar na Etapa 4, nenhum erro seja sobre a ferramenta — se o treino falhar, que seja por um motivo conceitual, não porque um tensor estava no device errado ou com o shape transposto. Se você já sabe NumPy, 80% disto é tradução direta; o que é genuinamente novo é autograd e o conceito de device.","preRequisitos":"Etapa 2","duracao":null,"grupos":[{"id":"g-pytorch","titulo":null,"topicos":[{"id":"pt-01","titulo":"Tensores básicos","prioridade":"fundamental","desc":"Criação, dtype, forma, armazenamento vs visualização, reshape, indexação, concatenação, primeira introdução ao autograd.","detalhe":"Tensor é um array de N dimensões que, diferente do NumPy, sabe rodar na GPU e rastrear suas próprias derivadas. A distinção que mais causa bug é view versus cópia: `.view()` e `.reshape()` costumam devolver uma vista que COMPARTILHA memória com o original, então alterar uma altera a outra. Use `.clone()` quando quiser independência de fato. Sobre dtype: a maior parte do treino roda em float32, rótulos de classificação precisam ser `long`, e misturar tipos gera erro ou conversão silenciosa. Quando um tensor tem `requires_grad=True`, o PyTorch passa a gravar todas as operações sobre ele num grafo para poder derivar depois."},{"id":"pt-02","titulo":"Operações em tensores","prioridade":"fundamental","desc":"Aritmética elemento a elemento, broadcasting, multiplicação matricial, reduções, comparações, seleções.","detalhe":"Vale decorar a diferença entre `*` (elemento a elemento) e `@` / `torch.matmul` (produto matricial) — e que broadcasting se aplica ao primeiro. Nas reduções (`.sum()`, `.mean()`, `.max()`), o argumento `dim` é o eixo que DESAPARECE; `keepdim=True` mantém a dimensão com tamanho 1 para o broadcasting seguinte funcionar. Em classificação você usa `.argmax(dim=1)` para converter logits em classe prevista. Hábito que economiza horas: imprima `.shape` depois de cada operação enquanto monta o modelo, em vez de descobrir o desalinhamento três camadas depois."},{"id":"pt-03","titulo":"Interoperabilidade e utilitários","prioridade":"importante","desc":"Conversão com NumPy, reprodutibilidade (torch.manual_seed), dispositivos CPU/GPU, serialização (torch.save e torch.load), helpers diversos.","detalhe":"`torch.from_numpy()` e `.numpy()` compartilham memória quando o tensor está na CPU — alterar um altera o outro. Para ir de GPU para NumPy é preciso `.detach().cpu().numpy()`: detach solta o grafo de gradientes e cpu move a memória. Todo tensor de uma mesma operação precisa estar no mesmo device, e esse é o erro número um de quem começa a usar GPU. Salve `state_dict()` em vez do objeto inteiro do modelo: o pickle do objeto quebra quando a classe muda de nome ou de arquivo. Semente fixa reduz a variação, mas não elimina: cuDNN tem kernels não-determinísticos, e é normal duas execuções com a mesma seed diferirem um pouco."}]}]},{"id":"fundamentos","numero":4,"titulo":"Fundamentos de ML","objetivo":"Aprender conceitos centrais de aprendizagem supervisionada, redes profundas, otimização, regularização, avaliação e diagnóstico.","descricao":"O núcleo do roadmap: 112 dos 156 tópicos estão aqui, e isso é proposital. As cinco unidades seguem uma progressão deliberada — primeiro o que é um modelo e uma perda, depois como empilhar camadas, depois como fazer o treino convergir de fato, depois como impedir que ele decore, e por fim como medir tudo isso sem se enganar. A Unidade 5 é a que mais separa quem sabe de quem acha que sabe: treinar é fácil, avaliar honestamente é difícil. Resista à tentação de pular para a especialização antes de terminar aqui.","preRequisitos":"Etapas 1 a 3","duracao":"10–14 semanas","grupos":[{"id":"g-unidade-1","titulo":"Unidade 1 — Do neurônio ao classificador","descricao":"Constrói o vocabulário mínimo: modelo, perda, gradiente. Termina com você entendendo um classificador logístico por inteiro, do dado à probabilidade.","topicos":[{"id":"u1-01","titulo":"Paradigma de aprendizagem","prioridade":"fundamental","desc":"Modelo, loss, regra de otimização.","detalhe":"Todo algoritmo supervisionado tem as mesmas três peças: um modelo com parâmetros ajustáveis, uma função de perda que mede o erro, e uma regra que atualiza os parâmetros para reduzi-la. Trocar de arquitetura é trocar a primeira peça; quase tudo o mais permanece. Enxergar essa estrutura faz um paper novo parecer uma variação, não um universo novo."},{"id":"u1-02","titulo":"Taxonomia de ML","prioridade":"fundamental","desc":"Supervisionado, não supervisionado, semissupervisionado, autossupervisionado (self-supervised) e reinforcement learning.","detalhe":"A divisão é sobre que sinal supervisiona o treino. Supervisionado tem rótulo humano; não supervisionado busca estrutura sem rótulo; autossupervisionado (self-supervised) inventa a tarefa a partir do próprio dado (prever a palavra escondida), e é o que tornou possível treinar LLMs em escala; RL aprende por recompensa atrasada. Como rotular é caro, o autossupervisionado é a tendência dominante."},{"id":"u1-03","titulo":"Teorema No Free Lunch","prioridade":"fundamental","desc":"Por que múltiplos modelos são necessários.","detalhe":"Nenhum algoritmo é superior a todos os outros em todos os problemas possíveis; o desempenho vem de suposições que casam com o domínio. Na prática isso significa: não existe ''melhor modelo'', existe melhor modelo para estes dados. É a justificativa formal para sempre começar com um baseline simples antes de assumir que precisa de rede profunda."},{"id":"u1-04","titulo":"Fundamentos de dados","prioridade":"fundamental","desc":"Dataset, features, rótulos, qualidade dos dados.","detalhe":"Linha é exemplo, coluna é feature, alvo é rótulo. A lição que custa caro: a qualidade do rótulo limita o teto do modelo. Se dois anotadores discordam em 15% dos casos, nenhum modelo passa muito disso, e a diferença entre 91% e 92% de acurácia vira ruído de anotação. Antes de trocar de arquitetura, olhe cem exemplos do seu dataset à mão."},{"id":"u1-05","titulo":"Perceptron histórico","prioridade":"opcional","desc":"Soma ponderada mais limiar.","detalhe":"O modelo de 1958: soma ponderada seguida de um degrau que devolve 0 ou 1. Vale pelo contexto histórico — a demonstração de que ele não resolve XOR causou o primeiro inverno da IA. A lição técnica que sobrevive é que o degrau tem derivada zero em todo lugar, logo não pode ser treinado por gradiente, o que motivou as ativações suaves."},{"id":"u1-06","titulo":"Neurônio artificial","prioridade":"fundamental","desc":"Soma ponderada mais bias mais ativação não linear.","detalhe":"A unidade de cálculo: `a = f(w·x + b)`. O produto escalar mede alinhamento entre a entrada e o que o neurônio procura; o bias desloca o limiar, permitindo ativar mesmo com entrada nula; a ativação não linear é o que impede a rede inteira de colapsar numa única transformação linear."},{"id":"u1-07","titulo":"Regressão linear","prioridade":"fundamental","desc":"Formulação, solução fechada, modelo base.","detalhe":"O modelo mais simples e o baseline que você deve bater antes de qualquer coisa complexa. Tem solução fechada (equação normal), o que o torna o exemplo perfeito para verificar se seu gradiente descendente implementado à mão chega ao mesmo lugar. Se uma rede profunda não supera a regressão linear no seu problema, o problema está nos dados, não na arquitetura."},{"id":"u1-08","titulo":"Visão geral de loss","prioridade":"fundamental","desc":"Propósito e relação com a tarefa.","detalhe":"A loss traduz ''errou'' num número que se pode derivar. É a única definição operacional de sucesso que o otimizador enxerga — ele vai minimizar exatamente o que você escreveu, inclusive quando isso não é o que você queria. A maior parte dos comportamentos estranhos de modelo é a loss sendo obedecida ao pé da letra."},{"id":"u1-09","titulo":"MSE","prioridade":"fundamental","desc":"Erro quadrático médio; penaliza erros grandes.","detalhe":"Média dos quadrados dos erros. O quadrado faz um erro de 10 pesar cem vezes mais que um erro de 1, então o modelo prioriza eliminar os erros grandes. Isso é desejável quando erro grande é desproporcionalmente caro, e péssimo quando seus dados têm outliers — um único rótulo errado pode dominar o gradiente. Equivale a MLE sob ruído gaussiano."},{"id":"u1-10","titulo":"MAE","prioridade":"importante","desc":"Penalidade linear, mais robusta a outliers.","detalhe":"Média dos erros absolutos. Cada erro pesa proporcionalmente ao seu tamanho, o que torna a MAE robusta a outliers. O custo: a derivada é constante e descontínua em zero, então a convergência final é menos suave. Enquanto MSE persegue a média condicional, MAE persegue a mediana."},{"id":"u1-11","titulo":"RMSE","prioridade":"opcional","desc":"MSE nas unidades originais.","detalhe":"Raiz do MSE. Otimizar RMSE ou MSE dá o mesmo mínimo — a raiz é monótona. O ganho é só de comunicação: RMSE está na mesma unidade do alvo, então ''erro de 3.2 reais'' é interpretável e ''10.24 reais²'' não é. Use MSE para treinar e RMSE para reportar."},{"id":"u1-12","titulo":"Huber loss","prioridade":"importante","desc":"Combina MSE e MAE.","detalhe":"Quadrática perto de zero e linear longe dele, com a transição num parâmetro δ. Fica com o melhor dos dois: gradiente suave perto do ótimo e robustez a outliers longe dele. É a escolha padrão sensata em regressão com dados do mundo real, que quase sempre têm alguns valores absurdos."},{"id":"u1-13","titulo":"Escolha de loss","prioridade":"importante","desc":"Procedimento de decisão baseado na tarefa e nos dados.","detalhe":"Decida por duas perguntas: qual é o tipo de saída (contínua, binária, multiclasse, multilabel) e qual erro custa mais caro no seu domínio. Regressão limpa pede MSE; regressão com outliers pede Huber; classificação pede cross-entropy. Quando as classes são muito desbalanceadas, pesos por classe ou focal loss importam mais do que a escolha da arquitetura."},{"id":"u1-14","titulo":"Teoria da informação aplicada","prioridade":"importante","desc":"Surpresa em bits.","detalhe":"A informação de um evento é `-log P(evento)`: quanto mais improvável, mais surpreendente, mais bits. Evento certo carrega zero informação. Essa única definição é a semente de entropia, cross-entropy e KL — e, portanto, da loss que você vai usar em toda classificação."},{"id":"u1-15","titulo":"Entropia","prioridade":"importante","desc":"Surpresa média de uma distribuição.","detalhe":"A média da surpresa, ponderada pelas probabilidades. Máxima quando tudo é equiprovável (incerteza total) e zero quando um resultado é certo. Serve de medida de impureza em árvores de decisão e de referência para saber quanta incerteza é irredutível no seu problema."},{"id":"u1-16","titulo":"Cross-entropy","prioridade":"fundamental","desc":"Surpresa média quando a verdade segue outra distribuição.","detalhe":"A loss padrão de classificação. Pune proporcionalmente ao log da probabilidade que o modelo atribuiu à classe correta: prever 0.99 na classe certa custa quase nada, prever 0.01 custa muito. Essa assimetria é o que faz o modelo aprender rápido no começo. Em PyTorch, `CrossEntropyLoss` já inclui o softmax — passe logits, não probabilidades."},{"id":"u1-17","titulo":"Divergência KL","prioridade":"importante","desc":"Diferença entre cross-entropy e entropia.","detalhe":"Mede o quanto uma distribuição difere de outra: é cross-entropy menos entropia. Não é simétrica, então KL(P||Q) ≠ KL(Q||P), e isso tem consequência prática em VAEs e em destilação de conhecimento. Em classificação comum, minimizar KL e minimizar cross-entropy são equivalentes, porque a entropia dos rótulos é constante."},{"id":"u1-18","titulo":"Máxima verossimilhança","prioridade":"fundamental","desc":"Parâmetros que maximizam a probabilidade dos dados.","detalhe":"O princípio que unifica as losses: escolha os parâmetros sob os quais os dados observados seriam mais prováveis. Como produto de probabilidades sofre underflow, maximiza-se o log — e maximizar log-verossimilhança é minimizar a negative log-likelihood, que é literalmente cross-entropy. As losses não foram inventadas; foram derivadas."},{"id":"u1-19","titulo":"Loss e suposições de distribuição","prioridade":"importante","desc":"MSE implica ruído gaussiano; cross-entropy implica categórico.","detalhe":"Escolher uma loss é assumir como o ruído dos seus dados se comporta, queira você ou não. MSE assume erro gaussiano simétrico; se o seu erro real é assimétrico ou tem cauda pesada, a loss está mentindo. Saber disso te dá uma ferramenta de diagnóstico: quando o modelo erra de um jeito sistemático, às vezes o problema é a loss, não a capacidade."},{"id":"u1-20","titulo":"Gradiente descendente","prioridade":"fundamental","desc":"Inclinação do loss para cada parâmetro e passo de atualização.","detalhe":"Calcule o gradiente da loss em relação a cada parâmetro e ande um passo no sentido contrário: `θ ← θ - η∇L`. Toda a dificuldade está no η (learning rate): alto demais e a loss diverge; baixo demais e o treino não termina. É o algoritmo que você deve implementar à mão uma vez, para uma regressão linear, antes de usar qualquer otimizador pronto."},{"id":"u1-21","titulo":"Backpropagation","prioridade":"fundamental","desc":"Aplicação eficiente da regra da cadeia.","detalhe":"Calcula o gradiente de todos os parâmetros em uma única passagem da saída para a entrada, reaproveitando resultados intermediários. Sem esse reaproveitamento, treinar rede profunda seria inviável. Não é um algoritmo de aprendizado — é só o cálculo eficiente da derivada; quem aprende é o otimizador."},{"id":"u1-22","titulo":"Loop de treinamento","prioridade":"fundamental","desc":"Forward, loss, backward, passo do otimizador, epochs, batches.","detalhe":"A sequência canônica: zerar gradientes, forward, calcular loss, backward, step do otimizador. Esquecer o `optimizer.zero_grad()` é o bug clássico — o PyTorch ACUMULA gradientes por padrão, então sem zerar você soma os do batch anterior e o treino fica inexplicavelmente ruim. Época é uma passada completa nos dados; batch é o pedaço processado por vez."},{"id":"u1-23","titulo":"DataLoaders","prioridade":"fundamental","desc":"Batching, shuffling, torch.utils.data.","detalhe":"O `Dataset` responde ''quantos exemplos existem'' e ''me dê o exemplo i''; o `DataLoader` cuida de agrupar em batches, embaralhar e carregar em paralelo. Embaralhar o treino é obrigatório (sem isso, batches ficam correlacionados e o gradiente vicia) e embaralhar validação é inútil. Se a GPU fica ociosa, o gargalo quase sempre está aqui, não no modelo."},{"id":"u1-24","titulo":"Sigmoid","prioridade":"fundamental","desc":"Comprime para [0,1] em classificação binária.","detalhe":"Comprime qualquer número real para o intervalo (0,1), permitindo ler a saída como probabilidade. Satura nos extremos: para entradas muito grandes ou muito pequenas, a derivada vira quase zero e o gradiente morre. Por isso serve bem como ativação de SAÍDA em classificação binária e mal como ativação de camadas internas."},{"id":"u1-25","titulo":"Regressão logística","prioridade":"fundamental","desc":"Modelo linear mais sigmoid.","detalhe":"Um neurônio só: combinação linear seguida de sigmoid. É o baseline obrigatório de classificação, treina em segundos, é interpretável (o peso diz a direção e a força de cada feature) e frequentemente chega perto de modelos muito mais caros em dado tabular. Comece sempre por ele."},{"id":"u1-26","titulo":"Binary Cross-Entropy","prioridade":"fundamental","desc":"Loss para classificação binária, sobre logits.","detalhe":"A cross-entropy no caso de duas classes. Prefira `BCEWithLogitsLoss` a aplicar sigmoid e depois `BCELoss`: a versão combinada usa log-sum-exp internamente e é numericamente estável, enquanto a separada produz NaN quando a sigmoid satura em exatamente 0 ou 1."},{"id":"u1-27","titulo":"Softmax multiclasse","prioridade":"fundamental","desc":"Converte scores em probabilidades.","detalhe":"Exponencia cada logit e normaliza, produzindo um vetor que soma 1. A exponencial exagera diferenças: logits 2 e 1 viram cerca de 0.73 e 0.27, não 0.67 e 0.33. É a generalização da sigmoid para N classes mutuamente exclusivas — se as classes NÃO são exclusivas, softmax é a escolha errada."},{"id":"u1-28","titulo":"Confiança do modelo","prioridade":"importante","desc":"Interpretação de probabilidades e calibração.","detalhe":"A saída do softmax parece probabilidade mas não é, necessariamente: redes modernas são sistematicamente sobre-confiantes, dizendo 0.99 em casos que acertam 80% das vezes. Quando a confiança vai ser usada para decidir (acionar um humano, recusar a predição), calibre com temperature scaling e verifique num diagrama de confiabilidade."},{"id":"u1-29","titulo":"Softmax estável","prioridade":"importante","desc":"Subtrair o máximo antes de exponenciar.","detalhe":"`exp(1000)` estoura para infinito. Subtrair o maior logit de todos antes de exponenciar não muda o resultado matemático (a constante cancela na normalização) e elimina o overflow. Toda implementação de biblioteca já faz isso — o item existe para você reconhecer o padrão e não reimplementar a versão ingênua."},{"id":"u1-30","titulo":"Classificação multilabel","prioridade":"importante","desc":"Sigmoides independentes mais BCE.","detalhe":"Quando um exemplo pode ter várias classes ao mesmo tempo (uma foto com cachorro E praia), softmax está errado porque força as probabilidades a competirem por um total de 1. Use uma sigmoid independente por classe com BCE, e escolha um limiar por classe — não existe argmax aqui."},{"id":"u1-31","titulo":"Limite geométrico de um neurônio","prioridade":"importante","desc":"Separabilidade linear.","detalhe":"Um neurônio só desenha um hiperplano: separa o espaço em dois lados. Isso basta para muitos problemas e falha no XOR, que precisa de duas fronteiras. Entender esse limite é entender por que a profundidade existe — empilhar camadas com não linearidade permite fronteiras de decisão arbitrariamente complexas."}]},{"id":"g-unidade-2","titulo":"Unidade 2 — Redes neurais profundas","descricao":"Empilhar camadas traz poder e traz problemas novos: gradiente que some, gradiente que explode, neurônio que morre. Esta unidade é sobre os dois lados.","topicos":[{"id":"u2-01","titulo":"MLP","prioridade":"fundamental","desc":"Empilhar camadas para modelar funções não lineares.","detalhe":"Multi-Layer Perceptron: várias camadas densas com ativação não linear entre elas. É a arquitetura base da qual todas as outras derivam. Sem a não linearidade entre camadas, qualquer pilha colapsa matematicamente numa única camada linear — a ativação é o que faz a profundidade valer alguma coisa."},{"id":"u2-02","titulo":"Terminologia","prioridade":"fundamental","desc":"Camadas, unidades ocultas, largura, profundidade, pesos, bias.","detalhe":"Largura é o número de neurônios por camada; profundidade é o número de camadas. Camada oculta é qualquer uma que não seja entrada nem saída. Fixe esse vocabulário porque toda discussão de arquitetura e todo paper o usam sem explicar."},{"id":"u2-03","titulo":"Teorema de aproximação universal","prioridade":"importante","desc":"Existência versus aprendizagem.","detalhe":"Uma rede de uma camada oculta suficientemente larga pode aproximar qualquer função contínua. O teorema é sedutor e enganoso: garante que a rede EXISTE, não que o gradiente descendente vai encontrá-la, nem que ela caberia na memória. Na prática, profundidade é muito mais eficiente em parâmetros do que largura."},{"id":"u2-04","titulo":"Benefícios da profundidade","prioridade":"importante","desc":"Reuso de features e eficiência de parâmetros.","detalhe":"Camadas profundas compõem features: as primeiras aprendem padrões simples e as seguintes combinam o que já foi aprendido. Esse reuso é por que uma rede profunda e estreita bate uma rasa e larga com o mesmo número de parâmetros — e por que transfer learning funciona, já que as camadas iniciais aprendem algo genérico."},{"id":"u2-05","titulo":"Contagem de parâmetros","prioridade":"importante","desc":"Cálculo do total por camada.","detalhe":"Uma camada densa de n entradas para m saídas tem n×m pesos mais m biases. Saber contar de cabeça te diz na hora se o modelo é grande demais para o seu dataset — a regra prática antiga pede pelo menos uma ordem de grandeza mais exemplos que parâmetros, e violá-la é receita de overfitting."},{"id":"u2-06","titulo":"Parâmetros vs hiperparâmetros","prioridade":"importante","desc":"O que o otimizador aprende versus o que você define.","detalhe":"Parâmetros (pesos, biases) são aprendidos pelo gradiente. Hiperparâmetros (learning rate, número de camadas, dropout, batch size) são definidos por você antes do treino. Hiperparâmetro deve ser escolhido pela VALIDAÇÃO, nunca pelo teste — ajustá-lo olhando o teste transforma a métrica final em ficção."},{"id":"u2-07","titulo":"Por que ativações","prioridade":"fundamental","desc":"Introduzem não linearidade.","detalhe":"A composição de funções lineares é linear. Sem ativação entre as camadas, uma rede de 50 camadas tem exatamente o mesmo poder expressivo de uma única camada. A ativação é o ingrediente mínimo que faz a profundidade existir."},{"id":"u2-08","titulo":"Função degrau","prioridade":"opcional","desc":"Histórica; gradiente zero, logo não treinável.","detalhe":"Devolve 0 ou 1 conforme um limiar. Derivada zero em todo lugar e indefinida no ponto de corte, o que a torna invisível para o gradiente descendente. Vale como contraste: é exatamente o defeito que a sigmoid veio corrigir."},{"id":"u2-09","titulo":"Sigmoid","prioridade":"importante","desc":"Suave, limitada, gradientes saturam nos extremos.","detalhe":"Derivada máxima de 0.25, no centro, e praticamente zero nos extremos. Empilhe dez camadas de sigmoid e o gradiente é multiplicado por fatores menores que 0.25 dez vezes — ele desaparece. É a causa histórica de redes profundas não treinarem antes da ReLU."},{"id":"u2-10","titulo":"Tanh","prioridade":"importante","desc":"Centrada em zero, gradientes ligeiramente melhores.","detalhe":"Sigmoid reescalada para (-1, 1). Ser centrada em zero ajuda porque mantém as ativações médias perto de zero, o que estabiliza as camadas seguintes. Ainda satura, então sofre do mesmo problema de gradiente, só que menos. Ainda aparece em RNNs e em LSTMs."},{"id":"u2-11","titulo":"ReLU","prioridade":"fundamental","desc":"Padrão: zero abaixo, identidade acima.","detalhe":"`max(0, x)`. Derivada 1 para entradas positivas, o que resolve o desaparecimento do gradiente, e é baratíssima de calcular. Foi a mudança técnica que viabilizou deep learning na prática. O preço é o neurônio morto: uma unidade que só recebe entradas negativas tem gradiente zero permanente e nunca mais se recupera."},{"id":"u2-12","titulo":"Leaky ReLU","prioridade":"importante","desc":"Pequena inclinação negativa; evita neurônios mortos.","detalhe":"Em vez de zerar os negativos, multiplica por algo pequeno como 0.01. Mantém um gradiente residual do lado negativo, então a unidade pode voltar à vida. Vale testar quando o diagnóstico indicar muitas unidades mortas; o ganho costuma ser modesto, não transformador."},{"id":"u2-13","titulo":"GELU","prioridade":"opcional","desc":"ReLU suavizado usado em transformers.","detalhe":"Versão suave da ReLU, ponderada pela probabilidade acumulada da gaussiana. É o padrão em BERT, GPT e quase todo transformer moderno. A suavidade ajuda a otimização em redes muito profundas; em MLPs pequenos a diferença para ReLU é desprezível."},{"id":"u2-14","titulo":"Escolha da ativação","prioridade":"importante","desc":"Regra prática por tipo de camada.","detalhe":"Camadas ocultas: ReLU por padrão, GELU em transformers. Camada de saída é determinada pela tarefa, não pela preferência: nenhuma ativação em regressão, sigmoid em binária, softmax em multiclasse, sigmoid por classe em multilabel. Aplicar softmax na saída e depois usar `CrossEntropyLoss` é erro duplo e comum."},{"id":"u2-15","titulo":"Inicialização de pesos","prioridade":"fundamental","desc":"Impacto no fluxo de sinais.","detalhe":"Inicializar tudo com zero faz todos os neurônios de uma camada computarem a mesma coisa e receberem o mesmo gradiente — eles nunca se diferenciam. Pesos grandes demais saturam as ativações; pequenos demais fazem o sinal desaparecer camada a camada. A inicialização certa mantém a variância do sinal estável ao longo da profundidade."},{"id":"u2-16","titulo":"Xavier/Glorot","prioridade":"importante","desc":"Para sigmoid e tanh.","detalhe":"Escala a variância inicial pelo número de entradas e saídas da camada, mantendo a variância do sinal constante na ida e na volta. Foi derivada assumindo ativação simétrica em torno de zero, por isso serve bem a tanh e sigmoid e serve mal a ReLU."},{"id":"u2-17","titulo":"Kaiming/He","prioridade":"importante","desc":"Para ReLU.","detalhe":"Corrige Xavier para o fato de a ReLU zerar metade das ativações, dobrando a variância inicial para compensar. É o padrão quando se usa ReLU e é o default do PyTorch em camadas lineares e convolucionais. Em redes profundas, a diferença entre Xavier e He é a diferença entre treinar e não treinar."},{"id":"u2-18","titulo":"Inicialização ortogonal","prioridade":"opcional","desc":"Preserva normas; útil para RNNs.","detalhe":"Inicializa a matriz de pesos como ortogonal, o que preserva a norma do vetor ao passar pela camada. Importa principalmente em RNNs, onde a mesma matriz é aplicada repetidamente ao longo da sequência e qualquer fator de escala diferente de 1 explode ou desaparece exponencialmente."},{"id":"u2-19","titulo":"Inicialização na prática","prioridade":"importante","desc":"Defaults do PyTorch e quando sobrescrever.","detalhe":"Os defaults do PyTorch são razoáveis e você raramente precisa mexer. As exceções que valem conhecer: zerar o bias da última camada para refletir a distribuição de classes acelera o início do treino em dados desbalanceados, e em detecção inicializa-se o bias da classificação para prever baixa probabilidade de objeto."},{"id":"u2-20","titulo":"Gradientes que desaparecem","prioridade":"importante","desc":"Diminuição ao retropropagar por muitas camadas.","detalhe":"O gradiente é um produto de derivadas ao longo das camadas; se cada fator é menor que 1, o produto tende a zero exponencialmente e as camadas iniciais param de aprender. Sintoma: loss desce um pouco e trava, com as primeiras camadas praticamente inalteradas. Soluções: ReLU, inicialização adequada, normalização e conexões residuais."},{"id":"u2-21","titulo":"Gradientes que explodem","prioridade":"importante","desc":"Crescimento sem controle e instabilidade.","detalhe":"O oposto: fatores maiores que 1 se acumulam e o gradiente vira um número enorme, produzindo um passo gigantesco que joga os pesos para o infinito. Sintoma: loss vira NaN de repente, muitas vezes no primeiro epoch. Soluções: clipping de gradiente, learning rate menor, warm-up."},{"id":"u2-22","titulo":"Clipping de gradiente","prioridade":"importante","desc":"Limitar a norma para evitar explosão.","detalhe":"Se a norma total do gradiente passa de um limite, reescale tudo proporcionalmente para caber nele. Preserva a direção e corta só o tamanho do passo. Praticamente obrigatório em RNNs e comum em transformers; `clip_grad_norm_` vai entre o backward e o step."},{"id":"u2-23","titulo":"Neurônios mortos","prioridade":"importante","desc":"Unidades ReLU sempre zero e como detectá-las.","detalhe":"Um neurônio ReLU que passou a receber só entradas negativas tem saída zero e gradiente zero para sempre — está morto. Detecte medindo a fração de ativações zero por camada ao longo de um epoch. Causas típicas: learning rate alto demais ou inicialização ruim. Mitigações: Leaky ReLU, LR menor."},{"id":"u2-24","titulo":"Mentalidade diagnóstica","prioridade":"importante","desc":"Mapear sintomas para causas raiz.","detalhe":"O hábito que mais diferencia um engenheiro de ML: tratar sintomas como pistas, não como azar. Loss não desce aponta para LR, bug no loop ou dados; loss vira NaN aponta para explosão ou log(0); treino bom e validação ruim aponta para overfitting ou vazamento. Antes de tudo isso, teste se o modelo consegue decorar 10 exemplos — se não consegue, há um bug, não um problema de capacidade."}]},{"id":"g-unidade-3","titulo":"Unidade 3 — Treinamento que funciona","descricao":"A distância entre ''o código roda'' e ''o modelo converge''. Otimizadores, learning rate e a disciplina de separar os dados antes de qualquer outra coisa.","topicos":[{"id":"u3-01","titulo":"Limitações do GD vanilla","prioridade":"fundamental","desc":"Taxa única e gradiente de todo o dataset, lento.","detalhe":"O gradiente descendente puro usa o dataset inteiro para dar um único passo, o que é inviável com milhões de exemplos, e aplica a mesma taxa a todos os parâmetros, mesmo quando uns precisam de passos grandes e outros de passos minúsculos. Cada otimizador que vem a seguir ataca uma dessas duas fraquezas."},{"id":"u3-02","titulo":"Taxonomia de otimizadores","prioridade":"importante","desc":"Como cada um resolve a fraqueza do anterior.","detalhe":"Vale memorizar a linhagem, porque ela é uma história de correções sucessivas: GD usa tudo e é lento → SGD usa mini-batch → Momentum suaviza o zig-zag → AdaGrad dá taxa por parâmetro mas morre → RMSProp corrige a morte → Adam junta momentum e RMSProp → AdamW conserta o weight decay do Adam. Entendendo a cadeia, você não precisa decorar as fórmulas."},{"id":"u3-03","titulo":"SGD","prioridade":"fundamental","desc":"Updates ruidosos em mini-batch.","detalhe":"Estima o gradiente com um punhado de exemplos em vez do dataset todo. O gradiente fica ruidoso, e o ruído é um recurso, não um defeito: ajuda a escapar de mínimos rasos e tem efeito regularizador. SGD com momentum, bem ajustado, ainda generaliza melhor que Adam em visão computacional."},{"id":"u3-04","titulo":"Efeito do tamanho do batch","prioridade":"importante","desc":"Ruído, velocidade e trade-off de generalização.","detalhe":"Batch grande dá gradiente mais estável e usa melhor a GPU, mas remove o ruído que ajuda a generalizar e costuma convergir para mínimos mais ''afiados''. Batch pequeno é mais ruidoso e mais lento por época, porém frequentemente generaliza melhor. Ao dobrar o batch, a regra prática é aumentar o learning rate proporcionalmente."},{"id":"u3-05","titulo":"Momentum","prioridade":"importante","desc":"Média móvel dos gradientes passados para reduzir zig-zag.","detalhe":"Acumula uma velocidade com os gradientes anteriores, como uma bola pesada descendo a encosta. Em vales estreitos, cancela as oscilações laterais e acelera na direção consistente. Valor típico: 0.9. É quase sempre um ganho grátis sobre SGD puro."},{"id":"u3-06","titulo":"AdaGrad","prioridade":"importante","desc":"Taxa de aprendizado por parâmetro que decai com gradiente acumulado.","detalhe":"Dá passos menores a parâmetros que já receberam muito gradiente e passos maiores a parâmetros raramente atualizados — excelente para features esparsas. O defeito fatal: a soma acumulada só cresce, então a taxa efetiva tende a zero e o treino para antes de convergir."},{"id":"u3-07","titulo":"RMSProp","prioridade":"importante","desc":"Média decrescente para evitar taxa zero.","detalhe":"Troca a soma acumulada do AdaGrad por uma média móvel exponencial, que esquece o passado distante. Com isso a taxa efetiva não morre e o algoritmo funciona em treinos longos e em objetivos não estacionários, como em RL."},{"id":"u3-08","titulo":"Adam","prioridade":"fundamental","desc":"Momentum mais RMSProp mais correção de viés. O padrão.","detalhe":"Mantém médias móveis do gradiente (primeiro momento) e do seu quadrado (segundo momento), com correção de viés para os primeiros passos. É o padrão razoável para começar qualquer coisa: funciona bem com pouco ajuste. Defaults que você vai ver em todo lugar: lr=1e-3, betas=(0.9, 0.999)."},{"id":"u3-09","titulo":"AdamW","prioridade":"importante","desc":"Adam com weight decay correto; padrão para transformers.","detalhe":"No Adam original, o weight decay era somado ao gradiente e acabava reescalado pelo segundo momento, o que o tornava inconsistente entre parâmetros. AdamW o aplica direto no passo de atualização, separado do gradiente. A diferença é pequena no código e relevante no resultado — é o padrão em transformers."},{"id":"u3-10","titulo":"Escolha do otimizador","prioridade":"importante","desc":"Diretrizes por tipo de modelo.","detalhe":"AdamW para transformers e NLP; SGD com momentum para CNNs de visão quando você tem orçamento para ajustar o schedule, porque costuma terminar melhor; Adam para protótipo rápido de qualquer coisa. Otimizador é o hiperparâmetro que você deve ajustar por último — learning rate e dados importam muito mais."},{"id":"u3-11","titulo":"Taxa de aprendizado","prioridade":"fundamental","desc":"Hiperparâmetro mais crítico e estratégias de ajuste.","detalhe":"Se você só puder ajustar uma coisa, ajuste esta. Alta demais: loss oscila ou vira NaN. Baixa demais: loss desce reto e lento, sem nunca chegar. Busque em escala logarítmica (1e-2, 1e-3, 1e-4), não linear. O LR range test — subir a taxa gradualmente e plotar a loss — encontra a faixa boa em poucos minutos."},{"id":"u3-12","titulo":"Scheduler de LR","prioridade":"importante","desc":"Ajuste dinâmico da taxa durante o treinamento.","detalhe":"Taxa constante é um compromisso ruim: você quer passos grandes no começo, para explorar, e pequenos no fim, para assentar no mínimo. Schedulers automatizam essa redução e costumam valer mais pontos de métrica do que trocar de arquitetura."},{"id":"u3-13","titulo":"Warm-up linear","prioridade":"importante","desc":"Início suave para não quebrar redes recém-inicializadas.","detalhe":"Sobe o learning rate de quase zero até o valor alvo ao longo das primeiras centenas de passos. Necessário porque, no início, as estimativas de momento do Adam são ruins e os pesos são aleatórios — um passo grande nesse momento desestabiliza tudo. Padrão em transformers."},{"id":"u3-14","titulo":"Cosine annealing","prioridade":"importante","desc":"Decaimento suave até quase zero.","detalhe":"Reduz a taxa seguindo meia onda de cosseno, do valor inicial até perto de zero no fim do treino. Suave, sem saltos, e sem hiperparâmetros além da duração total. Combinado com warm-up, é a receita padrão moderna."},{"id":"u3-15","titulo":"Step decay","prioridade":"opcional","desc":"Quedas discretas da taxa.","detalhe":"Divide a taxa por um fator em épocas pré-definidas (por exemplo, por 10 nas épocas 30 e 60). Abordagem clássica, ainda usada em reprodução de papers antigos de visão. Funciona, mas exige escolher os pontos de queda à mão, o que o cosseno evita."},{"id":"u3-16","titulo":"ReduceLROnPlateau","prioridade":"importante","desc":"Reduz LR quando a validação estagna.","detalhe":"Em vez de seguir um cronograma fixo, observa uma métrica de validação e reduz a taxa quando ela para de melhorar por N épocas. Adaptativo e difícil de errar, é uma boa escolha quando você não sabe de antemão quantas épocas o treino vai durar."},{"id":"u3-17","titulo":"Divisão de dados","prioridade":"fundamental","desc":"Treino, validação e teste; nunca tocar no teste antes do fim.","detalhe":"Treino ajusta os pesos, validação escolhe hiperparâmetros, teste estima o desempenho real — uma única vez, no fim. Toda decisão tomada olhando o teste contamina a estimativa e você perde a única medida honesta que tinha. Divida ANTES de normalizar, de imputar faltantes ou de qualquer estatística global, senão há vazamento."},{"id":"u3-18","titulo":"Checkpointing","prioridade":"importante","desc":"Salvar estado do modelo e do otimizador; manter o melhor.","detalhe":"Salve o `state_dict` do modelo E do otimizador — sem o segundo, retomar um treino interrompido reinicia os momentos do Adam e produz um salto na loss. Guarde o melhor checkpoint segundo a validação, não o último: o último quase sempre já começou a sobreajustar."},{"id":"u3-19","titulo":"Reprodutibilidade","prioridade":"importante","desc":"Sementes, operações determinísticas e por que execuções ainda divergem.","detalhe":"Fixe as seeds de Python, NumPy e torch, e lembre que os workers do DataLoader têm as suas. Mesmo assim, kernels de GPU somam em ordem não determinística e `torch.use_deterministic_algorithms(True)` custa desempenho. Conclusão prática: espere variação entre execuções e reporte média e desvio de várias seeds, não um número."}]},{"id":"g-unidade-4","titulo":"Unidade 4 — Generalização","descricao":"O modelo não existe para acertar o treino; existe para acertar o que nunca viu. Esta unidade é sobre a diferença entre as duas coisas e como reduzi-la.","topicos":[{"id":"u4-01","titulo":"Definição de generalização","prioridade":"fundamental","desc":"Desempenho em dados nunca vistos.","detalhe":"A única métrica que importa é a de dados que o modelo não viu no treino. Erro de treino baixo é condição necessária e completamente insuficiente — um modelo que memoriza tem erro de treino zero e serve para nada. Todo o resto desta unidade existe para fechar a diferença entre as duas medidas."},{"id":"u4-02","titulo":"Leitura de curvas de loss","prioridade":"fundamental","desc":"Diagnóstico de overfit e underfit.","detalhe":"Plote treino e validação na mesma figura, sempre. As duas altas e juntas: underfitting, o modelo é fraco ou o treino é curto. Treino caindo e validação subindo: overfitting, e o ponto onde a validação vira é onde parar. Validação ABAIXO do treino: suspeite de vazamento ou de dropout ativo distorcendo a comparação."},{"id":"u4-03","titulo":"Overfitting","prioridade":"fundamental","desc":"Memoriza o treino e falha no teste.","detalhe":"O modelo aprende o ruído específico dos seus exemplos em vez do padrão. Aparece quando há capacidade demais para dados de menos. As três saídas, em ordem de retorno: mais dados, mais regularização, menos capacidade. Mais dados quase sempre ganha das outras duas."},{"id":"u4-04","titulo":"Underfitting","prioridade":"fundamental","desc":"Modelo muito simples ou pouco treinado.","detalhe":"O modelo não consegue nem ajustar o treino. Causas: capacidade insuficiente, learning rate errado, treino curto demais, regularização excessiva — ou simplesmente um bug. O teste decisivo: tente fazer o modelo decorar um batch de 10 exemplos; se não conseguir chegar a loss quase zero, existe um bug no código, não um problema de capacidade."},{"id":"u4-05","titulo":"Trade-off viés-variância","prioridade":"importante","desc":"Fontes de erro.","detalhe":"Viés é erro por suposições simples demais (underfitting); variância é sensibilidade excessiva aos dados específicos de treino (overfitting); e há um ruído irredutível que nenhum modelo elimina. A moldura clássica diz que reduzir um aumenta o outro — útil como intuição, ainda que deep learning moderno a complique (ver double descent)."},{"id":"u4-06","titulo":"Complexidade vs tamanho do dataset","prioridade":"importante","desc":"Regra prática de dimensionamento.","detalhe":"Quanto mais parâmetros, mais dados são necessários. A regra antiga pede pelo menos 10 exemplos por parâmetro, e deep learning moderno a viola rotineiramente com a ajuda de regularização e pré-treino. O ponto prático permanece: com dataset pequeno, prefira modelo pequeno ou transfer learning — treinar do zero vai sobreajustar."},{"id":"u4-07","titulo":"Maldição da dimensionalidade","prioridade":"importante","desc":"Escassez de dados com muitas features.","detalhe":"Conforme a dimensão cresce, o volume do espaço cresce exponencialmente e os dados ficam esparsos: todos os pontos acabam aproximadamente à mesma distância uns dos outros, o que destrói métodos baseados em distância como KNN. É a motivação de redução de dimensionalidade e de aprender representações densas."},{"id":"u4-08","titulo":"Double descent","prioridade":"opcional","desc":"Por que modelos gigantes podem generalizar bem após a zona ruim.","detalhe":"A curva clássica em U do erro de teste ganha uma segunda descida: ao passar do ponto de interpolação (parâmetros suficientes para memorizar o treino), o erro de teste volta a cair. É parte da explicação de por que modelos enormes funcionam, contrariando a intuição de viés-variância."},{"id":"u4-09","titulo":"Limites de complexidade amostral","prioridade":"opcional","desc":"Estimativas da quantidade de dados necessária.","detalhe":"A teoria (dimensão VC, limites PAC) tenta estimar quantos exemplos bastam para garantir certa generalização. Os limites são corretos e, para redes profundas, tão frouxos que não ajudam a decidir nada na prática. Vale como cultura, não como ferramenta."},{"id":"u4-10","titulo":"Regularização","prioridade":"fundamental","desc":"Técnicas que trocam ajuste de treino por melhor generalização.","detalhe":"O guarda-chuva de tudo que piora o treino de propósito para melhorar o teste: penalidades nos pesos, dropout, augmentation, early stopping, label smoothing. Aplique quando houver evidência de overfitting nas curvas — regularizar um modelo que já está em underfitting só piora."},{"id":"u4-11","titulo":"Weight decay (L2)","prioridade":"fundamental","desc":"Encolher pesos a cada passo.","detalhe":"Soma uma penalidade proporcional ao quadrado dos pesos, empurrando todos em direção a zero sem zerar nenhum. Resultado: função mais suave, menos sensível a variações pequenas na entrada. É equivalente a assumir um prior gaussiano sobre os pesos. Valores típicos: 1e-4 a 1e-2."},{"id":"u4-12","titulo":"Regularização L1","prioridade":"importante","desc":"Sparsificar pesos e selecionar features.","detalhe":"Penaliza o valor absoluto, e a geometria dessa penalidade empurra pesos para exatamente zero, não apenas para perto. O efeito é seleção automática de features: o que sobrou com peso não-nulo é o que importa. Use quando interpretabilidade ou esparsidade forem objetivos; para pura generalização, L2 costuma ir melhor."},{"id":"u4-13","titulo":"Dropout","prioridade":"importante","desc":"Mascaramento aleatório de unidades durante o treino.","detalhe":"Desliga aleatoriamente uma fração das unidades a cada passo, impedindo que a rede dependa de um caminho específico — funciona como um ensemble implícito. Taxas típicas: 0.1 a 0.5. Crítico: dropout só age em treino; esquecer `model.eval()` na validação faz as métricas parecerem piores e aleatórias."},{"id":"u4-14","titulo":"Max-norm","prioridade":"opcional","desc":"Limitar a norma de cada vetor de peso.","detalhe":"Impõe um teto rígido à norma dos pesos de cada neurônio, reprojetando quando ultrapassa. Historicamente usado junto com dropout, permitindo learning rates maiores sem divergência. Pouco comum hoje, superado por weight decay mais normalização."},{"id":"u4-15","titulo":"Label smoothing","prioridade":"importante","desc":"Suavizar alvos para evitar sobre-confiança.","detalhe":"Em vez de pedir probabilidade 1.0 na classe certa, pede 0.9 e distribui 0.1 entre as outras. Impede que os logits cresçam indefinidamente em busca de uma certeza impossível, melhora a calibração e dá um pequeno ganho de acurácia. Valor típico: 0.1. Especialmente útil quando os rótulos têm ruído."},{"id":"u4-16","titulo":"Early stopping","prioridade":"importante","desc":"Parar quando a validação deixa de melhorar.","detalhe":"Monitora a validação e interrompe depois de N épocas sem melhora (a paciência), restaurando o melhor checkpoint. É a regularização de melhor custo-benefício que existe: economiza computação e evita overfitting ao mesmo tempo. Paciência pequena demais corta o treino cedo, porque a validação oscila naturalmente."},{"id":"u4-17","titulo":"Busca de hiperparâmetros","prioridade":"importante","desc":"Grade, aleatória e bayesiana; o que buscar primeiro.","detalhe":"Busca aleatória bate busca em grade com o mesmo orçamento, porque poucos hiperparâmetros realmente importam e a aleatória cobre mais valores distintos dos que importam. Métodos bayesianos (Optuna) usam os resultados anteriores para escolher o próximo ponto. Ordem de prioridade: learning rate, depois arquitetura e regularização, depois o resto. E sempre pela validação."}]},{"id":"g-unidade-5","titulo":"Unidade 5 — Avaliação e diagnóstico","descricao":"A unidade que mais separa quem sabe de quem acha que sabe. Treinar é fácil; medir honestamente, e desconfiar do próprio número, é o trabalho de verdade.","topicos":[{"id":"u5-01","titulo":"Confiar nas métricas","prioridade":"importante","desc":"Formas como scores podem enganar.","detalhe":"Um número alto pode vir de vazamento, de classe desbalanceada, de validação contaminada, de conjunto de teste pequeno demais ou de uma métrica que não reflete o objetivo. Antes de comemorar, pergunte: qual é o baseline trivial? Se prever sempre a classe majoritária dá 94%, seu 95% não significa nada."},{"id":"u5-02","titulo":"Contaminação da validação","prioridade":"importante","desc":"Over-tuning na validação.","detalhe":"Cada decisão tomada olhando a validação usa um pouco da informação dela. Depois de cem experimentos, você implicitamente ajustou o modelo ao conjunto de validação e ele deixou de ser uma estimativa imparcial. É exatamente para isso que existe o conjunto de teste separado, tocado uma única vez."},{"id":"u5-03","titulo":"Leakage entre treino e teste","prioridade":"importante","desc":"Fluxo acidental de informação e armadilhas comuns.","detalhe":"Informação do teste chegando ao treino produz resultado bom demais que desaba em produção. As fontes clássicas: normalizar antes de dividir; duplicatas nos dois conjuntos; dividir aleatoriamente dados agrupados (várias fotos do mesmo paciente); e, em série temporal, usar futuro para prever passado. Divida por grupo e por tempo quando for o caso."},{"id":"u5-04","titulo":"Cross-validation","prioridade":"importante","desc":"Rotação das partições de validação; cada exemplo avaliado uma vez.","detalhe":"Divide os dados em K partes, treina K vezes usando cada parte como validação, e devolve média e desvio. Dá uma estimativa muito mais estável que uma divisão única, e o desvio diz se a diferença entre dois modelos é real ou ruído. Custa K treinos, o que a torna comum em dado tabular e rara em deep learning."},{"id":"u5-05","titulo":"CV estratificado","prioridade":"importante","desc":"Preserva as proporções de classes.","detalhe":"Garante que cada fold tenha a mesma distribuição de classes do conjunto completo. Sem isso, com classes raras, um fold pode não conter nenhum exemplo positivo e a métrica daquele fold vira indefinida ou absurda. É o padrão em classificação e custa nada."},{"id":"u5-06","titulo":"Quando não usar CV","prioridade":"opcional","desc":"Séries temporais, dataset massivo e dados agrupados.","detalhe":"Em série temporal, CV aleatório treina com o futuro — use validação com janela deslizante. Com dataset enorme, uma divisão única já é estatisticamente estável e K treinos são desperdício. Com dados agrupados, use GroupKFold para manter o grupo inteiro de um lado só."},{"id":"u5-07","titulo":"Métricas de classificação","prioridade":"fundamental","desc":"Panorama geral.","detalhe":"Tudo deriva dos quatro números da matriz de confusão: verdadeiro positivo, falso positivo, verdadeiro negativo, falso negativo. Cada métrica é uma razão diferente entre eles, e escolher a métrica é decidir qual tipo de erro você está disposto a cometer."},{"id":"u5-08","titulo":"Acurácia","prioridade":"importante","desc":"Quando é enganosa, em especial sob desbalanceamento.","detalhe":"Fração de acertos. Intuitiva e perigosa: num problema com 1% de positivos, prever sempre ''negativo'' dá 99% de acurácia e detecta zero casos. Só use quando as classes estão razoavelmente equilibradas E os dois tipos de erro custam o mesmo — o que é raro."},{"id":"u5-09","titulo":"Precisão e recall","prioridade":"fundamental","desc":"Definições e trade-off.","detalhe":"Precisão: dos que previ positivos, quantos eram. Recall: dos positivos reais, quantos peguei. Movem-se em sentidos opostos conforme o limiar. A escolha é de domínio, não técnica: triagem médica prioriza recall (perder um doente é pior que um alarme falso); filtro de spam prioriza precisão (marcar um e-mail legítimo como spam é pior)."},{"id":"u5-10","titulo":"F1-score","prioridade":"importante","desc":"Média harmônica de precisão e recall.","detalhe":"A média harmônica pune o desequilíbrio: precisão 1.0 com recall 0.0 dá F1 zero, enquanto a média aritmética daria 0.5. Útil como número único de comparação, mas assume que precisão e recall valem o mesmo — se não valerem no seu domínio, F1 esconde a decisão em vez de informá-la."},{"id":"u5-11","titulo":"Matriz de confusão","prioridade":"fundamental","desc":"Detalhamento completo por classe.","detalhe":"A primeira coisa a olhar depois de treinar, antes de qualquer métrica agregada. Mostra QUAIS classes se confundem com quais, e esse padrão aponta a causa: classes visualmente parecidas, rótulos inconsistentes, ou classe com poucos exemplos. Um número agregado nunca diz isso."},{"id":"u5-12","titulo":"Curva ROC e AUC","prioridade":"importante","desc":"Desempenho em todos os thresholds.","detalhe":"Plota taxa de verdadeiros positivos contra falsos positivos variando o limiar. AUC é a área sob a curva e tem interpretação direta: a probabilidade de o modelo dar score maior a um positivo aleatório do que a um negativo aleatório. 0.5 é aleatório. Avalia o ranqueamento, independente do limiar escolhido."},{"id":"u5-13","titulo":"AUC-PR","prioridade":"importante","desc":"Mais adequado para classes raras.","detalhe":"Área sob a curva precisão-recall. Com classes muito desbalanceadas, ROC-AUC parece otimista porque a taxa de falso positivo tem um denominador enorme de negativos; AUC-PR foca nos positivos e expõe a dificuldade real. Com menos de 5% de positivos, prefira AUC-PR."},{"id":"u5-14","titulo":"MCC","prioridade":"opcional","desc":"Score balanceado para dados desbalanceados.","detalhe":"Coeficiente de correlação de Matthews: usa as quatro células da matriz de confusão e varia de -1 a +1. Só fica alto quando o modelo vai bem nas duas classes, o que o torna mais honesto que F1 sob desbalanceamento severo. Pouco usado, mas difícil de enganar."},{"id":"u5-15","titulo":"Métricas de regressão","prioridade":"fundamental","desc":"R², MAPE e outras; prós e contras.","detalhe":"RMSE está na unidade do alvo e pune erros grandes; MAE é robusta e lê-se como erro típico; R² diz quanta variância foi explicada em relação a prever sempre a média, e pode ser negativo quando o modelo é pior que essa média; MAPE é percentual e intuitivo, mas explode quando o valor real se aproxima de zero."},{"id":"u5-16","titulo":"Escolha da métrica","prioridade":"importante","desc":"Alinhar ao objetivo de negócio.","detalhe":"Escolha a métrica ANTES de treinar, derivada do custo real de cada tipo de erro. Métrica escolhida depois de ver os resultados é a que mais favorece o que você já obteve. Quando os custos são assimétricos e conhecidos, a métrica certa pode ser custo esperado em reais, não F1."},{"id":"u5-17","titulo":"Checagem de fluxo de gradiente","prioridade":"importante","desc":"Garantir que os gradientes chegam a todas as camadas.","detalhe":"Depois do backward, percorra os parâmetros e imprima a norma do gradiente por camada. Normas zeradas nas camadas iniciais indicam desaparecimento ou um `detach()` acidental; normas enormes indicam explosão iminente; `None` indica parâmetro desconectado do grafo. Cinco linhas de código que resolvem bugs de horas."},{"id":"u5-18","titulo":"Checklist para NaN","prioridade":"importante","desc":"Ordem típica de causas.","detalhe":"Percorra nesta ordem: learning rate alto demais (a mais comum); log(0) ou divisão por zero na loss; dados de entrada já contendo NaN ou infinito; sqrt de negativo; gradiente explodindo. `torch.autograd.set_detect_anomaly(True)` aponta a operação exata que gerou o NaN, ao custo de lentidão."},{"id":"u5-19","titulo":"Métricas de eficiência","prioridade":"importante","desc":"Contagem de parâmetros, FLOPs, latência, taxa e tamanho do modelo.","detalhe":"Acurácia não é a única restrição de um sistema real. Meça latência (tempo de uma predição), throughput (predições por segundo), memória e tamanho em disco. FLOPs é uma estimativa teórica e correlaciona mal com tempo real — meça no hardware alvo, descartando as primeiras iterações de warm-up e sincronizando a GPU."},{"id":"u5-20","titulo":"Lançamento, monitoramento e manutenção","prioridade":"importante","desc":"Considerações pós-deploy.","detalhe":"O modelo começa a envelhecer no dia em que entra no ar: a distribuição dos dados muda (data drift) e a relação entre entrada e alvo muda (concept drift). Monitore a distribuição das entradas e das predições, porque o rótulo verdadeiro costuma chegar tarde ou nunca. Planeje retreino periódico e um caminho de rollback."},{"id":"u5-21","titulo":"Metodologia prática","prioridade":"importante","desc":"Baseline, experimentos e modelo em produção.","detalhe":"A sequência que funciona: defina a métrica e separe os dados; estabeleça um baseline trivial e depois um modelo simples; só então aumente a complexidade, mudando uma coisa por vez e registrando tudo. Se um passo não melhora a validação de forma clara, descarte-o. A maior parte do ganho real vem de dados melhores, não de modelos maiores."}]}]},{"id":"especializacao","numero":5,"titulo":"Especialização","objetivo":"Escolher um domínio e aprofundar, mantendo o hábito das três dimensões: estudar teoria, implementar um projeto pequeno e validar em tarefa real.","descricao":"Escolha UM domínio. A tentação de estudar vários ao mesmo tempo produz conhecimento raso em todos — e, como os fundamentos da Etapa 4 são comuns a todos eles, migrar depois é barato. Profundidade em um domínio é o que gera projeto defensável e contratação; amplitude vem com o tempo, sozinha. O critério de escolha mais útil não é qual parece mais interessante, e sim a qual tipo de dado você tem acesso real para construir algo seu.","preRequisitos":"Etapa 4","duracao":"contínuo","grupos":[{"id":"g-dominios","titulo":"Escolha um domínio","descricao":"Os quatro caminhos mais comuns. Os dois primeiros concentram a maior parte das vagas; os dois últimos são mais nichados e mais acadêmicos.","topicos":[{"id":"es-01","titulo":"NLP","prioridade":"importante","desc":"Tokenização, embeddings, atenção e transformers; fine-tuning de modelos pré-treinados.","detalhe":"A progressão típica: tokenização (como texto vira números, e por que BPE existe) → embeddings (palavras como vetores com geometria significativa) → atenção e transformers → fine-tuning de modelos pré-treinados. Hoje quase nenhum trabalho prático treina do zero: você parte de um modelo pronto e adapta, o que torna a habilidade central avaliar e não arquitetar. É também a porta de entrada para engenharia de LLMs, RAG e agentes — área que você já começou a mapear nas suas notas de AI Engineer."},{"id":"es-02","titulo":"Visão computacional","prioridade":"importante","desc":"Convoluções, CNNs modernas, detecção e segmentação.","detalhe":"Progressão: convolução e campo receptivo → CNNs modernas (ResNet, EfficientNet) → transfer learning → detecção (YOLO, DETR) → segmentação (U-Net, SAM) → otimização para tempo real. Você já tem um roadmap dedicado e bem mais detalhado para isto no vault, em Computer Vision/Docs — este nó serve só para marcar a escolha. Uma observação que vale para os dois roadmaps: anotar um dataset próprio ensina mais sobre o problema do que treinar mais um modelo."},{"id":"es-03","titulo":"Reinforcement learning","prioridade":"opcional","desc":"MDPs, value e policy methods, exploração versus explotação.","detalhe":"Aprender por tentativa e recompensa, sem rótulo certo. Conceitos centrais: processo de decisão de Markov, funções de valor, gradiente de política, e o dilema entre explorar o desconhecido e explotar o que já funciona. Avise-se de que RL é notoriamente instável e caro em amostras — resultados variam muito entre seeds. Fora de jogos e robótica, a aplicação mais relevante hoje é RLHF, o alinhamento de modelos de linguagem por preferência humana."},{"id":"es-04","titulo":"Continual learning","prioridade":"opcional","desc":"Aprendizado incremental e esquecimento catastrófico.","detalhe":"Como fazer um modelo aprender tarefas novas sem apagar as antigas. O fenômeno central é o esquecimento catastrófico: treinar na tarefa B degrada drasticamente o desempenho na tarefa A. É uma área mais de pesquisa que de produção, onde a solução padrão da indústria continua sendo retreinar do zero com todos os dados. Relevante quando retreinar é proibitivo ou quando os dados antigos não podem ser retidos, por regulação."}]},{"id":"g-habito","titulo":"Hábito das três dimensões","descricao":"O critério para marcar qualquer tópico deste roadmap como feito. Vale para os 156, não só para esta etapa.","topicos":[{"id":"es-05","titulo":"Teoria","prioridade":"fundamental","desc":"Explicar o conceito com suas próprias palavras, sem consultar notas.","detalhe":"O teste honesto é explicar em voz alta, sem olhar nada, para alguém que não conhece o assunto. A sensação de entendimento ao ler é notoriamente não confiável — reconhecer não é lembrar. Escrever a explicação com suas palavras, aqui ou no vault, expõe os buracos imediatamente."},{"id":"es-06","titulo":"Prática","prioridade":"fundamental","desc":"Implementar um exemplo mínimo funcional em código.","detalhe":"Implemente a versão menor possível que funcione de ponta a ponta, sem copiar. Código executável não admite entendimento parcial: ou o shape bate ou não bate. Para conceitos matemáticos, o padrão de ouro é implementar em NumPy e conferir contra a função pronta da biblioteca — quando os dois batem, você entendeu."},{"id":"es-07","titulo":"Validação","prioridade":"fundamental","desc":"Interpretar o resultado de um experimento e justificar as escolhas de design.","detalhe":"A dimensão que quase todo mundo pula. Rodar e obter um número não é validar: validar é saber dizer se o número é confiável, o que ele esconde, e por que você escolheu esta métrica e não outra. Pergunte sempre: qual é o baseline trivial? Qual é a variação entre seeds? Em que condições isto falharia?"}]}]}]},"PROJETOS":{"python":["Criar uma CLI que lê um CSV, calcula estatísticas básicas e grava um relatório JSON."],"matematica":["Implementar multiplicação de matrizes e autovalores usando apenas NumPy, validando com matrizes conhecidas."],"pytorch":["Reimplementar um MLP de duas camadas do zero e treinar no dataset Iris."],"fundamentos":["Replicar um tutorial de classificação binária (Titanic, por exemplo) com regressão logística e reportar precisão, recall e F1.","Treinar o mesmo modelo com e sem dropout e weight decay, comparando as curvas de validação.","Realizar CV estratificado de 5 folds em um dataset multiclasse e plotar ROC-AUC por classe."],"especializacao":["Escolher um dataset público (CIFAR-10 para visão ou SST-2 para NLP) e fazer fine-tuning de um transformer pré-treinado, avaliando com métricas adequadas."]},"RECURSOS":[{"etapa":"python","titulo":"Tutorial oficial de Python","url":"https://docs.python.org/3/tutorial/","nota":"Referência oficial"},{"etapa":"python","titulo":"Ambientes virtuais em Python","url":"https://realpython.com/python-virtual-environments/","nota":"venv e conda"},{"etapa":"python","titulo":"Documentação do NumPy","url":"https://numpy.org/doc/","nota":"Biblioteca fundamental de arrays"},{"etapa":"python","titulo":"Documentação do pandas","url":"https://pandas.pydata.org/docs/","nota":"Manipulação de dados"},{"etapa":"python","titulo":"scikit-learn","url":"https://scikit-learn.org/stable/","nota":"Algoritmos clássicos de ML"},{"etapa":"matematica","titulo":"Linear Algebra — Gilbert Strang (MIT OCW)","url":"https://ocw.mit.edu/courses/18-06-linear-algebra-spring-2010/","nota":"Álgebra linear"},{"etapa":"matematica","titulo":"Calculus — Khan Academy","url":"https://www.khanacademy.org/math/calculus-1","nota":"Cálculo"},{"etapa":"matematica","titulo":"Probability and Statistics — DeGroot & Schervish","url":null,"nota":"Probabilidade"},{"etapa":"matematica","titulo":"Elements of Information Theory — Cover & Thomas","url":null,"nota":"Teoria da informação"},{"etapa":"matematica","titulo":"Truque log-sum-exp","url":"https://stackoverflow.com/questions/42126924/","nota":"Estabilidade numérica"},{"etapa":"pytorch","titulo":"Tutoriais oficiais do PyTorch","url":"https://pytorch.org/tutorials/","nota":"Tensores e deep learning"},{"etapa":"fundamentos","titulo":"Deep Learning — Goodfellow, Bengio, Courville","url":null,"nota":"Referência completa"},{"etapa":"fundamentos","titulo":"Pattern Recognition and Machine Learning — Bishop","url":null,"nota":"Leitura adicional"},{"etapa":"fundamentos","titulo":"Hands-On Machine Learning — Géron","url":null,"nota":"Leitura adicional"},{"etapa":"especializacao","titulo":"Attention Is All You Need (Vaswani et al., 2017)","url":"https://arxiv.org/abs/1706.03762","nota":"Transformers"},{"etapa":"especializacao","titulo":"CS231n — Stanford","url":"http://cs231n.stanford.edu/","nota":"Visão computacional, CNNs"},{"etapa":"especializacao","titulo":"Reinforcement Learning — Sutton & Barto (2ª ed.)","url":null,"nota":"RL"}],"LEGENDA":[{"chave":"fundamental","rotulo":"Fundamental","desc":"Ordem estrita. Não pule."},{"chave":"importante","rotulo":"Importante","desc":"Recomendado, mas a ordem é flexível."},{"chave":"opcional","rotulo":"Opcional","desc":"Pule sem culpa e volte depois."}],"ESTADOS":[{"chave":"pendente","rotulo":"Pendente"},{"chave":"estudando","rotulo":"Estudando"},{"chave":"feito","rotulo":"Feito"},{"chave":"pulado","rotulo":"Pulado"}],"CRITERIOS":["Explicar o conceito com suas próprias palavras, sem consultar notas.","Implementar um exemplo mínimo funcional em código.","Interpretar o resultado de um experimento e justificar as escolhas de design.","Depurar um treinamento que falhou usando a lista de diagnóstico."]}'::jsonb),
  ('cv', 'Computer Vision', '#1c6e51',
   '[[26,212],[62,196],[50,166],[88,150],[72,122],[114,108],[98,80],[142,70],[134,46],[182,52],[198,86],[230,70],[252,102],[282,78]]'::jsonb, 10,
   '{"ROADMAP":{"id":"cv","titulo":"Computer Vision","subtitulo":"Treze iterações, da visão clássica ao capstone","fonte":{"rotulo":"Advanced Computer Vision Engineer Roadmap","url":"https://medium.com/cvrealtime/advanced-computer-vision-engineer-roadmap-2024-aee32bfa14c1","consultadoEm":"2026-09-16"},"etapas":[{"id":"pre","numero":0,"titulo":"Pré-requisitos","objetivo":"Ter Python e NumPy sob controle e conseguir ler, escrever e exibir imagem e vídeo.","descricao":"Esta etapa não é sobre visão: é sobre não tropeçar na ferramenta. O ponto de virada é parar de pensar em imagem como \"arquivo\" e passar a pensar nela como uma matriz `H × W × C` de inteiros de 0 a 255 — porque é isso que todo o resto do roadmap manipula. Se você já programa em Python, o trabalho real aqui é o NumPy vetorizado: um laço `for` sobre pixels em Python é entre 50 e 500 vezes mais lento que a operação equivalente em NumPy, e essa diferença decide se o seu protótipo roda em tempo real ou não.","preRequisitos":"Nenhum","duracao":null,"criterios":["Você explica por que o OpenCV usa BGR e o que quebra quando você mistura com bibliotecas em RGB.","Você percorre e altera pixels sem laços Python explícitos, usando apenas NumPy.","Você recria seu ambiente do zero em uma máquina limpa em menos de 10 minutos."],"grupos":[{"id":"cv-g-py","titulo":"Python","descricao":"O suficiente para escrever código que você mesmo consiga manter daqui a três meses.","topicos":[{"id":"cv-pre-01","titulo":"Sintaxe e controle de fluxo","prioridade":"fundamental","desc":"Variáveis, operadores, condicionais, laços (`for`, `while`, `break`, `continue`, `else`).","detalhe":"O `else` de um laço é o detalhe que quase todo mundo desconhece: ele roda quando o laço termina SEM `break`, o que é exatamente o padrão \"procurei e não achei\". Fora isso, o que importa aqui é fluência: você não deveria estar pensando em sintaxe enquanto depura um pipeline de visão."},{"id":"cv-pre-02","titulo":"Estruturas de dados","prioridade":"fundamental","desc":"Listas, strings, dicionários, tuplas e sets.","detalhe":"A escolha da estrutura é escolha de complexidade: buscar em lista é O(n), em set ou dict é O(1). Em visão isso aparece ao cruzar IDs de detecção entre frames — com lista, o tracking fica quadrático no número de objetos. Tuplas são imutáveis e por isso podem ser chave de dicionário, o que é útil para indexar por coordenada."},{"id":"cv-pre-03","titulo":"Funções, retorno e escopo","prioridade":"fundamental","desc":"`return`, recursão e regras de escopo.","detalhe":"A armadilha clássica de Python é o argumento padrão mutável: `def f(x, acc=[])` reusa a MESMA lista entre chamadas. Use `None` como padrão e crie a lista dentro. Em visão isso morde quando você acumula detecções entre frames sem perceber."},{"id":"cv-pre-04","titulo":"Arquivos e exceções","prioridade":"fundamental","desc":"Manipulação de arquivos e tratamento de exceções.","detalhe":"Use sempre `with open(...)` para que o arquivo feche mesmo se der erro no meio. Em exceções, capture o tipo específico (`FileNotFoundError`), não `except Exception`: um `except` genérico engole o erro de programação junto com o erro esperado e você perde horas achando que o arquivo é que estava errado."},{"id":"cv-pre-05","titulo":"Orientação a objetos","prioridade":"importante","desc":"Classes, herança e composição.","detalhe":"Em visão você vai escrever classes o tempo todo — `Dataset` do PyTorch, trackers, pipelines. A regra prática: prefira composição a herança. Um `Pipeline` que CONTÉM um detector e um tracker é mais fácil de trocar e testar do que um que HERDA de ambos."},{"id":"cv-pre-06","titulo":"Recursos avançados","prioridade":"importante","desc":"Decorators, generators e context managers.","detalhe":"Generators (`yield`) são o que permite processar um vídeo de 2 horas sem carregar tudo na memória: você entrega um frame por vez. Decorators aparecem como `@torch.no_grad()` e em cronômetros de perfilagem. Context managers (`with`) garantem que a câmera é liberada mesmo quando o código estoura no meio."},{"id":"cv-pre-07","titulo":"Ambientes virtuais","prioridade":"fundamental","desc":"`venv` ou `uv` e gerenciamento de dependências.","detalhe":"Visão computacional é a área onde o inferno de dependências é mais real: versão de CUDA, de PyTorch, de OpenCV e de driver precisam combinar. Um ambiente por projeto, com as versões fixadas em arquivo, é o que torna o seu trabalho reproduzível — e é literalmente um dos critérios de domínio desta etapa."},{"id":"cv-pre-08","titulo":"NumPy","prioridade":"fundamental","desc":"Arrays, shapes, slicing, broadcasting e operações vetorizadas.","detalhe":"É a etapa mais importante desta lista. Uma imagem É um array NumPy, então recortar uma região é `img[y1:y2, x1:x2]` e clarear é `img + 30`. Broadcasting é o que permite aplicar um valor por canal sem laço. Atenção: slicing devolve uma VISTA que compartilha memória — alterar o recorte altera a imagem original, o que é ótimo para performance e péssimo quando não era a intenção."},{"id":"cv-pre-09","titulo":"O que é uma imagem","prioridade":"fundamental","desc":"Matriz `H × W × C`, dtype `uint8`, intervalo 0–255.","detalhe":"A ordem é altura, largura, canais — o inverso da intuição de \"largura por altura\" de quem vem do design. O dtype `uint8` tem um comportamento traiçoeiro: ele dá a volta (`250 + 10 = 4`), então clarear uma imagem com soma direta escurece as regiões já claras. Para aritmética segura, converta para `float32`, opere e use `np.clip` antes de voltar para `uint8`."},{"id":"cv-pre-10","titulo":"Entrada e saída no OpenCV","prioridade":"fundamental","desc":"`imread`, `imwrite`, `VideoCapture`, `VideoWriter`.","detalhe":"`imread` NÃO levanta exceção em arquivo inexistente: ele devolve `None` silenciosamente, e o erro só aparece três linhas depois com uma mensagem incompreensível. Cheque o retorno sempre. No `VideoWriter`, o FourCC e o FPS precisam ser compatíveis com o container, senão você obtém um arquivo de 0 byte sem nenhum aviso."}]}]},{"id":"classica","numero":1,"titulo":"Visão clássica com OpenCV","objetivo":"Resolver problemas de visão sem deep learning.","descricao":"Esta é a iteração que mais gente pula e que mais se arrepende de ter pulado. Ela constrói a intuição que depois explica o que a CNN está aprendendo — um filtro de Sobel escrito à mão é literalmente o que a primeira camada de uma rede converge a aprender sozinha. Além disso, boa parte do trabalho real de um engenheiro de visão é pré-processamento, definição de ROI, calibração e pós-processamento: tudo isso vive aqui, antes e depois do modelo. E, com frequência, a solução clássica é a solução certa em produção — ela é determinística, roda em milissegundos na CPU e não precisa de dataset anotado.","preRequisitos":"Etapa 0","duracao":null,"criterios":["Você escolhe o espaço de cor a partir do problema, não por tentativa e erro.","Você diagnostica um pipeline clássico que falhou identificando em qual etapa a informação foi perdida.","Você sabe apontar em que condições de iluminação e fundo a abordagem clássica deixa de servir."],"grupos":[{"id":"cv-g-cl-1","titulo":"Manipulação e realce","descricao":"As operações que preparam a imagem antes de qualquer decisão sobre ela.","topicos":[{"id":"cv-cl-01","titulo":"Espaços de cor","prioridade":"fundamental","desc":"BGR, RGB, HSV, LAB e quando cada um é preferível.","detalhe":"HSV é a resposta quando o problema é \"achar o objeto daquela cor\": ele separa matiz (qual cor) de saturação e valor (quão intensa, quão clara), então uma sombra sobre o objeto muda o V mas preserva o H. Em BGR, a mesma sombra muda os três canais ao mesmo tempo e o limiar quebra. LAB é útil quando você precisa de diferença de cor perceptualmente uniforme. O OpenCV usa BGR por herança histórica das câmeras dos anos 90 — e isso é a causa número um de imagens com azul e vermelho trocados ao misturar com matplotlib ou PIL."},{"id":"cv-cl-02","titulo":"Operações geométricas","prioridade":"fundamental","desc":"Crop, resize, rotação, flip, translação e warp.","detalhe":"Todo redimensionamento interpola, e a escolha importa: `INTER_AREA` para reduzir (faz média, evita aliasing), `INTER_LINEAR` ou `INTER_CUBIC` para ampliar. Reduzir com `INTER_NEAREST` cria serrilhado que depois vira ruído de alta frequência nos filtros. Ao rotacionar, lembre que a imagem resultante é retangular: ou você corta os cantos, ou calcula o novo bounding box e preenche as bordas."},{"id":"cv-cl-03","titulo":"Operações aritméticas e máscaras","prioridade":"fundamental","desc":"Operações aritméticas e bitwise entre imagens; máscaras.","detalhe":"Máscara é o mecanismo central da visão clássica: uma imagem binária onde 255 significa \"aqui sim\". `cv2.bitwise_and(img, img, mask=m)` é o idioma para aplicar uma. Use `cv2.add` em vez de `+` quando quiser saturação em 255 em vez de estouro — a diferença entre um céu branco e um céu com manchas pretas é exatamente essa."},{"id":"cv-cl-04","titulo":"Desenho sobre a imagem","prioridade":"opcional","desc":"Linhas, retângulos, círculos e texto.","detalhe":"Parece trivial e é a sua ferramenta de depuração mais usada: desenhar o bounding box, o contorno detectado e o valor do limiar sobre o frame é como você vê o que o algoritmo está vendo. Lembre que essas funções alteram a imagem NO LUGAR — desenhe sempre sobre uma cópia se ainda for processar o original."},{"id":"cv-cl-05","titulo":"Suavização","prioridade":"fundamental","desc":"Blur médio, gaussiano, mediano e bilateral.","detalhe":"Cada um serve a um ruído: o mediano é o único que remove ruído sal e pimenta sem borrar, porque usa a mediana em vez da média e portanto ignora o outlier. O gaussiano é o padrão antes de detectar bordas, já que Canny amplifica ruído. O bilateral preserva bordas enquanto suaviza áreas planas, ao custo de ser ordens de magnitude mais lento — raramente cabe em tempo real."},{"id":"cv-cl-06","titulo":"Limiarização","prioridade":"fundamental","desc":"Global, adaptativa e Otsu.","detalhe":"Limiar global só funciona com iluminação uniforme — que quase nunca é o caso. Otsu escolhe o limiar automaticamente maximizando a separação entre dois picos do histograma, mas pressupõe que existem dois picos. A adaptativa calcula um limiar por vizinhança e é o que salva documento fotografado com sombra de um lado. Se a sua limiarização falha, o problema costuma estar na iluminação, não no parâmetro."},{"id":"cv-cl-07","titulo":"Morfologia","prioridade":"fundamental","desc":"Erosão, dilatação, abertura, fechamento e gradiente.","detalhe":"É a faxina pós-limiarização. Abertura (erosão seguida de dilatação) remove pontinhos brancos soltos; fechamento (o inverso) tampa buracos dentro do objeto. O tamanho e a forma do kernel são o parâmetro de verdade: um kernel elíptico de 5×5 remove ruído diferente de um retangular de 3×9. Aplicar erosão demais faz objetos finos desaparecerem por completo."},{"id":"cv-cl-08","titulo":"Histogramas","prioridade":"importante","desc":"Cálculo, equalização e CLAHE.","detalhe":"O histograma diz se a imagem está subexposta, estourada ou com baixo contraste — antes de você culpar o algoritmo. Equalização global espalha os níveis por toda a faixa, mas amplifica ruído em regiões já uniformes. CLAHE faz isso por blocos com limite de contraste, e é o que se usa na prática em imagem médica e em cena com iluminação desigual."}]},{"id":"cv-g-cl-2","titulo":"Extração de estrutura","descricao":"De pixels para entidades: bordas, formas e correspondências entre imagens.","topicos":[{"id":"cv-cl-09","titulo":"Detecção de bordas","prioridade":"fundamental","desc":"Sobel, Laplaciano e Canny (e o papel dos dois limiares).","detalhe":"Borda é derivada: onde a intensidade muda rápido. Sobel aproxima a primeira derivada em X ou Y; o Laplaciano usa a segunda. Canny é um pipeline completo — suaviza, calcula gradiente, afina a borda e aplica histerese com DOIS limiares: acima do alto é borda certa, entre os dois só conta se estiver conectada a uma borda certa. Essa conectividade é o que evita bordas tracejadas, e é por isso que mexer só no limiar baixo muda tanto o resultado."},{"id":"cv-cl-10","titulo":"Contornos","prioridade":"fundamental","desc":"Extração, hierarquia, área, perímetro, bounding box e aproximação poligonal.","detalhe":"Contorno é a fronteira de uma região conectada, e dele saem as medidas que viram decisão: área (filtra ruído por tamanho mínimo), razão de aspecto, extensão e solidez (identificam forma). `approxPolyDP` reduz o contorno a poucos vértices — se sobram 4, provavelmente é um retângulo. A hierarquia informa quem está dentro de quem, que é como se detecta um furo dentro de uma peça."},{"id":"cv-cl-11","titulo":"Features e casamento","prioridade":"importante","desc":"Harris, SIFT, ORB, matchers e homografia.","detalhe":"Feature é um ponto que você reconhece mesmo que a imagem gire, mude de escala ou de iluminação — tipicamente um canto, nunca um ponto no meio de uma área lisa. SIFT é mais robusto mas era patenteado; ORB é livre, rápido e suficiente na maior parte dos casos. Com pares casados entre duas imagens, a homografia é a matriz 3×3 que leva uma no plano da outra: é assim que se faz panorama, correção de perspectiva de documento e alinhamento de duas tomadas da mesma cena."},{"id":"cv-cl-12","titulo":"Vídeo e subtração de fundo","prioridade":"importante","desc":"MOG2, KNN e diferença entre frames.","detalhe":"Com câmera fixa, modelar o fundo e subtrair é o detector de movimento mais barato que existe. MOG2 e KNN mantêm um modelo estatístico por pixel e se adaptam a mudanças lentas de luz. As falhas previsíveis: objeto que para passa a fazer parte do fundo; sombra é detectada como movimento (MOG2 tem opção para marcá-la); e qualquer tremor da câmera invalida o modelo inteiro."}]}]},{"id":"matematica","numero":2,"titulo":"Fundamentos matemáticos aplicados","objetivo":"Ver a matemática como explicação do que você já implementou, não como pré-requisito abstrato.","descricao":"A ordem aqui é deliberada e contraria a maioria dos cursos: você já escreveu o filtro antes de estudar a convolução, já viu a borda aparecer antes de saber que estava calculando uma derivada. Isso transforma a matemática de obstáculo em explicação. O objetivo não é demonstrar teoremas, e sim conseguir prever o comportamento: saber o que acontece com o tamanho da saída quando você muda o stride, por que uma taxa de aprendizado alta diverge, e o que o PCA está jogando fora quando reduz dimensão.","preRequisitos":"Etapa 1","duracao":null,"criterios":["Você explica o que muda no tamanho da saída ao alterar stride e padding, sem consultar a fórmula.","Você relaciona o kernel de Sobel ao conceito de derivada da imagem.","Você sabe dizer por que uma taxa de aprendizado alta faz a perda divergir."],"grupos":[{"id":"cv-g-mat-1","titulo":"Álgebra linear e geometria","topicos":[{"id":"cv-mat-01","titulo":"Vetores e matrizes","prioridade":"fundamental","desc":"Produto matricial, transposta e inversa.","detalhe":"A intuição que vale mais que a mecânica: uma matriz é uma FUNÇÃO que transforma vetores. O produto `A @ B` é a composição \"aplique B, depois A\" — por isso a ordem importa. A inversa desfaz a transformação, e só existe se nada foi perdido no caminho; uma matriz que achata o espaço em uma dimensão menor não tem inversa, e é isso que o determinante zero está dizendo."},{"id":"cv-mat-02","titulo":"Autovalores, autovetores e PCA","prioridade":"importante","desc":"O que isso significa em uma imagem.","detalhe":"Autovetor é a direção que a transformação não gira, só estica; o autovalor é o quanto estica. PCA usa isso para achar as direções de maior variância dos dados. Aplicado a rostos, os primeiros componentes viram as \"eigenfaces\": padrões de iluminação e forma que, somados, reconstroem qualquer rosto do conjunto. O exercício de reconstruir imagens com poucos componentes mostra na prática o que cada componente carrega."},{"id":"cv-mat-03","titulo":"Transformações geométricas como matrizes","prioridade":"fundamental","desc":"Translação, rotação, escala, afim e projetiva.","detalhe":"O truque das coordenadas homogêneas (acrescentar um 1 ao vetor) é o que permite expressar translação como multiplicação de matriz, e portanto compor rotação, escala e translação num único produto. Afim preserva paralelismo e precisa de 3 pares de pontos; projetiva não preserva e precisa de 4 — é a diferença entre endireitar uma imagem levemente torta e corrigir a perspectiva de um documento fotografado de lado."},{"id":"cv-mat-04","titulo":"Convolução e correlação cruzada","prioridade":"fundamental","desc":"Kernel, stride, padding e o efeito de cada um.","detalhe":"Convolução formalmente inverte o kernel; correlação cruzada não. Na prática as bibliotecas de deep learning implementam correlação cruzada e chamam de convolução — e como o kernel é aprendido, dá no mesmo. A fórmula do tamanho de saída, que vale a pena internalizar: `(entrada + 2·padding − kernel) / stride + 1`. Padding `same` existe para manter o tamanho; stride 2 reduz pela metade e é a alternativa ao pooling."}]},{"id":"cv-g-mat-2","titulo":"Cálculo, otimização e estatística","topicos":[{"id":"cv-mat-05","titulo":"Cálculo","prioridade":"fundamental","desc":"Derivadas, gradiente, regra da cadeia e derivadas parciais.","detalhe":"O gradiente é o vetor que aponta para a subida mais íngreme; treinar é andar no sentido contrário. A regra da cadeia é literalmente o backpropagation: a derivada de uma composição é o produto das derivadas de cada etapa. Entender isso explica por que redes muito profundas sofrem com gradiente que desaparece — é um produto de muitos números menores que 1."},{"id":"cv-mat-06","titulo":"Gradiente descendente","prioridade":"fundamental","desc":"Variantes e taxa de aprendizado.","detalhe":"A taxa de aprendizado é o tamanho do passo. Pequena demais: converge devagar ou empaca em mínimo local raso. Grande demais: o passo ultrapassa o vale, a perda sobe, e a divergência vira NaN em poucas iterações. É o hiperparâmetro que mais importa, e o teste de sanidade mais rápido quando um treino não desce."},{"id":"cv-mat-07","titulo":"Probabilidade","prioridade":"importante","desc":"Variáveis aleatórias, distribuições, Bayes, média e variância.","detalhe":"Bayes é o que converte \"o modelo acertou 99% no teste\" em \"qual a chance de estar certo NESTE caso\" — e a resposta depende da prevalência. Com um evento raro (1 em 10 mil), mesmo um detector de 99% de precisão produz muito mais falsos positivos do que verdadeiros. É a matemática por trás da sua desconfiança saudável de métricas altas."},{"id":"cv-mat-08","titulo":"Estatística","prioridade":"importante","desc":"Amostragem, viés, correlação e significância.","detalhe":"Viés de amostragem é o erro mais caro em visão: se todas as fotos da classe A foram tiradas de dia e as da classe B de noite, o modelo aprende iluminação e reporta acurácia excelente. Sobre significância: a diferença entre 91,2% e 91,8% em um conjunto de teste de 500 imagens está dentro do ruído — não é melhoria, é variação."},{"id":"cv-mat-09","titulo":"Otimização","prioridade":"importante","desc":"Funções de custo, mínimos locais, regularização L1 e L2.","detalhe":"A função de custo é a tradução do seu objetivo em número derivável — escolhê-la é uma decisão de projeto, não um detalhe. L2 (weight decay) encolhe todos os pesos suavemente; L1 zera muitos deles e produz um modelo esparso, útil quando você quer seleção de features. Em redes profundas, mínimos locais são um problema menor do que a teoria sugere; o obstáculo real costuma ser platôs e pontos de sela."}]}]},{"id":"ml-classico","numero":3,"titulo":"Machine learning clássico","objetivo":"Aprender a avaliar modelos corretamente antes de treinar redes profundas.","descricao":"A razão de esta iteração vir antes das redes é econômica: erro de avaliação em modelo clássico custa minutos para descobrir; o mesmo erro em rede profunda custa dias de GPU e passa despercebido por semanas, porque o número na tela continua subindo. Aqui você aprende a desconfiar da própria métrica — vazamento de dados, acurácia enganosa em dataset desbalanceado, validação que não representa produção. São os mesmos erros que depois aparecem em deep learning, só que aqui eles são visíveis.","preRequisitos":"Etapa 2","duracao":null,"criterios":["Você explica por que acurácia é uma métrica ruim em dataset desbalanceado, com um exemplo numérico.","Você identifica vazamento de dados em um pipeline (por exemplo, normalizar antes de dividir o conjunto).","Você escolhe entre priorizar precisão ou recall a partir do custo do erro no domínio."],"grupos":[{"id":"cv-g-mlc-1","titulo":"Enquadramento e algoritmos","topicos":[{"id":"cv-mlc-01","titulo":"Tipos de aprendizado","prioridade":"fundamental","desc":"Supervisionado e não supervisionado; classificação e regressão.","detalhe":"Supervisionado precisa de rótulo, e rotular é o gargalo real de qualquer projeto de visão — não o modelo. Não supervisionado dispensa rótulo mas entrega agrupamento, não resposta: o algoritmo separa os dados em grupos e cabe a você decidir o que cada grupo significa. Classificação prevê categoria; regressão prevê número contínuo, como a coordenada de um ponto."},{"id":"cv-mlc-02","titulo":"Divisão de dados e vazamento","prioridade":"fundamental","desc":"Treino, validação e teste; vazamento de dados.","detalhe":"Treino ajusta parâmetros, validação ajusta hiperparâmetros, teste se toca UMA vez. Vazamento é qualquer informação do teste que escapa para o treino, e em visão ele tem formas próprias: frames consecutivos do mesmo vídeo em splits diferentes (são quase a mesma imagem), augmentação aplicada antes da divisão, ou normalização calculada sobre o conjunto inteiro. O sintoma é sempre o mesmo: validação ótima, produção péssima."},{"id":"cv-mlc-03","titulo":"Classificadores clássicos","prioridade":"importante","desc":"KNN, árvores de decisão, Random Forest e SVM (incluindo o kernel trick).","detalhe":"KNN não treina: guarda tudo e compara na hora, o que o torna lento na inferência e péssimo em alta dimensão. Random Forest é o baseline honesto para dados tabulares e descritores de imagem — robusto e quase sem ajuste. SVM com kernel RBF projeta os dados num espaço de dimensão maior onde eles ficam separáveis, sem nunca calcular essa projeção explicitamente; foi o estado da arte em classificação de imagem antes das CNNs."},{"id":"cv-mlc-04","titulo":"K-Means e clustering em imagens","prioridade":"importante","desc":"Segmentação por cor e quantização.","detalhe":"Tratando cada pixel como um ponto em 3 dimensões (B, G, R), o K-Means agrupa cores parecidas: isso é quantização de cor e também uma segmentação ingênua. Limitações a conhecer: você precisa escolher o K, o resultado depende da inicialização, e o algoritmo assume grupos esféricos de tamanho parecido — o que raramente descreve regiões de uma imagem real."},{"id":"cv-mlc-05","titulo":"Validação cruzada e hiperparâmetros","prioridade":"fundamental","desc":"Cross-validation e busca de hiperparâmetros.","detalhe":"Validação cruzada em K dobras dá uma estimativa com barra de erro em vez de um número solto, e é o que diferencia \"melhorou\" de \"deu sorte na divisão\". Use a variante estratificada para preservar a proporção das classes. Busca aleatória costuma achar bons hiperparâmetros mais rápido que busca em grade, porque a maioria dos hiperparâmetros não importa e a grade desperdiça tempo variando os irrelevantes."}]},{"id":"cv-g-mlc-2","titulo":"Avaliação e preparação de dados","topicos":[{"id":"cv-mlc-06","titulo":"Métricas de classificação","prioridade":"fundamental","desc":"Acurácia, precisão, recall, F1, matriz de confusão, ROC e AUC.","detalhe":"O exemplo numérico que resolve o critério de domínio: num dataset com 99% de classe negativa, o modelo que responde sempre \"negativo\" tem 99% de acurácia e serve para nada. Precisão responde \"dos que apontei, quantos eram\"; recall, \"dos que existiam, quantos achei\". A matriz de confusão é mais informativa que qualquer número único, porque mostra QUAIS classes se confundem — e isso costuma apontar um problema de anotação."},{"id":"cv-mlc-07","titulo":"Overfitting, viés e variância","prioridade":"fundamental","desc":"Overfitting, underfitting, viés e variância.","detalhe":"O diagnóstico se faz comparando duas curvas: erro de treino alto e validação alta é underfitting (modelo simples demais, viés); treino baixo e validação alta é overfitting (decorou, variância). Cada caso pede o oposto do outro — mais capacidade contra mais dados e regularização. Tratar overfitting com um modelo maior é o erro mais comum de quem não olha as duas curvas."},{"id":"cv-mlc-08","titulo":"Engenharia de features","prioridade":"importante","desc":"Seleção, redução de dimensionalidade e normalização.","detalhe":"Normalizar é obrigatório para KNN e SVM, que dependem de distância: sem isso, a feature de maior escala domina o cálculo. O detalhe que vira vazamento: calcule média e desvio APENAS no treino e aplique no teste, nunca o contrário. Em alta dimensão, as distâncias se achatam (\"maldição da dimensionalidade\") e reduzir dimensão passa a melhorar o resultado, não só a velocidade."},{"id":"cv-mlc-09","titulo":"Descritores clássicos de imagem","prioridade":"importante","desc":"HOG, LBP e histogramas de cor.","detalhe":"São o elo entre a iteração 1 e o machine learning: convertem a imagem num vetor de tamanho fixo que o classificador consegue consumir. HOG descreve a distribuição de orientações de gradiente em células e foi a base da detecção de pedestres por anos. LBP captura textura comparando cada pixel com seus vizinhos. HOG + SVM é um baseline que ainda vale como referência, e é o projeto desta iteração."},{"id":"cv-mlc-10","titulo":"Augmentation e desbalanceamento","prioridade":"fundamental","desc":"Data augmentation e classes desbalanceadas.","detalhe":"Augmentation só vale se a transformação for plausível no seu domínio: espelhar um gato horizontalmente faz sentido, espelhar um dígito manuscrito cria um rótulo errado. Para desbalanceamento, as opções são pesar a classe na função de custo, reamostrar, ou mudar a métrica — e a primeira costuma ser a menos destrutiva. Aplique augmentation apenas no treino, jamais na validação."},{"id":"cv-mlc-11","titulo":"Scikit-learn na prática","prioridade":"importante","desc":"`Pipeline`, transformadores e reprodutibilidade com `random_state`.","detalhe":"O `Pipeline` existe para tornar o vazamento difícil: ele garante que cada transformador só vê o treino dentro de cada dobra da validação cruzada. Fixe `random_state` em toda divisão e todo modelo estocástico — sem isso, você não consegue dizer se a melhoria veio da sua mudança ou de outra divisão dos dados."}]}]},{"id":"redes","numero":4,"titulo":"Redes neurais e PyTorch","objetivo":"Entender o que uma rede faz internamente antes de usar modelos prontos.","descricao":"Esta é a última iteração em que você escreve as coisas do zero. Daqui em diante você usa modelos pré-treinados, e a diferença entre quem consegue depurá-los e quem não consegue é exatamente o que se aprende aqui. Implementar forward e backward à mão em NumPy, mesmo para um problema trivial, é o que transforma backpropagation de palavra em mecanismo. Depois disso, o loop de treino do PyTorch deixa de ser um template copiado e passa a ser cinco linhas cujo propósito você consegue justificar uma a uma.","preRequisitos":"Etapa 3","duracao":null,"criterios":["Você escreve um loop de treino em PyTorch do zero, sem consultar um template.","Você diagnostica três sintomas distintos: perda que não desce, perda que diverge, e treino bom com validação ruim.","Você explica o que `model.eval()` e `torch.no_grad()` mudam, e o que quebra ao esquecê-los."],"grupos":[{"id":"cv-g-nn-1","titulo":"Anatomia de uma rede","topicos":[{"id":"cv-nn-01","titulo":"Neurônio e camadas densas","prioridade":"fundamental","desc":"Neurônio, camadas densas, pesos e vieses.","detalhe":"Um neurônio é uma soma ponderada mais um viés, passada por uma ativação. Uma camada densa é só isso em forma matricial: `y = Wx + b`. O viés é o que permite deslocar a fronteira de decisão da origem — sem ele, toda fronteira passaria pelo ponto zero, o que limita severamente o que a rede consegue representar."},{"id":"cv-nn-02","titulo":"Funções de ativação","prioridade":"fundamental","desc":"ReLU, LeakyReLU, sigmoid, tanh, softmax.","detalhe":"Sem ativação não linear, empilhar camadas é inútil: a composição de transformações lineares continua linear. ReLU é o padrão por ser barata e não saturar do lado positivo; seu defeito é o neurônio morto, que LeakyReLU corrige deixando um filete passar no lado negativo. Sigmoid satura nas duas pontas e mata o gradiente — use só na saída de classificação binária. Softmax normaliza logits em distribuição de probabilidade e pertence à saída multiclasse, não ao meio da rede."},{"id":"cv-nn-03","titulo":"Forward e backpropagation","prioridade":"fundamental","desc":"Forward pass e backpropagation.","detalhe":"Forward calcula a predição e guarda os valores intermediários; backward percorre o grafo no sentido inverso aplicando a regra da cadeia para obter a derivada da perda em relação a cada peso. O ponto que o exercício em NumPy deixa claro: o backward REUSA o que o forward guardou — é por isso que treinar consome muito mais memória que inferir, e por isso que `torch.no_grad()` economiza tanto."},{"id":"cv-nn-04","titulo":"Funções de perda","prioridade":"fundamental","desc":"Cross-entropy, MSE e quando cada uma se aplica.","detalhe":"Cross-entropy para classificação, MSE para regressão — e a troca entre elas é erro comum. Detalhe prático do PyTorch: `nn.CrossEntropyLoss` já aplica log-softmax internamente, então a sua rede deve devolver logits crus. Colocar um softmax antes dela aplica a operação duas vezes, os gradientes encolhem e o treino fica lento sem dar erro algum."},{"id":"cv-nn-05","titulo":"Otimizadores","prioridade":"fundamental","desc":"SGD, momentum, RMSProp e Adam.","detalhe":"SGD puro é lento em vales estreitos; momentum acumula velocidade e atravessa platôs. Adam adapta a taxa por parâmetro e é o padrão razoável para começar. Contraponto que vale saber: SGD com momentum e um bom schedule costuma generalizar melhor que Adam em visão, e é o que as receitas de treino de ResNet usam."}]},{"id":"cv-g-nn-2","titulo":"Treinar de verdade","topicos":[{"id":"cv-nn-06","titulo":"Hiperparâmetros de treino","prioridade":"fundamental","desc":"Batch size, épocas, learning rate e schedulers.","detalhe":"Batch grande dá gradiente menos ruidoso e melhor uso da GPU, mas o ruído do batch pequeno é em parte o que ajuda a generalizar. Regra prática ao dobrar o batch: dobre também a taxa de aprendizado. Schedulers reduzem a taxa ao longo do treino — cosine annealing e step decay são os dois padrões, e quase sempre valem alguns pontos de acurácia de graça."},{"id":"cv-nn-07","titulo":"Regularização","prioridade":"fundamental","desc":"Dropout, weight decay e early stopping.","detalhe":"Dropout desliga neurônios aleatoriamente no treino, forçando redundância; ele é DESLIGADO automaticamente por `model.eval()`, e esquecer isso é a causa número um de inferência com resultado instável. Weight decay penaliza pesos grandes. Early stopping para quando a validação para de melhorar e é a regularização mais barata que existe."},{"id":"cv-nn-08","titulo":"Normalização e inicialização","prioridade":"importante","desc":"Batch normalization e inicialização de pesos.","detalhe":"BatchNorm normaliza as ativações por batch e permite taxas de aprendizado maiores e convergência mais rápida. Ele também muda de comportamento entre treino e avaliação — usa estatísticas do batch no treino e médias acumuladas na inferência — outra razão para `model.eval()`. Inicialização ruim faz o sinal desaparecer ou explodir ao longo das camadas; He para ReLU, Xavier para tanh."},{"id":"cv-nn-09","titulo":"Convolução em redes","prioridade":"fundamental","desc":"Filtros, feature maps, pooling e campo receptivo.","detalhe":"A CNN é eficiente por dois motivos: pesos compartilhados (o mesmo filtro varre a imagem inteira, o que dá invariância a translação) e conectividade local. Campo receptivo é a região da imagem original que influencia um neurônio — ele cresce com a profundidade, e é por isso que camadas rasas detectam bordas e as profundas detectam partes de objeto. Se o objeto é maior que o campo receptivo, a rede não consegue vê-lo inteiro."},{"id":"cv-nn-10","titulo":"PyTorch essencial","prioridade":"fundamental","desc":"Tensores, `autograd`, `nn.Module`, `Dataset`, `DataLoader`, `.to(device)`.","detalhe":"`nn.Module` organiza parâmetros e submódulos e dá `.parameters()` de graça para o otimizador. `Dataset` define como obter UM item; `DataLoader` cuida de batch, embaralhamento e paralelismo de leitura — e `num_workers` costuma ser o parâmetro que tira a GPU da ociosidade. Modelo e dados precisam estar no MESMO device, e o erro de device é provavelmente o mais frequente de todos."},{"id":"cv-nn-11","titulo":"Loop de treino à mão","prioridade":"fundamental","desc":"`zero_grad`, `backward`, `step`, modo `train`/`eval`.","detalhe":"A ordem é: zerar gradientes, forward, calcular perda, backward, passo do otimizador. `zero_grad` é necessário porque o PyTorch ACUMULA gradientes por padrão — esquecê-lo faz os gradientes somarem entre batches e o treino degenera de um jeito difícil de diagnosticar. Na validação, `model.eval()` mais `torch.no_grad()`: o primeiro muda dropout e BatchNorm, o segundo dispensa o grafo e economiza memória. São coisas diferentes e você precisa das duas."},{"id":"cv-nn-12","titulo":"Checkpoints e reprodutibilidade","prioridade":"importante","desc":"Salvar e carregar checkpoints; seeds.","detalhe":"Salve o `state_dict`, não o objeto do modelo inteiro — o pickle do objeto amarra o arquivo à estrutura exata do seu código e quebra na primeira refatoração. Um checkpoint útil guarda também o estado do otimizador, a época e a melhor métrica, para poder retomar. Fixar seeds reduz a variação mas não elimina: algumas operações de CUDA são não determinísticas por padrão."}]}]},{"id":"cnns","numero":5,"titulo":"CNNs modernas e transfer learning","objetivo":"Parar de treinar do zero. Este é o modo padrão de trabalho na prática.","descricao":"Treinar do zero é quase sempre a escolha errada: um backbone pré-treinado na ImageNet já aprendeu bordas, texturas e partes de objeto, e isso transfere para praticamente qualquer domínio visual. Com transfer learning, 200 imagens por classe costumam bastar para um resultado decente — contra dezenas de milhares exigidas por um treino do zero. A outra metade desta iteração é interpretabilidade: Grad-CAM é o que revela que o seu modelo de 95% de acurácia aprendeu o fundo, a marca d''água ou o tipo de iluminação em vez do objeto.","preRequisitos":"Etapa 4","duracao":null,"criterios":["Você justifica a escolha da arquitetura pelo trade-off entre acurácia, tamanho e latência.","Você consegue descobrir, via Grad-CAM, que um modelo com boa acurácia estava aprendendo o fundo e não o objeto.","Você sabe quando congelar e quando descongelar o backbone, em função do tamanho do dataset."],"grupos":[{"id":"cv-g-cnn-1","titulo":"Arquiteturas","descricao":"Cada uma resolveu um problema concreto da anterior; conhecer o problema vale mais que decorar as camadas.","topicos":[{"id":"cv-cnn-01","titulo":"VGG","prioridade":"importante","desc":"Profundidade uniforme e seu custo.","detalhe":"VGG mostrou que empilhar convoluções 3×3 pequenas supera poucas convoluções grandes, com menos parâmetros e mais não linearidade. O custo é brutal: a maior parte dos seus ~138 milhões de parâmetros está nas camadas densas finais. Hoje serve mais como referência histórica e como extrator de features para perceptual loss do que como escolha de produção."},{"id":"cv-cnn-02","titulo":"ResNet","prioridade":"fundamental","desc":"Conexões residuais e o problema do gradiente que desaparece.","detalhe":"Antes da ResNet, redes mais profundas ficavam PIORES, inclusive no treino — não era overfitting, era otimização. A conexão residual (`saída = F(x) + x`) cria um caminho direto para o gradiente retroceder sem ser multiplicado, o que permitiu treinar centenas de camadas. É a ideia mais reaproveitada do deep learning moderno: transformers também a usam. ResNet-50 continua sendo o baseline honesto de classificação."},{"id":"cv-cnn-03","titulo":"Inception","prioridade":"opcional","desc":"Convoluções paralelas em múltiplas escalas.","detalhe":"Em vez de escolher o tamanho do kernel, o bloco Inception aplica 1×1, 3×3 e 5×5 em paralelo e concatena, deixando a rede decidir a escala. A convolução 1×1 que aparece antes das maiores é um redutor de canais e é o que torna o custo viável. O conceito de 1×1 como \"camada densa aplicada por pixel\" aparece em muitas arquiteturas depois desta."},{"id":"cv-cnn-04","titulo":"EfficientNet e MobileNet","prioridade":"importante","desc":"Escalonamento composto e convolução separável em profundidade.","detalhe":"A convolução separável em profundidade quebra a convolução normal em duas etapas (espacial por canal, depois 1×1 entre canais) e reduz o custo em quase uma ordem de magnitude com perda pequena de acurácia — é o que viabiliza visão em celular. EfficientNet mostrou que escalar profundidade, largura e resolução JUNTOS, numa proporção fixa, rende mais que escalar qualquer um isoladamente. São as arquiteturas a considerar quando a iteração 11 cobrar latência."}]},{"id":"cv-g-cnn-2","titulo":"Transferir, aumentar e inspecionar","topicos":[{"id":"cv-cnn-05","titulo":"Transfer learning","prioridade":"fundamental","desc":"Congelar backbone, substituir a cabeça e descongelar por etapas.","detalhe":"A regra prática é pelo tamanho do seu dataset: poucos dados e domínio parecido com ImageNet, congele tudo e treine só a cabeça; muitos dados ou domínio distante (imagem médica, satélite, infravermelho), descongele progressivamente. Descongelar tudo de uma vez com taxa alta destrói as features pré-treinadas nas primeiras iterações — fenômeno conhecido como esquecimento catastrófico."},{"id":"cv-cnn-06","titulo":"Fine-tuning","prioridade":"fundamental","desc":"Taxas de aprendizado diferenciadas por camada.","detalhe":"Camadas rasas aprenderam bordas e texturas, que são universais e não devem mudar muito; camadas profundas aprenderam conceitos específicos da ImageNet e precisam se adaptar. Daí a taxa discriminativa: menor nas primeiras camadas, maior nas últimas, tipicamente com fator de 10 entre blocos. Combine com warmup para não arruinar os pesos no primeiro passo."},{"id":"cv-cnn-07","titulo":"Pré-processamento esperado","prioridade":"fundamental","desc":"Tamanho e normalização de cada modelo pré-treinado.","detalhe":"Cada modelo pré-treinado espera exatamente a normalização usada no treino original — para a ImageNet, média `[0.485, 0.456, 0.406]` e desvio `[0.229, 0.224, 0.225]` em RGB. Alimentar com valores de 0 a 255, ou em BGR vindo do OpenCV, produz um modelo que funciona mal sem dar nenhum erro. É a falha silenciosa mais frequente de quem está começando com transfer learning."},{"id":"cv-cnn-08","titulo":"Augmentation moderno","prioridade":"importante","desc":"`albumentations`, RandAugment, mixup e cutmix.","detalhe":"`albumentations` é rápido e, crucialmente, transforma a anotação junto com a imagem — ao girar, as caixas e máscaras giram também. Mixup e cutmix combinam duas imagens e seus rótulos, o que regulariza bem e calibra melhor a confiança do modelo. Como na iteração 3: só no treino, e só com transformações plausíveis no seu domínio."},{"id":"cv-cnn-09","titulo":"Interpretabilidade","prioridade":"fundamental","desc":"Grad-CAM e visualização de feature maps.","detalhe":"Grad-CAM usa o gradiente da classe prevista em relação à última camada convolucional para produzir um mapa de calor do que pesou na decisão. É a ferramenta que expõe o atalho: o modelo que separa cachorro de lobo pela neve ao fundo, ou que detecta pneumonia pelo marcador do aparelho de raio-X. Rode Grad-CAM nos ACERTOS também, não só nos erros — um acerto pelo motivo errado não sobrevive a produção."},{"id":"cv-cnn-10","titulo":"Acompanhamento de experimentos","prioridade":"importante","desc":"TensorBoard ou Weights & Biases.","detalhe":"Depois do quinto experimento, você não lembra mais qual taxa de aprendizado gerou qual curva. Registre hiperparâmetros, métricas, hash do commit e versão do dataset junto com cada run. O ganho não é organização: é conseguir responder \"por que esta versão ficou melhor\" com evidência em vez de memória."}]}]},{"id":"deteccao","numero":6,"titulo":"Detecção de objetos","objetivo":"Sair de \"que imagem é esta\" para \"o que existe na imagem e onde\".","descricao":"Detecção é onde o trabalho deixa de ser sobre o modelo e passa a ser sobre os dados. Anotar 300 imagens à mão ensina mais sobre o problema do que treinar dez arquiteturas: você descobre quais casos são ambíguos, onde a sua própria definição de classe vacila e quanto do erro do modelo é na verdade erro de anotação. A outra lição desta iteração é que os limiares de confiança e de NMS são decisões de PRODUTO, não de treino — eles traduzem o custo relativo de um falso positivo e de um falso negativo no seu domínio.","preRequisitos":"Etapa 5","duracao":null,"criterios":["Você explica mAP@0.5 versus mAP@0.5:0.95 e o que a diferença revela sobre a precisão das caixas.","Você distingue erro de detecção causado por dataset, por anotação e por arquitetura.","Você escolhe entre um detector de um ou dois estágios a partir do requisito de latência."],"grupos":[{"id":"cv-g-det-1","titulo":"Conceitos e formatos","topicos":[{"id":"cv-det-01","titulo":"Classificação, localização, detecção e segmentação","prioridade":"fundamental","desc":"A diferença entre as quatro tarefas.","detalhe":"Classificação dá um rótulo para a imagem inteira; localização acrescenta uma caixa para um único objeto; detecção lida com número variável de objetos e classes; segmentação desce ao pixel. A escolha é guiada pelo que a aplicação precisa MEDIR: se basta contar, detecção serve; se é preciso saber a área exata, só segmentação resolve."},{"id":"cv-det-02","titulo":"Formatos de bounding box","prioridade":"fundamental","desc":"`xyxy`, `xywh`, normalizado; COCO, Pascal VOC e YOLO.","detalhe":"Três convenções incompatíveis em uso simultâneo: Pascal VOC usa `xyxy` absoluto, COCO usa `x,y,largura,altura` com origem no canto, YOLO usa centro e dimensões NORMALIZADOS de 0 a 1. Converter errado produz caixas deslocadas ou minúsculas, e o treino simplesmente não converge. Sempre desenhe algumas anotações sobre a imagem antes de treinar — cinco minutos que economizam um dia."},{"id":"cv-det-03","titulo":"IoU, NMS e limiar de confiança","prioridade":"fundamental","desc":"Intersecção sobre união, supressão de não máximos e corte de confiança.","detalhe":"IoU mede sobreposição entre duas caixas e é a régua de tudo em detecção. NMS resolve o fato de que o detector emite várias caixas para o mesmo objeto: mantém a de maior confiança e descarta as que se sobrepõem acima de um limiar. O efeito colateral a conhecer: com objetos legitimamente sobrepostos (uma multidão), um NMS agressivo apaga detecções corretas — é quando se usa Soft-NMS."},{"id":"cv-det-04","titulo":"Detectores de dois estágios","prioridade":"importante","desc":"R-CNN, Fast R-CNN, Faster R-CNN e Region Proposal Network.","detalhe":"A linhagem é uma aula de otimização incremental: R-CNN rodava a CNN em cada proposta (lentíssimo); Fast R-CNN passou a rodar uma vez na imagem e recortar as features; Faster R-CNN substituiu a busca seletiva externa por uma rede de propostas treinável, tornando o sistema inteiro ponta a ponta. São mais precisos em objetos pequenos e mais lentos — a escolha quando a latência não é o gargalo."},{"id":"cv-det-05","titulo":"Detectores de estágio único","prioridade":"fundamental","desc":"SSD e a família YOLO (âncoras, grid, versões anchor-free).","detalhe":"Estágio único prevê classe e caixa diretamente sobre um grid, em uma passada — daí a velocidade. Âncoras são caixas de referência de formatos predefinidos; se o seu domínio tem objetos de proporção incomum (algo muito alongado, por exemplo), as âncoras padrão atrapalham e vale recalculá-las. As versões anchor-free mais recentes eliminam esse ajuste prevendo a caixa diretamente."},{"id":"cv-det-06","titulo":"Detectores com transformer","prioridade":"opcional","desc":"DETR.","detalhe":"DETR trata detecção como predição de conjunto: a rede emite N caixas de uma vez e um algoritmo de correspondência bipartida as casa com a verdade. Isso elimina âncoras e NMS do pipeline. O preço é convergência muito lenta no treino e desempenho fraco em objetos pequenos — variantes como Deformable DETR atacam ambos."}]},{"id":"cv-g-det-2","titulo":"Avaliar e treinar","topicos":[{"id":"cv-det-07","titulo":"Métricas de detecção","prioridade":"fundamental","desc":"AP, mAP@0.5, mAP@0.5:0.95 e curva precisão-recall.","detalhe":"AP é a área sob a curva precisão-recall de uma classe; mAP é a média entre classes. A diferença que o critério de domínio cobra: mAP@0.5 só exige 50% de sobreposição, enquanto mAP@0.5:0.95 faz a média em dez limiares cada vez mais exigentes — uma queda grande entre os dois significa que você ACHA os objetos mas as caixas estão imprecisas, o que é um problema diferente de não achá-los."},{"id":"cv-det-08","titulo":"Anotação de dados","prioridade":"fundamental","desc":"CVAT, Roboflow ou Label Studio; qualidade e consistência.","detalhe":"Consistência vale mais que volume: se metade do dataset inclui a sombra do objeto na caixa e a outra metade não, você impôs ao modelo um alvo contraditório e nenhuma arquitetura resolve isso. Escreva um guia de anotação com casos de borda decididos ANTES de começar, e revise uma amostra cruzada. Boa parte do que parece erro de modelo é desacordo de anotação."},{"id":"cv-det-09","titulo":"Treino com Ultralytics YOLO","prioridade":"fundamental","desc":"Dataset YAML, hiperparâmetros e augmentation.","detalhe":"O YAML aponta diretórios e lista as classes NA ORDEM dos índices — trocar a ordem entre datasets é um erro silencioso que gera rótulos invertidos. Comece do peso pré-treinado, não do zero. E leia o que o augmentation padrão já faz (mosaico, HSV, flip): ele costuma ser suficiente, e desligá-lo nas últimas épocas melhora as caixas finais."}]}]},{"id":"segmentacao","numero":7,"titulo":"Segmentação","objetivo":"Precisão em nível de pixel.","descricao":"Segmentação responde \"quais pixels exatamente\", e isso muda o que você consegue medir: área, forma, contorno, proporção. É a diferença entre contar folhas doentes e medir a porcentagem de área afetada. O custo é de anotação — rotular máscara é entre cinco e dez vezes mais caro que rotular caixa, razão pela qual o SAM mudou o jogo ao permitir anotar por clique. A armadilha estatística desta iteração é a acurácia por pixel: quando o objeto ocupa 2% da imagem, prever \"fundo\" em tudo dá 98%.","preRequisitos":"Etapa 6","duracao":null,"criterios":["Você explica por que acurácia por pixel engana quando o objeto ocupa 2% da imagem.","Você escolhe entre detecção e segmentação a partir do que a aplicação precisa medir.","Você lê o tipo de erro: bordas imprecisas, buracos internos e falsos positivos isolados têm causas diferentes."],"grupos":[{"id":"cv-g-seg-1","titulo":"Tarefas e arquiteturas","topicos":[{"id":"cv-seg-01","titulo":"Os três tipos de segmentação","prioridade":"fundamental","desc":"Semântica, de instâncias e panóptica.","detalhe":"Semântica rotula cada pixel por classe e não distingue indivíduos: duas pessoas encostadas viram uma mancha só. De instâncias separa indivíduos mas costuma ignorar o fundo. Panóptica faz as duas coisas. Se a sua aplicação precisa CONTAR, segmentação semântica não basta — e descobrir isso depois de anotar o dataset inteiro é caro."},{"id":"cv-seg-02","titulo":"Encoder-decoder e skip connections","prioridade":"fundamental","desc":"A estrutura comum a quase toda rede de segmentação.","detalhe":"O encoder reduz a resolução acumulando contexto semântico; o decoder volta ao tamanho original. O problema é que a redução destrói a informação de localização precisa. As skip connections resolvem isso ligando cada nível do encoder ao nível correspondente do decoder, devolvendo o detalhe espacial. É por isso que a U-Net tem esse formato de U."},{"id":"cv-seg-03","titulo":"U-Net, FCN e DeepLab","prioridade":"fundamental","desc":"U-Net e variantes; FCN; convolução dilatada.","detalhe":"A U-Net nasceu em imagem biomédica, com poucos dados e muita augmentation, e continua sendo o primeiro modelo a tentar em qualquer segmentação binária. DeepLab usa convolução dilatada (atrous), que amplia o campo receptivo sem reduzir a resolução nem acrescentar parâmetros, e o módulo ASPP combina várias dilatações para capturar objetos em escalas diferentes."},{"id":"cv-seg-04","titulo":"Mask R-CNN e RoIAlign","prioridade":"importante","desc":"Segmentação de instâncias sobre um detector.","detalhe":"Mask R-CNN é o Faster R-CNN com um ramo adicional que prevê a máscara dentro de cada caixa. A contribuição técnica importante é o RoIAlign: o RoIPool anterior arredondava coordenadas para inteiros, e esse desalinhamento de poucos pixels era irrelevante para a caixa mas arruinava a máscara. Interpolação bilinear em vez de arredondamento — uma mudança pequena com ganho grande."},{"id":"cv-seg-05","titulo":"Segment Anything (SAM)","prioridade":"importante","desc":"Segmentação por prompt.","detalhe":"SAM segmenta qualquer objeto a partir de um ponto, uma caixa ou uma máscara grosseira, sem ter sido treinado nas suas classes. O uso que mais rende: acelerar anotação. Você clica, ele produz a máscara, você corrige — reduzindo o custo por imagem drasticamente. Ele não sabe o NOME do que segmentou, então ainda é preciso atribuir a classe (ou combiná-lo com GroundingDINO, na iteração 9)."}]},{"id":"cv-g-seg-2","titulo":"Perdas, métricas e pós-processamento","topicos":[{"id":"cv-seg-06","titulo":"Perdas específicas","prioridade":"fundamental","desc":"Dice, IoU loss, focal loss e o desbalanceamento de pixels.","detalhe":"Cross-entropy por pixel trata todos os pixels igualmente, e com 98% de fundo ela converge para prever fundo. Dice loss otimiza a sobreposição diretamente e é naturalmente robusta ao desbalanceamento. Focal loss reduz o peso dos exemplos fáceis para que os difíceis dominem o gradiente. A combinação cross-entropy + Dice é a receita padrão, e comparar as duas isoladamente é o projeto desta iteração."},{"id":"cv-seg-07","titulo":"Métricas de segmentação","prioridade":"fundamental","desc":"IoU, mIoU, Dice e acurácia por pixel.","detalhe":"IoU e Dice medem sobreposição e estão matematicamente relacionados (Dice é sempre maior ou igual); Dice é mais tolerante com objetos pequenos. mIoU é a média entre classes e é a métrica padrão em benchmarks. Acurácia por pixel só deve aparecer no relatório acompanhada de outra — sozinha, ela é a métrica que o critério de domínio pede para você saber desmascarar."},{"id":"cv-seg-08","titulo":"Anotação por máscara e polígono","prioridade":"importante","desc":"Custo de anotação.","detalhe":"Polígono é mais rápido de anotar e editar que pintura livre, e é o formato que COCO usa. Decida antecipadamente o nível de detalhe: contornar cada fio de cabelo multiplica o custo por cinco e raramente muda a métrica. Como em detecção, ambiguidade de borda não resolvida vira ruído de rótulo, e o modelo aprende a incerteza da sua equipe."},{"id":"cv-seg-09","titulo":"Pós-processamento de máscaras","prioridade":"importante","desc":"Morfologia e remoção de componentes pequenos.","detalhe":"Aqui a iteração 1 volta a ser útil: abertura remove falsos positivos isolados, fechamento tampa buracos internos, e filtrar componentes conectados por área mínima limpa ruído. O critério de domínio pede justamente isso — ler o TIPO de erro: buraco interno sugere perda muito penalizada no centro, borda imprecisa sugere resolução insuficiente no decoder, e pontos isolados sugerem limiar baixo demais."}]}]},{"id":"tracking","numero":8,"titulo":"Tracking e análise de movimento","objetivo":"Manter identidade ao longo do tempo.","descricao":"É aqui que o vídeo deixa de ser uma sequência de imagens independentes. A mudança de perspectiva é importante: um detector excelente frame a frame pode produzir um tracking péssimo, porque identidade é um problema de ASSOCIAÇÃO, não de detecção. E tracking é o que habilita quase toda métrica de negócio em vídeo — contagem sem duplicar, tempo de permanência, trajetória, velocidade. Sem identidade estável, você consegue dizer quantos objetos há em cada frame, mas nunca quantos passaram.","preRequisitos":"Etapa 6","duracao":null,"criterios":["Você explica por que um detector bom pode gerar um tracking ruim, e vice-versa.","Você sabe qual parâmetro ajustar quando os IDs trocam demais e quando as trilhas somem cedo demais.","Você distingue quando o problema exige tracking e quando detecção por frame já basta."],"grupos":[{"id":"cv-g-trk","titulo":null,"topicos":[{"id":"cv-trk-01","titulo":"Tracking de objeto único","prioridade":"importante","desc":"Trackers clássicos do OpenCV (KCF, CSRT, MOSSE).","detalhe":"Você marca o objeto uma vez e o tracker o segue por correlação de aparência, sem detector. MOSSE é o mais rápido e o menos preciso; CSRT é o inverso; KCF fica no meio. Todos derivam com o tempo e nenhum se recupera de oclusão total. Servem quando há um alvo só, definido pelo usuário, e detectar a cada frame seria caro demais."},{"id":"cv-trk-02","titulo":"Tracking-by-detection","prioridade":"fundamental","desc":"Tracking de múltiplos objetos e o paradigma dominante.","detalhe":"O paradigma é simples de enunciar: detecte em todo frame e associe as detecções novas às trilhas existentes. Isso separa claramente as duas fontes de erro — falha de detecção (objeto some) e falha de associação (objeto troca de ID) — e é exatamente a distinção que o critério de domínio cobra. Quase todo tracker moderno de múltiplos objetos segue este desenho."},{"id":"cv-trk-03","titulo":"Kalman e algoritmo húngaro","prioridade":"fundamental","desc":"Predição de estado e associação ótima.","detalhe":"O filtro de Kalman prevê onde cada trilha deve estar no próximo frame assumindo movimento aproximadamente constante, e funde essa previsão com a medição, ponderando pela incerteza de cada uma. O algoritmo húngaro então resolve a atribuição ótima entre trilhas previstas e detecções novas, minimizando o custo total — tipicamente baseado em IoU ou distância. Juntos, eles são o SORT."},{"id":"cv-trk-04","titulo":"SORT, DeepSORT e ByteTrack","prioridade":"fundamental","desc":"Associação por movimento, por aparência e por detecções fracas.","detalhe":"SORT associa só por posição e é rápido, mas troca IDs em cruzamentos. DeepSORT acrescenta um descritor de aparência, o que permite reidentificar após oclusão, ao custo de uma rede extra por objeto. ByteTrack teve a percepção de que detecções de BAIXA confiança, normalmente descartadas, costumam ser objetos ocluídos — associá-las numa segunda rodada melhora bastante sem custo adicional."},{"id":"cv-trk-05","titulo":"Métricas de tracking","prioridade":"importante","desc":"MOTA, IDF1 e troca de identidade.","detalhe":"MOTA agrega falsos positivos, falsos negativos e trocas de ID num número só, e por isso é dominada pela qualidade da detecção. IDF1 mede quão bem a identidade foi preservada ao longo do tempo e é a métrica honesta para avaliar a ASSOCIAÇÃO. Reportar as duas é o que separa \"meu detector é bom\" de \"meu tracking é bom\"."},{"id":"cv-trk-06","titulo":"Optical flow","prioridade":"importante","desc":"Lucas-Kanade (esparso) e Farnebäck (denso).","detalhe":"Optical flow estima o deslocamento aparente dos pixels entre frames. Lucas-Kanade acompanha poucos pontos bons de rastrear e é barato; Farnebäck calcula o campo para todos os pixels e é caro. Ambos assumem brilho constante e movimento pequeno entre frames — uma mudança brusca de iluminação ou um objeto rápido quebram a premissa."},{"id":"cv-trk-07","titulo":"Contagem e regiões de interesse","prioridade":"fundamental","desc":"Estimativa de movimento, linhas de contagem e ROI.","detalhe":"Contar por linha virtual exige identidade estável e uma regra de cruzamento robusta: compare a posição do centro em relação à linha entre frames consecutivos e conte a TRANSIÇÃO, uma vez por ID. Contar presença dentro da ROI frame a frame é o erro clássico que infla o número em dezenas de vezes. Para velocidade, você precisa de escala — e sem calibração (iteração 10) a estimativa é relativa."},{"id":"cv-trk-08","titulo":"Oclusão e reidentificação","prioridade":"importante","desc":"Oclusão, reentrada em cena e re-ID.","detalhe":"Os dois parâmetros que o critério de domínio cobra são justamente destes: `max_age` (quantos frames manter uma trilha sem detecção) e o limiar de associação. `max_age` curto demais faz as trilhas sumirem cedo em oclusões; longo demais faz trilhas fantasmas capturarem objetos errados. Limiar de associação frouxo troca IDs; apertado fragmenta trilhas."}]}]},{"id":"avancadas","numero":9,"titulo":"Arquiteturas avançadas","objetivo":"Alcançar o estado da arte atual, onde visão e linguagem convergem.","descricao":"A mudança conceitual desta iteração é que o modelo deixa de ser treinado para o SEU conjunto de classes. CLIP classifica categorias que nunca viu rotuladas, GroundingDINO detecta pelo nome em texto livre, SAM segmenta sem saber o que está segmentando. Na prática isso muda o início de qualquer projeto: antes de anotar, vale testar o que um modelo zero-shot já resolve — e, quando não resolve sozinho, usá-lo para gerar os rótulos iniciais que você depois corrige. O risco correspondente é se enganar com exemplos escolhidos a dedo: zero-shot impressiona na demo e decepciona no conjunto de teste.","preRequisitos":"Etapa 5","duracao":null,"criterios":["Você explica quando ViT supera CNN e quando não vale o custo.","Você usa modelos zero-shot para gerar rótulos iniciais e reduzir custo de anotação.","Você sabe avaliar um resultado zero-shot sem se enganar com exemplos escolhidos a dedo."],"grupos":[{"id":"cv-g-adv-1","titulo":"Transformers em visão","topicos":[{"id":"cv-adv-01","titulo":"Atenção e self-attention","prioridade":"fundamental","desc":"A arquitetura transformer.","detalhe":"Self-attention deixa cada posição consultar todas as outras e decidir de quais depende, o que dá campo receptivo global já na primeira camada — contra o crescimento gradual da CNN. O preço é custo quadrático no número de tokens, razão pela qual imagens são cortadas em patches em vez de tratadas pixel a pixel."},{"id":"cv-adv-02","titulo":"Vision Transformer (ViT)","prioridade":"fundamental","desc":"Patches, embeddings posicionais e token de classificação.","detalhe":"O ViT corta a imagem em patches de 16×16, projeta cada um num vetor e trata a sequência como texto. Como a atenção não tem noção de ordem, o embedding posicional é o que reintroduz a geometria. O token de classificação é um vetor extra que agrega a informação de todos os patches e alimenta a cabeça final — ideia herdada do BERT."},{"id":"cv-adv-03","titulo":"Swin Transformer","prioridade":"importante","desc":"Atenção hierárquica em janelas.","detalhe":"O Swin calcula atenção dentro de janelas locais e desloca essas janelas a cada camada, o que restaura a comunicação entre elas. Isso derruba o custo de quadrático para linear na resolução e recupera a hierarquia multiescala que as CNNs têm naturalmente — por isso ele funciona bem como backbone de detecção e segmentação, onde o ViT puro é desajeitado."},{"id":"cv-adv-04","titulo":"Por que ViT precisa de mais dados","prioridade":"fundamental","desc":"O papel do pré-treino em larga escala.","detalhe":"A CNN traz embutidas duas suposições corretas sobre imagens: pixels vizinhos se relacionam e um padrão é o mesmo em qualquer posição. O ViT não traz nenhuma das duas e precisa APRENDER isso dos dados — daí precisar de escala. Treinado só no seu dataset de 5 mil imagens, ele perde para uma ResNet; partindo de pré-treino massivo, ganha. É exatamente a resposta ao critério de domínio desta iteração."}]},{"id":"cv-g-adv-2","titulo":"Sem rótulos e com linguagem","topicos":[{"id":"cv-adv-05","titulo":"Aprendizado autossupervisionado","prioridade":"importante","desc":"SimCLR, MoCo, MAE e DINO.","detalhe":"A ideia é inventar uma tarefa cujo rótulo vem dos próprios dados: reconhecer que duas augmentações da mesma imagem são a mesma coisa (SimCLR, MoCo), ou reconstruir pedaços mascarados (MAE). Isso aproveita imagem não anotada, que você provavelmente tem aos milhares. DINO produz, de brinde, mapas de atenção que segmentam objetos sem nunca ter visto uma máscara."},{"id":"cv-adv-06","titulo":"Modelos visão-linguagem","prioridade":"fundamental","desc":"CLIP, embeddings compartilhados e classificação zero-shot.","detalhe":"O CLIP treina um codificador de imagem e um de texto para projetarem no MESMO espaço, aproximando os pares corretos. Classificar sem treino vira comparar o embedding da imagem com o de frases como \"uma foto de um gato\". O resultado depende muito da formulação do prompt — medir essa variação é o projeto desta iteração. O mesmo espaço compartilhado também dá busca por similaridade de graça."},{"id":"cv-adv-07","titulo":"Vocabulário aberto","prioridade":"importante","desc":"GroundingDINO e SAM.","detalhe":"GroundingDINO detecta a partir de uma descrição textual, devolvendo caixas; alimentando essas caixas ao SAM, você obtém máscaras. O pipeline \"texto, caixa, máscara\" produz dataset de segmentação sem anotação manual inicial. Trate o resultado como rascunho a revisar, não como verdade — mas um rascunho que corta a maior parte do trabalho."},{"id":"cv-adv-08","titulo":"Modelos generativos","prioridade":"opcional","desc":"GANs, autoencoders e modelos de difusão.","detalhe":"Em visão aplicada, o uso mais concreto é gerar dados sintéticos para classes raras e traduzir entre domínios (sintético para real, dia para noite). Difusão substituiu as GANs na maior parte dos casos por treinar de forma estável, sem o colapso de modo. Autoencoders continuam úteis para detecção de anomalia: o erro de reconstrução sinaliza o que foge do normal."},{"id":"cv-adv-09","titulo":"Super-resolução e restauração","prioridade":"opcional","desc":"Aumentar resolução e remover degradação.","detalhe":"Útil quando a captura é limitada — placa distante, imagem médica de baixa dose. A ressalva crítica é que esses modelos ALUCINAM detalhe plausível: o resultado parece nítido mas o conteúdo é inventado. Em domínio forense ou clínico isso é inaceitável, e a métrica que conta não é a perceptual, é se a tarefa seguinte melhorou."}]}]},{"id":"visao3d","numero":10,"titulo":"Visão 3D","objetivo":"Recuperar geometria a partir de imagens.","descricao":"Uma imagem é uma projeção: a terceira dimensão foi descartada na captura. Esta iteração é sobre recuperá-la, e a primeira lição é que isso exige ou duas vistas, ou movimento, ou uma suposição aprendida sobre o mundo. A calibração é o alicerce de tudo o que vem depois — intrínsecos errados contaminam disparidade, nuvem de pontos, reconstrução e SLAM, e o erro aparece lá na frente, disfarçado de outra coisa. Boa parte dos problemas que parecem precisar de 3D se resolve com uma heurística 2D mais barata; saber distinguir os casos é o critério de domínio aqui.","preRequisitos":"Etapa 2","duracao":null,"criterios":["Você explica por que profundidade monocular é relativa e o que é preciso para torná-la métrica.","Você identifica quando o problema exige geometria de verdade e quando uma heurística 2D basta.","Você reconhece os efeitos de uma calibração ruim nos resultados seguintes do pipeline."],"grupos":[{"id":"cv-g-3d","titulo":null,"topicos":[{"id":"cv-3d-01","titulo":"Modelo de câmera pinhole","prioridade":"fundamental","desc":"Parâmetros intrínsecos e extrínsecos.","detalhe":"Intrínsecos descrevem a câmera em si — distância focal em pixels e ponto principal — e formam a matriz K. Extrínsecos descrevem onde ela está no mundo: rotação e translação. A projeção é a composição das duas, e é por isso que, sem conhecer K, você consegue dizer que um objeto está mais longe, mas não quantos metros."},{"id":"cv-3d-02","titulo":"Calibração e distorção","prioridade":"fundamental","desc":"Calibração de câmera e correção de distorção.","detalhe":"Lentes reais curvam linhas retas, especialmente grande-angulares. A calibração com padrão de xadrez estima K e os coeficientes de distorção a partir de pontos de geometria conhecida. Dicas que decidem a qualidade: use 15 a 20 imagens com o padrão em orientações e profundidades variadas, cobrindo os CANTOS do quadro, que é onde a distorção é maior. Um erro de reprojeção acima de ~1 pixel indica calibração a refazer."},{"id":"cv-3d-03","titulo":"Geometria epipolar e estéreo","prioridade":"importante","desc":"Visão estéreo e mapa de disparidade.","detalhe":"Com duas câmeras, a restrição epipolar reduz a busca pelo ponto correspondente de duas dimensões para uma linha — é o que torna o estéreo computável. A disparidade (deslocamento horizontal) é inversamente proporcional à profundidade, com a constante dada pela linha de base e pela focal. Superfícies sem textura não têm correspondência confiável, e é ali que o mapa de profundidade vem esburacado."},{"id":"cv-3d-04","titulo":"Profundidade monocular","prioridade":"importante","desc":"MiDaS, Depth Anything.","detalhe":"Esses modelos aprenderam pistas que humanos também usam: tamanho relativo, oclusão, perspectiva, textura. O resultado é profundidade RELATIVA, ou seja, ordenação — sem escala absoluta, porque uma maquete e uma casa projetam a mesma imagem. Para torná-la métrica você precisa de uma referência: um objeto de tamanho conhecido, um sensor de profundidade ou estéreo."},{"id":"cv-3d-05","titulo":"Nuvens de pontos","prioridade":"importante","desc":"Representação, registro (ICP) e Open3D.","detalhe":"Nuvem de pontos é um conjunto de coordenadas 3D, possivelmente com cor e normal. ICP alinha duas nuvens iterando entre \"achar correspondências mais próximas\" e \"calcular a transformação que as alinha\". Ele converge para o mínimo local mais próximo, então precisa de uma inicialização razoável — alinhamento grosseiro por features globais primeiro, ICP para refinar."},{"id":"cv-3d-06","titulo":"Structure from Motion","prioridade":"opcional","desc":"Reconstrução multi-vista.","detalhe":"SfM recupera simultaneamente as poses das câmeras e a estrutura 3D a partir de várias fotos não calibradas, casando features entre elas. É o que está por trás de reconstruir um objeto a partir de fotos de celular. Exige sobreposição generosa entre vistas e textura suficiente; parede lisa e superfície reflexiva derrubam o processo."},{"id":"cv-3d-07","titulo":"SLAM","prioridade":"opcional","desc":"Odometria visual, mapeamento e fechamento de laço.","detalhe":"SLAM resolve mapeamento e localização ao mesmo tempo, em tempo real. A odometria acumula erro a cada frame — é a deriva que o exercício manda medir. O fechamento de laço é o mecanismo de correção: ao reconhecer um lugar já visitado, o sistema redistribui o erro acumulado por todo o percurso. Sem ele, um trajeto fechado não fecha."},{"id":"cv-3d-08","titulo":"NeRF e Gaussian Splatting","prioridade":"opcional","desc":"Representação neural de cena.","detalhe":"NeRF representa a cena como uma função contínua que, dada uma posição e uma direção de visada, devolve cor e densidade — e renderiza vistas novas com realismo alto, ao custo de horas de otimização por cena. Gaussian Splatting alcança qualidade comparável com treino e renderização muito mais rápidos, o que o tornou a escolha prática atual."}]}]},{"id":"edge","numero":11,"titulo":"Tempo real e edge","objetivo":"O mesmo modelo, rodando dentro das restrições reais de hardware.","descricao":"Esta iteração é o que separa protótipo de produto, e a ordem importa: meça primeiro, otimize depois. A descoberta recorrente de quem perfila um pipeline de visão pela primeira vez é que a inferência não é o gargalo — decodificação de vídeo, redimensionamento, cópia entre CPU e GPU e NMS costumam consumir mais tempo que o modelo. Otimizar a rede antes de saber disso é esforço aplicado no lugar errado. A entrega desta iteração não é um número de FPS: é uma tabela de acurácia contra latência que sustenta uma decisão.","preRequisitos":"Etapa 6","duracao":null,"criterios":["Você apresenta uma tabela de acurácia versus latência e defende uma escolha com base nela.","Você descobre e corrige um gargalo que estava fora da inferência.","Você mede corretamente, descartando as primeiras iterações e sincronizando a GPU."],"grupos":[{"id":"cv-g-edge-1","titulo":"Medir antes de otimizar","topicos":[{"id":"cv-edge-01","titulo":"Medição correta","prioridade":"fundamental","desc":"Latência, throughput, FPS, uso de memória e warm-up.","detalhe":"Três erros arruínam qualquer medição de GPU: não descartar as primeiras iterações (o warm-up inclui alocação e compilação de kernels), não sincronizar antes de parar o cronômetro (as chamadas CUDA são assíncronas e você acaba medindo o tempo de enfileirar) e reportar a média sem a cauda. Relate a mediana e o percentil 95 — é a cauda que estoura o orçamento de tempo real."},{"id":"cv-edge-02","titulo":"Mapeamento de gargalos","prioridade":"fundamental","desc":"Pré-processamento, cópia CPU↔GPU, decodificação, pós-processamento.","detalhe":"Cronometre cada estágio separadamente antes de tocar no modelo. Decodificar H.264 em CPU pode custar mais que a inferência inteira; o redimensionamento em CPU, idem; e cada cópia entre CPU e GPU é tempo puro. NMS com muitas caixas também aparece com frequência no topo do perfil. É aqui que mora o critério de domínio sobre o gargalo fora da inferência."},{"id":"cv-edge-03","titulo":"Batching e assincronia","prioridade":"importante","desc":"Inferência assíncrona e paralelismo em pipeline.","detalhe":"Batch aumenta o throughput mas também a latência do primeiro resultado — se a aplicação é interativa, isso pode ser inaceitável. Paralelismo em pipeline (decodificar o frame N+1 enquanto o N é inferido) é o ganho mais barato em vídeo, porque sobrepõe trabalho de CPU e GPU que hoje acontece em sequência."}]},{"id":"cv-g-edge-2","titulo":"Comprimir e acelerar","topicos":[{"id":"cv-edge-04","titulo":"Exportação de modelos","prioridade":"fundamental","desc":"ONNX e o grafo de inferência.","detalhe":"ONNX é o formato intermediário que desacopla o treino do runtime. A exportação congela o grafo e remove tudo que só servia ao treino. Armadilhas comuns: controle de fluxo dependente de dados não exporta bem, e dimensões dinâmicas precisam ser declaradas explicitamente ou o modelo só aceita o tamanho exato usado na exportação. Sempre confira que a saída do ONNX bate com a do PyTorch dentro de uma tolerância."},{"id":"cv-edge-05","titulo":"Runtimes","prioridade":"fundamental","desc":"ONNX Runtime, TensorRT, OpenVINO e TFLite.","detalhe":"Cada um é especializado no seu hardware: TensorRT em GPUs NVIDIA, OpenVINO em CPUs e aceleradores Intel, TFLite em móvel, ONNX Runtime como opção portátil. Eles aceleram fundindo operações (convolução, BatchNorm e ReLU viram um kernel só) e escolhendo implementações otimizadas. Ganhos de 2 a 5 vezes sem perda de acurácia são comuns só com a troca de runtime."},{"id":"cv-edge-06","titulo":"Quantização","prioridade":"fundamental","desc":"Dinâmica, estática e QAT; INT8 e FP16.","detalhe":"FP16 costuma ser ganho quase gratuito em GPU moderna, com perda desprezível. INT8 dá mais velocidade e menos memória, mas exige calibração com dados representativos para escolher as escalas, e pode custar acurácia. QAT simula a quantização durante o treino e recupera boa parte dessa perda. A regra inegociável: reavalie a acurácia DEPOIS de quantizar, no mesmo conjunto de teste."},{"id":"cv-edge-07","titulo":"Pruning e distilação","prioridade":"importante","desc":"Poda, distilação de conhecimento e backbone leve.","detalhe":"Pruning remove pesos ou canais pouco importantes; o não estruturado comprime bem mas só acelera com suporte de hardware a esparsidade, enquanto o estruturado (canais inteiros) acelera em qualquer lugar. Distilação treina um modelo pequeno para imitar as saídas de um grande e costuma superar o mesmo modelo pequeno treinado direto nos rótulos. E às vezes o caminho mais curto é simplesmente trocar o backbone por um MobileNet."},{"id":"cv-edge-08","titulo":"Hardware","prioridade":"importante","desc":"Jetson, Raspberry Pi, Coral TPU e aceleradores móveis.","detalhe":"Cada plataforma impõe o seu formato: Jetson quer TensorRT, Coral exige INT8 totalmente quantizado e um conjunto restrito de operações, Raspberry Pi sem acelerador é CPU pura. Decida o hardware ANTES de escolher a arquitetura — descobrir que o seu modelo usa uma operação não suportada depois de treinado é um retrabalho caro."},{"id":"cv-edge-09","titulo":"Decodificação acelerada e GStreamer","prioridade":"opcional","desc":"Decodificação de vídeo em hardware.","detalhe":"GPUs e SoCs trazem decodificadores de vídeo dedicados que liberam a CPU por completo. Com GStreamer é possível montar um pipeline que decodifica em hardware e entrega o frame já na memória da GPU, eliminando a cópia. Em sistemas com muitas câmeras simultâneas, isso é frequentemente a diferença entre viável e inviável."},{"id":"cv-edge-10","titulo":"Trade-off explícito","prioridade":"fundamental","desc":"Acurácia perdida contra velocidade ganha.","detalhe":"A entrega concreta é uma tabela: para cada configuração, acurácia, latência mediana, p95, memória e tamanho. Com ela, a decisão deixa de ser preferência e vira argumento — \"perdemos 1,2 ponto de mAP e ganhamos 3,4 vezes em velocidade, e o requisito é 25 FPS\". Sem ela, qualquer escolha é defensável e nenhuma é justificada."}]}]},{"id":"deploy","numero":12,"titulo":"Full stack e deploy","objetivo":"Transformar o modelo em um sistema que outra pessoa consegue usar.","descricao":"O critério de domínio desta iteração é desconfortável de propósito: outra pessoa clona o seu repositório, roda um comando e o sistema funciona. Notebook que só roda na sua máquina não conta. Esta é a iteração mais larga do roadmap porque cruza para outra disciplina — API, banco, fila, container, nuvem, observabilidade. Não é preciso profundidade em tudo: o objetivo é conseguir entregar uma fatia vertical completa, da imagem enviada ao resultado exibido, com log e medição no caminho.","preRequisitos":"Etapa 6","duracao":null,"criterios":["Outra pessoa clona seu repositório, roda um comando e o sistema funciona.","Você justifica o que roda no servidor e o que roda no navegador, considerando latência e privacidade.","Você sabe o que acontece sob 10 requisições simultâneas, porque mediu."],"grupos":[{"id":"cv-g-dep-1","titulo":"Interface e API","topicos":[{"id":"cv-dep-01","titulo":"Fundamentos web","prioridade":"importante","desc":"HTML, CSS e JavaScript.","detalhe":"O suficiente para montar uma página que envia uma imagem e desenha o resultado. Para visão, o elemento que importa é o `<canvas>`: é nele que você sobrepõe caixas e máscaras ao frame. Vale conhecer também `getUserMedia`, que dá acesso à webcam direto do navegador."},{"id":"cv-dep-02","titulo":"Framework de frontend","prioridade":"opcional","desc":"React.js ou Vue.js.","detalhe":"Só compensa quando a interface tem estado de verdade — lista de resultados, filtros, histórico, upload com progresso. Para uma demo de uma tela, HTML e JavaScript puros entregam mais rápido e com menos a manter. Escolha pelo tamanho do problema, não pelo currículo."},{"id":"cv-dep-03","titulo":"Backend em Python","prioridade":"fundamental","desc":"FastAPI (recomendado), Flask ou Django.","detalhe":"FastAPI é a escolha natural aqui: valida entrada e saída com tipos, gera documentação interativa sozinho e suporta assíncrono nativamente. O detalhe que mais importa em visão: carregue o modelo UMA vez na inicialização e reaproveite entre requisições — carregá-lo por requisição transforma 30 ms em 3 segundos."},{"id":"cv-dep-04","titulo":"APIs REST","prioridade":"fundamental","desc":"Rotas, upload de arquivos, validação e códigos de erro.","detalhe":"Defina um contrato explícito: tipos e tamanho máximo aceitos, formato da resposta, e o que acontece quando a imagem é inválida. Responda 400 para entrada ruim e 500 só para falha sua — misturar os dois torna impossível distinguir cliente errado de servidor quebrado no monitoramento. Imponha limite de tamanho: sem ele, um upload de 200 MB derruba o processo."},{"id":"cv-dep-05","titulo":"WebSockets","prioridade":"importante","desc":"Vídeo ao vivo e atualizações em tempo real.","detalhe":"HTTP não serve para fluxo contínuo: o custo por requisição domina. WebSocket mantém a conexão aberta nos dois sentidos. A decisão de projeto é o que trafega — enviar o frame inteiro codificado e devolver JSON com as detecções costuma ser mais barato que devolver o frame anotado. E descarte frames quando o servidor atrasar, em vez de acumular fila."},{"id":"cv-dep-06","titulo":"Streaming de vídeo","prioridade":"importante","desc":"MJPEG, WebRTC e suas limitações.","detalhe":"MJPEG é trivial de implementar e esbanja banda, porque cada frame é um JPEG independente. WebRTC é o caminho de baixa latência de verdade, com compressão e adaptação à rede, ao custo de infraestrutura adicional (STUN/TURN). Para demo interna, MJPEG; para produto, WebRTC."}]},{"id":"cv-g-dep-2","titulo":"Dados, empacotamento e operação","topicos":[{"id":"cv-dep-07","titulo":"Banco de dados","prioridade":"importante","desc":"PostgreSQL e MongoDB; metadados e resultados.","detalhe":"Guarde metadados e resultados no banco e a mídia fora dele — blob de imagem em tabela incha o banco e estraga backup e replicação. PostgreSQL com coluna JSONB cobre bem resultados de formato variável sem abrir mão de consultas e integridade. O que você vai querer consultar depois: data, modelo e versão usados, tempo de inferência e confiança."},{"id":"cv-dep-08","titulo":"Armazenamento de mídia","prioridade":"importante","desc":"Sistema de arquivos versus object storage (S3).","detalhe":"Sistema de arquivos local é simples e não escala além de uma máquina; object storage dá durabilidade, URLs assinadas e acesso de múltiplos processos. O padrão que evita trafegar a imagem pelo seu servidor duas vezes: o cliente envia direto para o storage com URL pré-assinada e manda ao backend apenas a chave."},{"id":"cv-dep-09","titulo":"Filas e processamento assíncrono","prioridade":"importante","desc":"Tarefas pesadas fora do ciclo da requisição.","detalhe":"Processar um vídeo de 10 minutos dentro de uma requisição HTTP garante timeout. O padrão é: aceitar, devolver um ID de tarefa, processar em worker e expor o status por consulta ou notificação. A fila também é o que protege a GPU de ser disputada por dez requisições simultâneas — que é o que o critério de domínio manda você medir."},{"id":"cv-dep-10","titulo":"Docker","prioridade":"fundamental","desc":"Imagens, volumes, GPU no container e `docker compose`.","detalhe":"É o que torna \"clona e roda um comando\" verdadeiro. Para GPU é preciso a imagem base CUDA correta e o runtime da NVIDIA; a versão do CUDA dentro do container tem que ser compatível com o driver do host. Use build em múltiplos estágios para não carregar compilador na imagem final, e monte modelos e dados como volume em vez de embuti-los, para não gerar imagens de vários gigabytes."},{"id":"cv-dep-11","titulo":"Nuvem","prioridade":"importante","desc":"AWS, GCP ou Azure — computação, storage e GPU.","detalhe":"Instância com GPU é cara por hora e é o custo que surpreende. Para carga intermitente, considere inferência em CPU com modelo otimizado (iteração 11) ou função serverless; a GPU dedicada só se justifica com uso contínuo. Configure alerta de gasto antes de subir qualquer coisa — a conta esquecida é um clássico."},{"id":"cv-dep-12","titulo":"Servidores de inferência","prioridade":"opcional","desc":"TorchServe, Triton e BentoML.","detalhe":"Resolvem de forma pronta o que você escreveria à mão: batching dinâmico, múltiplas versões do modelo em paralelo, métricas e health check. Triton ainda roda modelos de frameworks diferentes no mesmo servidor. Valem quando há vários modelos ou tráfego sério; para um modelo só, FastAPI é mais simples de operar."},{"id":"cv-dep-13","titulo":"Observabilidade","prioridade":"fundamental","desc":"Logs estruturados, métricas, tracing e alertas.","detalhe":"Log estruturado em JSON é consultável; log em texto livre é arqueologia. Registre latência por estágio, taxa de erro e distribuição das confianças — essa última é o seu detector precoce de drift, porque a confiança média cai antes de a acurácia desabar. Alerta só no que exige ação humana, senão ele vira ruído e deixa de ser lido."},{"id":"cv-dep-14","titulo":"Visão no navegador","prioridade":"opcional","desc":"TensorFlow.js e OpenCV.js.","detalhe":"Rodar no cliente elimina latência de rede e mantém a imagem no dispositivo, o que resolve privacidade de um jeito que nenhuma política de servidor resolve. As limitações são reais: modelo pequeno, desempenho variável entre dispositivos e download inicial pesado. É a resposta ao critério de domínio sobre o que roda onde."},{"id":"cv-dep-15","titulo":"Versionamento de modelos e dados","prioridade":"fundamental","desc":"Rastreabilidade e rollback.","detalhe":"Toda predição deveria ser rastreável até a versão exata de modelo e dataset que a gerou — sem isso você não consegue explicar uma regressão nem voltar atrás. Ferramentas como DVC versionam dados junto com o código. Mantenha a versão anterior pronta para servir: rollback precisa ser uma troca de configuração, não um retreino."}]}]},{"id":"capstone","numero":13,"titulo":"Capstone","objetivo":"Integrar tudo em um sistema único, com escopo real e limitações declaradas.","descricao":"Prefira um problema do seu próprio contexto, com dados aos quais você tem acesso. A dificuldade real de um capstone quase nunca está no modelo; está em obter e anotar dados representativos, e em admitir por escrito onde o sistema falha. Os tópicos desta etapa são os critérios de conclusão do roadmap transformados em itens de trabalho: cada um é uma entrega verificável, e a ordem entre eles importa — definir a métrica depois de ver os resultados é a forma mais fácil de se enganar.","preRequisitos":"Etapas 11 e 12","duracao":null,"grupos":[{"id":"cv-g-cap","titulo":null,"topicos":[{"id":"cv-cap-01","titulo":"Problema e métrica definidos antes","prioridade":"fundamental","desc":"Métrica de sucesso declarada antes de começar.","detalhe":"Escreva, antes de tocar no código, qual número precisa atingir qual valor para o projeto ser considerado bem-sucedido, e por que esse número reflete o custo real do erro. Métrica escolhida depois dos resultados é sempre a que favorece o que você já obteve — e essa é a forma mais comum e mais invisível de autoengano técnico."},{"id":"cv-cap-02","titulo":"Dataset versionado e dividido","prioridade":"fundamental","desc":"Treino, validação e teste sem vazamento.","detalhe":"Em visão, divida por FONTE, não por arquivo: todos os frames de um mesmo vídeo, todas as fotos de uma mesma sessão ou de um mesmo paciente ficam no mesmo lado. Divisão aleatória por imagem coloca quadros quase idênticos nos dois lados e produz uma validação otimista que não sobrevive à produção."},{"id":"cv-cap-03","titulo":"Baseline antes do modelo complexo","prioridade":"fundamental","desc":"Linha de base simples implementada primeiro.","detalhe":"Comece pelo trivial: a classe majoritária, uma heurística clássica da iteração 1, um modelo pré-treinado sem ajuste. O baseline serve a dois propósitos — mede quanto a complexidade realmente agrega e, com frequência, revela que o problema é mais fácil ou mais difícil do que parecia. Modelo complexo sem baseline é um número sem régua."},{"id":"cv-cap-04","titulo":"Avaliação com as métricas corretas","prioridade":"fundamental","desc":"As métricas da tarefa, e não apenas acurácia.","detalhe":"Classificação desbalanceada pede F1 por classe e matriz de confusão; detecção pede mAP nos dois limiares e análise por classe; segmentação pede IoU e Dice. Reporte também a variação entre execuções com seeds diferentes: um número único sem noção de dispersão não permite dizer se a sua melhoria é real."},{"id":"cv-cap-05","titulo":"Análise dos piores casos","prioridade":"fundamental","desc":"Exemplos visuais dos erros.","detalhe":"Separe os N piores erros e olhe para eles um a um. Os padrões que aparecem quase sempre são de três tipos: rótulo errado, classe genuinamente ambígua, ou condição não representada no treino (iluminação, ângulo, escala). Cada um pede uma ação diferente, e nenhum deles é visível no agregado da métrica."},{"id":"cv-cap-06","titulo":"Latência e FPS no hardware alvo","prioridade":"fundamental","desc":"Medição no dispositivo real.","detalhe":"Aplique o rigor da iteração 11: warm-up descartado, GPU sincronizada, mediana e p95 reportados, e a medição feita no hardware onde o sistema vai rodar. Número obtido na sua RTX não diz nada sobre o comportamento em uma Jetson — e é no dispositivo alvo que o requisito precisa ser cumprido."},{"id":"cv-cap-07","titulo":"Sistema empacotado e executável","prioridade":"fundamental","desc":"Executável por terceiros e documentado.","detalhe":"O teste honesto é pedir a alguém que siga o seu README numa máquina limpa, sem fazer perguntas, e anotar onde essa pessoa trava. Tudo que ela precisou perguntar é documentação faltando. Docker com um comando de subida resolve a maior parte dos casos."},{"id":"cv-cap-08","titulo":"README com decisões e resultados","prioridade":"fundamental","desc":"Arquitetura, decisões, resultados e limitações.","detalhe":"Documente as alternativas que você considerou e descartou, com o motivo — isso vale mais para quem lê (e para você em seis meses) do que a descrição do que ficou. Inclua a tabela de acurácia contra latência e seja explícito sobre as limitações: um projeto que declara onde falha demonstra mais maturidade técnica do que um que promete funcionar sempre."},{"id":"cv-cap-09","titulo":"Condições de falha declaradas","prioridade":"fundamental","desc":"Lista explícita de onde o sistema falha.","detalhe":"Teste deliberadamente fora da distribuição: pouca luz, ângulo extremo, oclusão, objeto fora do conjunto de classes, imagem corrompida. Escreva o que acontece em cada caso. Um sistema que sabe dizer \"não sei\" com confiança calibrada é muito mais útil em produção do que um que responde com alta confiança sobre algo que nunca viu."}]}]}]},"PROJETOS":{"pre":["Construir uma CLI que recebe uma imagem ou vídeo, aplica uma transformação e grava o resultado.","Fazer a CLI funcionar com webcam ao vivo, exibindo o FPS na tela.","Tratar os erros reais: arquivo inexistente, codec ausente, câmera ocupada."],"classica":["Detector de objeto por cor em HSV, com trackbars para calibrar os limiares ao vivo.","Contador de objetos em uma imagem usando limiarização, morfologia e contornos.","Alinhamento de dois ângulos da mesma cena usando ORB e homografia.","Detector de movimento em vídeo com subtração de fundo, ignorando ruído por área mínima."],"matematica":["Implementar convolução 2D do zero em NumPy e comparar com `cv2.filter2D`.","Escrever os kernels de Sobel, blur e sharpen à mão e explicar por que funcionam.","Implementar gradiente descendente para uma regressão linear, imprimindo a perda por época.","Aplicar PCA a um conjunto de imagens e reconstruí-las com poucos componentes."],"ml-classico":["Classificador de imagens com HOG + SVM, encapsulado em um `Pipeline` do scikit-learn.","Comparar KNN, Random Forest e SVM no mesmo dataset com validação cruzada.","Produzir a matriz de confusão e analisar quais classes se confundem e por quê.","Repetir o experimento com um dataset propositalmente desbalanceado e observar a acurácia enganar."],"redes":["Implementar uma rede densa do zero em NumPy (forward e backward) para um problema simples.","Treinar uma CNN pequena em PyTorch no CIFAR-10 ou dataset equivalente.","Plotar curvas de perda e acurácia de treino e validação, e identificar o ponto de overfitting.","Escrever um `Dataset` customizado que lê imagens do seu próprio diretório."],"cnns":["Montar um dataset próprio de classificação (mínimo 3 classes, 200 imagens por classe).","Fazer fine-tuning de uma ResNet e comparar com a mesma arquitetura treinada do zero.","Aplicar Grad-CAM e verificar se o modelo olha para a região correta da imagem.","Registrar todos os experimentos com hiperparâmetros e resultados rastreáveis."],"deteccao":["Rodar um YOLO pré-treinado em vídeo e medir o FPS.","Anotar um dataset próprio (mínimo 300 imagens) e treinar um detector nele.","Avaliar por classe e identificar qual classe puxa o mAP para baixo, e por quê.","Ajustar limiares de confiança e NMS para o custo real do falso positivo no seu domínio."],"segmentacao":["Treinar uma U-Net em um dataset de segmentação binária.","Comparar cross-entropy contra Dice loss em um dataset com classes desbalanceadas.","Sobrepor a máscara prevista à imagem e inspecionar visualmente os piores casos.","Usar SAM para acelerar a anotação de um dataset próprio."],"tracking":["Acoplar um tracker ao seu detector da iteração 6 e manter IDs estáveis.","Contar objetos que cruzam uma linha virtual, sem contar duas vezes.","Medir velocidade aproximada de objetos e discutir a fonte de erro da estimativa.","Provocar oclusões propositais e medir quantas trocas de ID ocorrem."],"avancadas":["Fazer fine-tuning de um ViT no dataset da iteração 5 e comparar com a CNN.","Usar CLIP para classificação zero-shot e medir o quanto o prompt altera o resultado.","Construir busca por similaridade em um acervo de imagens usando embeddings.","Usar GroundingDINO combinado com SAM para segmentar por descrição textual."],"visao3d":["Calibrar uma câmera real com um padrão de xadrez e corrigir a distorção.","Gerar um mapa de profundidade monocular e convertê-lo em nuvem de pontos.","Reconstruir um objeto pequeno a partir de múltiplas fotos.","Rodar um SLAM visual em um vídeo e avaliar a deriva ao longo do percurso."],"edge":["Estabelecer a linha de base medindo o modelo da iteração 6 com rigor.","Exportar para ONNX e reexecutar a medição.","Quantizar para INT8 e registrar acurácia e latência antes e depois.","Perfilar o pipeline completo e descobrir quanto do tempo NÃO é o modelo.","Rodar em hardware limitado (ou simulado) e alcançar a meta de FPS."],"deploy":["Expor o detector como API que recebe uma imagem e devolve detecções em JSON.","Construir um frontend que consome a API e desenha as caixas sobre a imagem.","Implementar streaming ao vivo por WebSocket, com o processamento no servidor.","Persistir cada inferência em banco, com metadados, e criar uma tela de histórico.","Empacotar tudo em Docker e subir em uma instância na nuvem.","Instrumentar latência por requisição e taxa de erro."],"capstone":["Multi-Object Tracking com detecção de anomalias em tempo real.","Reconstrução 3D de objetos usando Neural Radiance Fields (NeRF).","Super-resolução de imagens médicas com deep learning.","Reconhecimento de gestos em tempo real para interfaces de realidade aumentada.","Navegação autônoma de drone com desvio de obstáculos.","Análise de fluxo de tráfego em tempo real a partir de imagens de drone."]},"RECURSOS":[{"etapa":"pre","titulo":"Documentação do OpenCV","url":"https://docs.opencv.org/","nota":"Referência oficial"},{"etapa":"pre","titulo":"Documentação do NumPy","url":"https://numpy.org/doc/","nota":"Base de todo o resto"},{"etapa":"classica","titulo":"OpenCV — tutoriais de processamento de imagem","url":"https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html","nota":"Passo a passo do módulo imgproc"},{"etapa":"matematica","titulo":"Linear Algebra — Gilbert Strang (MIT OCW)","url":"https://ocw.mit.edu/courses/18-06-linear-algebra-spring-2010/","nota":"Álgebra linear"},{"etapa":"matematica","titulo":"Calculus — Khan Academy","url":"https://www.khanacademy.org/math/calculus-1","nota":"Cálculo"},{"etapa":"ml-classico","titulo":"Guia do usuário do scikit-learn","url":"https://scikit-learn.org/stable/user_guide.html","nota":"Algoritmos e avaliação"},{"etapa":"redes","titulo":"Tutoriais do PyTorch","url":"https://pytorch.org/tutorials/","nota":"Tensores, autograd e loop de treino"},{"etapa":"cnns","titulo":"CS231n — Stanford","url":"http://cs231n.stanford.edu/","nota":"CNNs, do zero ao estado da arte"},{"etapa":"cnns","titulo":"albumentations","url":"https://albumentations.ai/docs/","nota":"Augmentation moderno"},{"etapa":"deteccao","titulo":"Documentação do Ultralytics YOLO","url":"https://docs.ultralytics.com/","nota":"Treino e inferência de detectores"},{"etapa":"deteccao","titulo":"Roboflow","url":"https://roboflow.com/","nota":"Anotação e versionamento de dataset"},{"etapa":"segmentacao","titulo":"Segment Anything (Meta AI)","url":"https://segment-anything.com/","nota":"Segmentação por prompt"},{"etapa":"tracking","titulo":"ByteTrack (repositório)","url":"https://github.com/ifzhang/ByteTrack","nota":"Tracking-by-detection moderno"},{"etapa":"avancadas","titulo":"An Image is Worth 16x16 Words (ViT)","url":"https://arxiv.org/abs/2010.11929","nota":"Vision Transformer"},{"etapa":"avancadas","titulo":"CLIP (OpenAI)","url":"https://openai.com/research/clip","nota":"Visão e linguagem"},{"etapa":"avancadas","titulo":"Papers with Code — Computer Vision","url":"https://paperswithcode.com/area/computer-vision","nota":"Acompanhar o estado da arte"},{"etapa":"visao3d","titulo":"Open3D","url":"https://www.open3d.org/docs/release/","nota":"Nuvens de pontos e registro"},{"etapa":"edge","titulo":"ONNX Runtime","url":"https://onnxruntime.ai/docs/","nota":"Exportação e inferência otimizada"},{"etapa":"edge","titulo":"NVIDIA TensorRT","url":"https://docs.nvidia.com/deeplearning/tensorrt/","nota":"Quantização e aceleração"},{"etapa":"deploy","titulo":"FastAPI","url":"https://fastapi.tiangolo.com/","nota":"Backend recomendado"},{"etapa":"deploy","titulo":"Docker — documentação","url":"https://docs.docker.com/","nota":"Empacotamento e GPU no container"},{"etapa":"capstone","titulo":"100 ideias de projetos de visão computacional","url":"https://github.com/farukalamai/top-100-computer-vision-projects-idea-for-2024","nota":"Banco de temas"},{"etapa":"capstone","titulo":"Repositório do roadmap original","url":"https://github.com/farukalamai/advanced-computer-vision-engineer-roadmap-2024","nota":"Fonte da estrutura"}],"LEGENDA":[{"chave":"fundamental","rotulo":"Fundamental","desc":"Ordem estrita. Não pule."},{"chave":"importante","rotulo":"Importante","desc":"Recomendado, mas a ordem é flexível."},{"chave":"opcional","rotulo":"Opcional","desc":"Pule sem culpa e volte depois."}],"ESTADOS":[{"chave":"pendente","rotulo":"Pendente"},{"chave":"estudando","rotulo":"Estudando"},{"chave":"feito","rotulo":"Feito"},{"chave":"pulado","rotulo":"Pulado"}],"CRITERIOS":["Que problema esta técnica resolve que a anterior não resolvia?","Qual é o custo dela (dados, computação, latência, complexidade)?","Como eu meço se ela funcionou?","Em que condições ela falha?","Eu conseguiria explicar isso a alguém sem usar o jargão?"]}'::jsonb),
  ('langchain', 'LangChain e LangGraph', '#6a4b9e',
   '[[30,168],[62,202],[106,198],[142,168],[148,126],[188,108],[234,118],[272,70]]'::jsonb, 20,
   '{"ROADMAP":{"id":"langchain","titulo":"LangChain e LangGraph","subtitulo":"Oito fases, de cliente tipado a agente supervisionado","fonte":{"rotulo":"Documentação oficial do LangChain e do LangGraph","url":"https://docs.langchain.com/oss/python/langgraph/overview","consultadoEm":"2026-08-30"},"etapas":[{"id":"f0-prereq","numero":0,"titulo":"Pré-requisitos","objetivo":"Cliente de LLM tipado e testável.","descricao":"Esta fase não usa LangChain. A ideia é chegar ao framework sabendo o que ele resolve, e para isso você precisa ter sentido o problema primeiro: pedir \"responda em JSON\" e torcer não é o mesmo que validar uma estrutura. O cliente que você escreve aqui vira a sua régua — quando o LangChain fizer a mesma coisa em três linhas, você vai saber exatamente o que foi abstraído e o que continua sendo problema seu. Timeout, resposta inválida e estouro de contexto são os três erros que aparecem no primeiro dia de produção e que nenhum tutorial trata.","preRequisitos":"Python e noções de LLM","duracao":"3–5 dias","criterios":["Você explica por que validar a saída do modelo é diferente de apenas pedir que ele responda em JSON.","Você trata timeout, resposta inválida e limite de contexto de forma explícita."],"grupos":[{"id":"lc-g-f0","titulo":null,"topicos":[{"id":"lc-f0-01","titulo":"Python moderno","prioridade":"fundamental","desc":"Funções, classes, `typing`, `TypedDict`, iteradores e `async`/`await`.","detalhe":"`TypedDict` é o que o LangGraph usa para declarar o schema de estado, então vale conhecê-lo antes. `async`/`await` deixa de ser opcional a partir da fase 3: chamadas a LLM são I/O, e executar cinco buscas em paralelo contra sequencialmente é a diferença entre 2 e 10 segundos de resposta. Anotações de tipo aqui não são estilo — as bibliotecas as leem em tempo de execução para gerar schemas."},{"id":"lc-f0-02","titulo":"Ambiente e dependências","prioridade":"fundamental","desc":"Ambientes virtuais, variáveis de ambiente e gerenciamento de dependências.","detalhe":"Chave de API vai em variável de ambiente, nunca no código — e `.env` entra no `.gitignore` antes do primeiro commit, não depois. O ecossistema LangChain se move rápido e quebra entre versões menores: fixe as versões em arquivo e anote qual versão da documentação você está seguindo, porque metade dos tutoriais na internet usa APIs que já não existem."},{"id":"lc-f0-03","titulo":"JSON, HTTP e exceções","prioridade":"fundamental","desc":"APIs HTTP e tratamento de exceções.","detalhe":"Toda chamada a um provedor de LLM é HTTP e falha como HTTP: 429 de limite de taxa (que pede backoff exponencial, não retry imediato), 500 transitório, e timeout. Timeout merece atenção especial porque a geração pode legitimamente demorar — um timeout curto demais derruba requisições válidas, e um longo demais trava o seu serviço."},{"id":"lc-f0-04","titulo":"Papéis de mensagem","prioridade":"fundamental","desc":"Mensagens de sistema, usuário, assistente e ferramentas.","detalhe":"A API de chat é uma lista de mensagens com papéis, e cada papel tem peso diferente: a de sistema estabelece comportamento, as de usuário e assistente formam o histórico, e a de ferramenta carrega o retorno de uma chamada. O ciclo completo de tool calling (fase 2) é literalmente a conversa crescendo com uma mensagem de ferramenta no meio — entender isso agora torna aquela fase trivial."},{"id":"lc-f0-05","titulo":"Tokens, contexto e saída estruturada","prioridade":"fundamental","desc":"Janela de contexto, temperatura e saída estruturada.","detalhe":"A janela de contexto é o limite de entrada MAIS saída somadas, e estourá-la é a falha que mais aparece quando você começa a acumular histórico ou a injetar documentos. Temperatura baixa para extração e classificação, mais alta para redação. Sobre saída estruturada: use o modo nativo do provedor (function calling ou JSON schema) em vez de pedir no prompt — a diferença é entre garantia e probabilidade."},{"id":"lc-f0-06","titulo":"Embeddings e RAG","prioridade":"importante","desc":"Noções de embeddings, similaridade vetorial e RAG.","detalhe":"Só o suficiente para a fase 3 não ser do zero: embedding é um vetor que posiciona o texto num espaço onde proximidade significa semelhança de significado, e a busca é por similaridade de cosseno. O conceito que evita a confusão mais comum da trilha inteira: RAG é recuperação, não memória — ele busca em documentos, não lembra da conversa."}]}]},{"id":"f1-fundamentos","numero":1,"titulo":"Fundamentos do LangChain","objetivo":"Pipeline de extração e classificação.","descricao":"O valor desta fase não está nas funcionalidades e sim na interface: quando toda etapa é um `Runnable` com a mesma assinatura, elas se compõem, se trocam e se testam isoladamente. O teste de que você entendeu é o critério de domínio — trocar o provedor de modelo sem encostar na lógica de negócio. Se isso exigir reescrita, a abstração vazou em algum ponto e vale achar onde antes de seguir.","preRequisitos":"Fase 0","duracao":"4–6 dias","criterios":["Você compõe etapas pequenas em vez de escrever um bloco monolítico.","Você troca o modelo sem reescrever a lógica de negócio.","Você testa cada etapa isoladamente."],"grupos":[{"id":"lc-g-f1","titulo":null,"topicos":[{"id":"lc-f1-01","titulo":"Instalação e integração do provedor","prioridade":"fundamental","desc":"Instalar e conectar o provedor de modelo escolhido.","detalhe":"O pacote se divide entre o núcleo e as integrações por provedor, o que é exatamente o que permite trocar de modelo depois. Instale só a integração que você usa. Faça uma chamada crua funcionar antes de montar qualquer cadeia: separar \"a credencial está errada\" de \"a composição está errada\" economiza bastante tempo."},{"id":"lc-f1-02","titulo":"Modelos de chat e mensagens","prioridade":"fundamental","desc":"Objetos de mensagem e a interface de chat.","detalhe":"O LangChain normaliza os papéis da fase 0 em classes de mensagem, e é isso que faz o mesmo código rodar em provedores diferentes. A resposta traz metadados valiosos além do texto: contagem de tokens (para custo), motivo de parada (para detectar truncamento) e as chamadas de ferramenta pendentes, que a fase 2 vai usar."},{"id":"lc-f1-03","titulo":"Prompts e templates","prioridade":"fundamental","desc":"Modelos de prompt parametrizados.","detalhe":"Template separa a instrução estável do dado variável, o que torna o prompt versionável e diffável em vez de uma string montada por concatenação espalhada pelo código. O detalhe operacional: trate o prompt como código — ele vai no repositório, muda com commit, e uma alteração nele pode degradar o sistema tanto quanto uma mudança de lógica."},{"id":"lc-f1-04","titulo":"Saída estruturada e schemas","prioridade":"fundamental","desc":"Schemas e validação da resposta.","detalhe":"Declare um modelo Pydantic e peça a saída nesse formato: a biblioteca converte o schema para o formato do provedor e valida o retorno. As descrições dos campos vão no prompt e influenciam o resultado — são documentação E instrução ao mesmo tempo. Decida desde já o que fazer quando a validação falhar: tentar de novo, pedir correção, ou falhar explicitamente."},{"id":"lc-f1-05","titulo":"Runnable e composição","prioridade":"fundamental","desc":"Composição e execução síncrona e assíncrona.","detalhe":"`Runnable` é a abstração central: tudo (prompt, modelo, parser, função sua) tem `invoke`, `batch`, `stream` e as versões assíncronas. Por isso o operador de composição funciona e por isso streaming e paralelismo vêm de graça quando você compõe em vez de escrever um bloco imperativo. `batch` é o atalho mais subestimado para processar muitos itens com concorrência."},{"id":"lc-f1-06","titulo":"Configuração, callbacks e erros","prioridade":"importante","desc":"Configuração em tempo de execução, callbacks e tratamento de falhas.","detalhe":"Callbacks dão os ganchos de observabilidade que a fase 7 vai usar: início, fim, erro e token a token. Configuração em tempo de execução permite trocar temperatura ou modelo por chamada sem reconstruir a cadeia. Para falhas, os padrões prontos são retry com backoff e fallback para outro modelo — o fallback é o que mantém o sistema de pé durante uma instabilidade do provedor."}]}]},{"id":"f2-agentes","numero":2,"titulo":"Ferramentas e agentes com LangChain","objetivo":"Agente com ferramentas seguras.","descricao":"A pergunta central desta fase é de arquitetura, não de API: o que fica em código e o que é delegado ao modelo. A resposta prática é que regra de negócio, política de segurança e ordem obrigatória de passos ficam em código; a escolha entre caminhos legítimos pode ser do modelo. Delegar demais produz um sistema que não se consegue testar nem auditar. Os dois modos de falha a provocar deliberadamente aqui: o ciclo infinito e a ferramenta sensível executada sem confirmação.","preRequisitos":"Fase 1","duracao":"1 semana","criterios":["Você justifica quais decisões ficam em código e quais podem ser delegadas ao modelo.","O agente não entra em ciclo infinito.","O agente não executa uma ferramenta sensível sem a política esperada."],"grupos":[{"id":"lc-g-f2","titulo":null,"topicos":[{"id":"lc-f2-01","titulo":"Criação de ferramentas","prioridade":"fundamental","desc":"Nome, descrição e schema claros.","detalhe":"A descrição da ferramenta é um prompt: é por ela que o modelo decide se e quando chamar. Vago demais e a ferramenta nunca é usada; genérico demais e é usada sempre. Diga o que ela faz, quando usar e, principalmente, quando NÃO usar. Tipos restritivos no schema (enum em vez de string livre) eliminam uma classe inteira de argumentos inválidos antes de a chamada acontecer."},{"id":"lc-f2-02","titulo":"Tool calling","prioridade":"fundamental","desc":"O ciclo modelo–ferramenta–modelo.","detalhe":"O modelo não executa nada: ele devolve a intenção de chamar, com os argumentos. Quem executa é o seu código, e o resultado volta como mensagem de ferramenta para o modelo continuar. Essa separação é a sua oportunidade de controle — validar argumentos, aplicar autorização, pedir confirmação. O modelo pode pedir várias chamadas de uma vez, e tratá-las em paralelo é ganho fácil."},{"id":"lc-f2-03","titulo":"create_agent e estado do agente","prioridade":"fundamental","desc":"O laço de agente pronto e o que ele guarda.","detalhe":"`create_agent` empacota o laço \"chamar modelo, executar ferramentas, repetir até não haver mais chamadas\". Vale escrever esse laço à mão uma vez antes de usar o atalho: são cerca de vinte linhas e, depois disso, o comportamento do agente deixa de ser caixa-preta. Por baixo, ele já é um grafo do LangGraph — o que torna a fase 4 menos um salto."},{"id":"lc-f2-04","titulo":"Contexto e injeção de dependências","prioridade":"importante","desc":"Contexto de execução e dependências nas ferramentas.","detalhe":"Ferramentas quase sempre precisam de algo que o modelo não deve ver nem escolher: conexão de banco, ID do usuário autenticado, credencial. Isso entra por injeção, fora do schema exposto ao modelo. É também a forma correta de impor escopo — a ferramenta consulta pedidos DO usuário da sessão, e não de um ID que o modelo poderia inventar."},{"id":"lc-f2-05","titulo":"Middleware e limites","prioridade":"fundamental","desc":"Middleware, limites de iteração e tratamento de falhas.","detalhe":"Limite de iterações é obrigatório: sem ele, um modelo que insiste em chamar a mesma ferramenta queima orçamento até o timeout. Middleware é onde entram log, autorização e a confirmação antes de ação com efeito externo. Sobre erro de ferramenta: devolver a mensagem de erro ao modelo costuma funcionar, porque ele corrige o argumento e tenta de novo — desde que a mensagem diga o que estava errado."},{"id":"lc-f2-06","titulo":"Workflow determinístico ou decisão delegada","prioridade":"fundamental","desc":"Quando o fluxo é código e quando é escolha do modelo.","detalhe":"Se os passos são conhecidos de antemão, escreva um workflow: ele é testável, barato e previsível. Agente é para quando o caminho depende do que for descoberto no meio. Um bom projeto costuma ser majoritariamente determinístico com um trecho agêntico delimitado — e esta é a decisão que a fase 4 vai tornar explícita em forma de grafo."}]}]},{"id":"f3-rag","numero":3,"titulo":"RAG com LangChain","objetivo":"Assistente que responde a partir de documentos.","descricao":"RAG parece simples e falha de quatro maneiras diferentes, que o critério de domínio pede para você saber distinguir: o documento não foi indexado, o chunk ficou mal cortado, a recuperação trouxe o trecho errado, ou a geração ignorou o contexto que recebeu. Cada uma pede uma correção distinta, e tratá-las como um problema só é a razão pela qual tanta gente fica ajustando o prompt quando o erro está na indexação. Por isso a regra desta fase: avalie recuperação separadamente da resposta.","preRequisitos":"Fase 1","duracao":"1–2 semanas","criterios":["Você diagnostica separadamente: documento não indexado, chunk inadequado, recuperação irrelevante e geração infiel ao contexto.","A resposta apresenta as fontes recuperadas.","O sistema admite quando não há evidência suficiente."],"grupos":[{"id":"lc-g-f3-1","titulo":"Indexar","topicos":[{"id":"lc-f3-01","titulo":"Carregamento e normalização","prioridade":"fundamental","desc":"Carregar e normalizar documentos.","detalhe":"É a etapa mais ingrata e a que mais determina a qualidade final. PDF com colunas vira texto embaralhado; tabela perde a estrutura; cabeçalho e rodapé repetidos poluem todo chunk. Inspecione o texto extraído antes de indexar — grande parte dos \"o modelo não sabe responder\" se explica aqui, e nenhum ajuste de prompt compensa."},{"id":"lc-f3-02","titulo":"Chunks e metadados","prioridade":"fundamental","desc":"Divisão em chunks e metadados associados.","detalhe":"Chunk grande traz contexto e dilui a similaridade; pequeno é preciso e perde o entorno. Divida respeitando a estrutura (seção, parágrafo) em vez de contar caracteres cegamente, e use sobreposição para não cortar uma frase ao meio. Metadados (fonte, página, seção, data) são o que permite citar a evidência e filtrar a busca — e são baratos de guardar e caros de acrescentar depois."},{"id":"lc-f3-03","titulo":"Embeddings e vector stores","prioridade":"fundamental","desc":"Gerar embeddings e armazená-los.","detalhe":"Use o MESMO modelo de embedding para indexar e para consultar; trocá-lo invalida o índice inteiro e exige reindexar tudo. Para começar, um store local resolve; a migração para um gerenciado vem quando o volume ou a concorrência pedirem. Anote junto do índice qual modelo e qual versão o geraram."}]},{"id":"lc-g-f3-2","titulo":"Recuperar e responder","topicos":[{"id":"lc-f3-04","titulo":"Retrievers, filtros e busca híbrida","prioridade":"fundamental","desc":"Recuperação, filtros por metadado e combinação com busca léxica.","detalhe":"Busca puramente vetorial erra em termos exatos — códigos de produto, nomes próprios, números de artigo — porque semelhança semântica não é igualdade. Busca híbrida combina o vetorial com busca léxica e cobre os dois casos. Filtros por metadado restringem o espaço antes da similaridade e são o jeito de implementar permissão por documento."},{"id":"lc-f3-05","titulo":"Contexto e citação","prioridade":"fundamental","desc":"Construção do contexto e citação das evidências.","detalhe":"A ordem dos trechos importa: modelos prestam menos atenção ao meio de um contexto longo, então coloque o mais relevante nas pontas. Peça a citação por identificador do chunk, não por título livre, para a referência ser verificável. E instrua explicitamente a admitir ausência de evidência — sem isso, o comportamento padrão é preencher a lacuna."},{"id":"lc-f3-06","titulo":"Avaliar recuperação e resposta","prioridade":"fundamental","desc":"Avaliação de recuperação separada da avaliação da resposta.","detalhe":"Monte um conjunto de perguntas com os chunks corretos anotados e meça recall da recuperação primeiro: se o trecho certo não chegou, nenhum ajuste de geração resolve. Só depois avalie a resposta quanto à fidelidade ao contexto fornecido. Duas métricas, dois diagnósticos — é literalmente o critério de domínio desta fase."},{"id":"lc-f3-07","titulo":"Riscos de RAG","prioridade":"fundamental","desc":"Prompt injection em documentos, conteúdo desatualizado e ausência de evidência.","detalhe":"Documento recuperado é entrada NÃO CONFIÁVEL: um texto que contenha \"ignore as instruções anteriores\" pode sequestrar o comportamento do agente, e isso é especialmente grave quando ele tem ferramentas com efeito externo (fase 2). Trate o conteúdo recuperado como dado, delimite-o claramente no prompt, e nunca deixe que ele autorize uma ação. Conteúdo desatualizado é o outro risco: registre a data no metadado e deixe-a visível na resposta."}]}]},{"id":"f4-grafos","numero":4,"titulo":"Fundamentos do LangGraph","objetivo":"Workflow com estado, decisão e ciclo.","descricao":"Aqui o controle de fluxo deixa de ser implícito e vira estrutura declarada: estado, nós e arestas. A recomendação da fonte é começar pelo Graph API em vez da Functional API justamente porque ele torna o fluxo VISÍVEL — e o critério de domínio desta fase é desenhar o grafo antes de programá-lo. A outra recomendação vale ouro e quase ninguém segue: implemente o workflow inteiro com funções determinísticas ou simuladas primeiro, e só depois conecte o LLM. Depurar topologia e depurar prompt ao mesmo tempo é o que torna esta fase difícil sem necessidade.","preRequisitos":"Fase 2","duracao":"1 semana","criterios":["Você desenha o grafo antes de programá-lo.","Você explica cada campo do estado e quem o modifica.","Você prevê quais nós serão executados em cada rota."],"grupos":[{"id":"lc-g-f4-1","titulo":"Modelo mental","descricao":"Um workflow no Graph API é definido por três coisas, e só por elas.","topicos":[{"id":"lc-f4-01","titulo":"Estado","prioridade":"fundamental","desc":"Snapshot compartilhado da aplicação.","detalhe":"O estado é o contrato do grafo: tudo que um nó precisa ler ou escrever passa por ele. Projete-o primeiro, campo a campo, respondendo para cada um quem escreve e quem lê. Estado inchado com dados que só um nó usa é sinal de que aquilo deveria ser variável local; estado faltando campo força comunicação por efeito colateral, que é o começo de um grafo impossível de depurar."},{"id":"lc-f4-02","titulo":"Nós","prioridade":"fundamental","desc":"Funções que executam lógica e retornam atualizações.","detalhe":"Um nó recebe o estado e devolve apenas o DELTA — os campos que mudaram — e não o estado inteiro. Isso é o que permite execução paralela sem sobrescrita acidental. Mantenha cada nó com uma responsabilidade: colocar toda a lógica em um nó só é uma das armadilhas listadas no roadmap, e anula o motivo de usar grafo."},{"id":"lc-f4-03","titulo":"Arestas","prioridade":"fundamental","desc":"Transições fixas ou condicionais entre nós.","detalhe":"Aresta fixa sempre leva ao mesmo nó; condicional é uma função que lê o estado e devolve o próximo destino. A regra prática que vale para o resto da trilha: a condição é código seu, determinístico e testável, mesmo quando o DADO que ela inspeciona veio do modelo. Roteamento é lugar de `if`, não de prompt."}]},{"id":"lc-g-f4-2","titulo":"Construir o grafo","topicos":[{"id":"lc-f4-04","titulo":"StateGraph e reducers","prioridade":"fundamental","desc":"Schemas de estado e reducers.","detalhe":"Por padrão, uma atualização SUBSTITUI o valor do campo. Reducer muda essa regra — o caso clássico é a lista de mensagens, que deve acumular em vez de sobrescrever. Quando dois nós paralelos escrevem no mesmo campo sem reducer, você tem uma condição de corrida; com reducer de concatenação, tem o resultado combinado. É o primeiro lugar onde um grafo paralelo dá errado."},{"id":"lc-f4-05","titulo":"Nós, arestas, START e END","prioridade":"fundamental","desc":"Montagem básica do grafo.","detalhe":"`START` e `END` são nós virtuais que marcam entrada e saída. Compile o grafo e renderize o diagrama antes de executar: comparar o desenho que você fez à mão com o que a biblioteca gerou revela aresta esquecida e nó órfão em segundos. Esse diagrama também é um dos entregáveis do projeto final."},{"id":"lc-f4-06","titulo":"Sequências, ramificações e ciclos","prioridade":"fundamental","desc":"As três topologias básicas.","detalhe":"Ciclo é o que diferencia grafo de pipeline: é ele que permite \"buscar de novo se a evidência for insuficiente\", que é o passo 5 do projeto desta fase. E todo ciclo precisa de condição de parada explícita, normalmente um contador de tentativas no estado — o mesmo cuidado com limite de iterações da fase 2, agora na topologia."},{"id":"lc-f4-07","titulo":"Roteamento condicional","prioridade":"fundamental","desc":"Escolher o próximo nó a partir do estado.","detalhe":"A função de roteamento deve ser pura e testável sem LLM: dado um estado, qual é o próximo nó. Escreva testes para ela cobrindo cada rota — é o teste mais barato e mais valioso do grafo inteiro, e responde diretamente ao critério de \"prever quais nós serão executados em cada rota\"."},{"id":"lc-f4-08","titulo":"Command","prioridade":"importante","desc":"Combinar atualização de estado e controle de fluxo.","detalhe":"`Command` deixa um nó devolver, de uma vez, o que mudou no estado E para onde ir. Isso evita separar artificialmente a decisão (que o nó já tomou, porque tem a informação) da aresta condicional (que teria de reinspecionar o estado para redescobri-la). Use quando o próprio nó é quem sabe o destino."},{"id":"lc-f4-09","titulo":"Send e map-reduce","prioridade":"importante","desc":"Fan-out dinâmico.","detalhe":"`Send` despacha N execuções paralelas de um nó, uma por item, quando N só é conhecido em tempo de execução — exatamente o caso de \"executar pesquisas em paralelo\" do projeto. Os resultados se juntam no estado via reducer, fechando o map-reduce. É também onde a vantagem do `async` da fase 0 aparece de forma concreta."},{"id":"lc-f4-10","titulo":"Functional API versus Graph API","prioridade":"opcional","desc":"Por que começar pelo Graph API.","detalhe":"A Functional API usa decoradores e fluxo de controle Python comum, o que é mais natural de escrever e menos explícito de ler. O Graph API obriga a declarar a topologia, e é essa obrigação que tem valor didático agora: o grafo desenhado é o sistema documentado. Volte à Functional API depois, quando a estrutura já estiver clara na sua cabeça."}]}]},{"id":"f5-persistencia","numero":5,"titulo":"Persistência e human-in-the-loop","objetivo":"Agente retomável com aprovação.","descricao":"Esta fase resolve dois problemas que sempre aparecem juntos em sistema real: o processo precisa sobreviver a uma reinicialização, e uma pessoa precisa aprovar antes de algo irreversível acontecer. O checkpoint é o que torna as duas coisas possíveis — pausar é só não avançar, e retomar é carregar o estado salvo. A sutileza que morde aqui é a reexecução: ao retomar, o nó interrompido roda desde o começo, então qualquer efeito externo que ele já tenha causado acontece de novo. Daí a insistência em idempotência.","preRequisitos":"Fase 4","duracao":"1 semana","criterios":["Você sabe onde posicionar uma interrupção.","Você evita duplicar efeitos externos durante retomadas.","Você consegue inspecionar o estado persistido."],"grupos":[{"id":"lc-g-f5","titulo":null,"topicos":[{"id":"lc-f5-01","titulo":"Checkpoints e threads","prioridade":"fundamental","desc":"Retomada de execução por `thread_id`.","detalhe":"O checkpointer salva o estado a cada passo, indexado por `thread_id`. A thread é a unidade de conversa: mesmo ID, mesmo histórico e mesmo estado. Para desenvolvimento, um checkpointer em memória basta; para o projeto desta fase, que exige reiniciar o processo e retomar, é preciso um persistente de verdade. Teste matando o processo no meio, não simulando."},{"id":"lc-f5-02","titulo":"Persistência e tolerância a falhas","prioridade":"fundamental","desc":"Estado durável e recuperação.","detalhe":"Com checkpoint a cada nó, uma falha custa no máximo um nó de retrabalho, e não a execução inteira — o que importa quando cada nó custa uma chamada paga de LLM. Guardar o histórico de checkpoints também dá depuração temporal: você consegue olhar o estado exato antes da decisão errada, em vez de reconstruí-lo a partir de logs."},{"id":"lc-f5-03","titulo":"interrupt() e retomada com Command","prioridade":"fundamental","desc":"Pausar e retomar com a decisão humana.","detalhe":"`interrupt()` suspende a execução e devolve o controle a quem chamou, com os dados que a pessoa precisa ver. A retomada acontece com um `Command` carregando a decisão. O detalhe decisivo: a retomada reexecuta o nó DESDE O INÍCIO, e o `interrupt()` devolve o valor fornecido em vez de pausar de novo. Por isso o código antes da interrupção não pode ter efeito colateral."},{"id":"lc-f5-04","titulo":"Revisão, aprovação, edição e rejeição","prioridade":"fundamental","desc":"Os quatro desfechos de uma intervenção humana.","detalhe":"Aprovar e rejeitar são os casos fáceis. Editar é o mais útil e o mais esquecido: a pessoa corrige o argumento da ferramenta e o fluxo segue com o valor corrigido. Trate os quatro desfechos explicitamente no estado — e lembre que a rejeição precisa de um caminho de saída digno, não de uma exceção não tratada."},{"id":"lc-f5-05","titulo":"Idempotência de efeitos externos","prioridade":"fundamental","desc":"Não duplicar o que já aconteceu.","detalhe":"A técnica é a chave de idempotência: gere um identificador determinístico para a operação e deixe que o sistema externo ignore a repetição. Enquanto isso não existir, siga a regra estrutural — coloque o efeito externo DEPOIS da interrupção, num nó próprio e minúsculo, de modo que a reexecução do nó anterior não dispare nada."},{"id":"lc-f5-06","titulo":"Implicações da reexecução","prioridade":"fundamental","desc":"O que roda de novo após uma interrupção.","detalhe":"Internalize: o nó inteiro roda de novo. Isso significa que chamadas de LLM antes do `interrupt()` são repetidas (custo), que contadores incrementados ali são incrementados duas vezes (bug) e que logs aparecem duplicados (confusão). O padrão seguro é um nó que só prepara e interrompe, e outro que só executa."}]}]},{"id":"f6-streaming","numero":6,"titulo":"Streaming, memória e subgrafos","objetivo":"Agente modular e responsivo.","descricao":"O critério de domínio desta fase é conceitual e vale mais que qualquer API: distinguir histórico de conversa, estado transitório, checkpoint e memória de longo prazo — e escolher conscientemente onde cada dado vive. Confundi-los é uma das armadilhas listadas no roadmap, e produz sistemas que lembram do que deveriam esquecer e esquecem do que deveriam lembrar. O streaming, por sua vez, é menos sobre velocidade e mais sobre percepção: um agente que leva oito segundos mostrando progresso é aceitável; o mesmo agente em silêncio, não.","preRequisitos":"Fase 5","duracao":"1 semana","criterios":["Você distingue histórico de conversa, estado transitório, checkpoint e memória de longo prazo.","Você escolhe conscientemente onde cada dado deve viver."],"grupos":[{"id":"lc-g-f6","titulo":null,"topicos":[{"id":"lc-f6-01","titulo":"Modos de streaming","prioridade":"fundamental","desc":"Mensagens, tokens, atualizações e valores de estado.","detalhe":"São granularidades diferentes para públicos diferentes: token a token para a resposta final na tela; atualizações por nó para indicar progresso (\"pesquisando\", \"verificando\"); valores de estado para depuração. Dá para consumir mais de um modo ao mesmo tempo, e a escolha é de interface, não de implementação."},{"id":"lc-f6-02","titulo":"Eventos personalizados","prioridade":"importante","desc":"Informar progresso a partir de dentro dos nós.","detalhe":"Quando um nó faz algo demorado que não é uma chamada de LLM — uma busca, um cálculo, uma espera por API — nada é transmitido por padrão e a interface congela. Eventos personalizados permitem emitir sinais de progresso de dentro do nó, e são o que evita a sensação de travamento na parte mais lenta do fluxo."},{"id":"lc-f6-03","titulo":"Memória de curto prazo","prioridade":"fundamental","desc":"Histórico no estado da thread.","detalhe":"É o histórico da conversa, que vive no estado e morre com a thread. O problema inevitável é o crescimento: a janela de contexto estoura. As saídas são resumir as mensagens antigas, manter uma janela deslizante das últimas N, ou ambas. Decida a política ANTES de o estouro acontecer em produção."},{"id":"lc-f6-04","titulo":"Memória de longo prazo","prioridade":"fundamental","desc":"Stores organizados por namespace e chave.","detalhe":"É o que atravessa threads: a preferência do usuário lembrada na conversa de amanhã. Vive num store separado, organizado por namespace (tipicamente o usuário) e chave. Duas regras que o projeto final cobra: grave apenas o que foi explicitamente autorizado, e deixe a memória inspecionável e apagável — memória implícita que o usuário não sabe que existe é problema de produto e de privacidade."},{"id":"lc-f6-05","titulo":"Subgrafos","prioridade":"importante","desc":"Modularidade e isolamento de estado.","detalhe":"Um subgrafo é um grafo usado como nó de outro, com estado próprio e uma tradução explícita na fronteira. É o que mantém o grafo principal legível quando o sistema cresce, e o que permite testar \"pesquisa\" e \"revisão\" isoladamente — que é exatamente o que o projeto desta fase pede. Também é o caminho natural para multiagente, mais tarde."},{"id":"lc-f6-06","titulo":"Execução assíncrona e cancelamento","prioridade":"importante","desc":"Rodar e interromper sob demanda.","detalhe":"Cancelamento é requisito real: o usuário fecha a aba, e o seu agente continua gastando tokens numa pesquisa que ninguém vai ler. Trate o cancelamento como caminho previsto — propagado para as chamadas em andamento, com o estado salvo até o último passo concluído, de modo que a thread continue retomável."}]}]},{"id":"f7-producao","numero":7,"titulo":"Avaliação, observabilidade e produção","objetivo":"Projeto final observável e testado.","descricao":"A regra que organiza esta fase está na própria fonte: implante somente depois de tornar o comportamento observável. Sem trace, um agente em produção é uma caixa-preta cara — você sabe que a resposta ficou ruim e não sabe em qual dos oito passos ela se perdeu. A segunda regra é avaliar a TRAJETÓRIA, não só a resposta: um agente que chega à conclusão certa depois de chamar a ferramenta errada quatro vezes passa em qualquer avaliação de saída final e vai quebrar no primeiro caso que não estava no seu teste.","preRequisitos":"Fases 3 e 6","duracao":"1–2 semanas","criterios":["Diagrama do grafo e contrato de estado documentados.","Ferramentas tipadas e com erros tratados.","Persistência e retomada verificadas.","Pelo menos um interrupt de aprovação.","Testes de nós e rotas críticas.","Dataset de avaliação com casos normais e adversariais.","Medições de qualidade, custo e latência.","Lista explícita de riscos e limitações."],"grupos":[{"id":"lc-g-f7-1","titulo":"Observar e avaliar","topicos":[{"id":"lc-f7-01","titulo":"Tracing e depuração","prioridade":"fundamental","desc":"LangSmith.","detalhe":"Um trace mostra a árvore completa de execução: cada nó, cada prompt enviado, cada resposta, tokens e latência por passo. Ligue isso no começo do desenvolvimento, não no fim — ele é mais útil enquanto você constrói, e a prática de olhar o trace antes de chutar uma causa é o hábito que esta fase precisa instalar."},{"id":"lc-f7-02","titulo":"Datasets de avaliação","prioridade":"fundamental","desc":"Casos de regressão.","detalhe":"Toda vez que você encontrar um caso em que o sistema erra, transforme-o em caso de teste antes de corrigir. O conjunto cresce a partir das falhas reais, que é a única fonte confiável de casos difíceis. Sem isso, cada ajuste de prompt corrige um caso e quebra outro silenciosamente — e você só descobre pelo usuário."},{"id":"lc-f7-03","titulo":"Avaliação de trajetória","prioridade":"fundamental","desc":"Decisões, chamadas de ferramentas e resultado.","detalhe":"Avalie se as ferramentas certas foram chamadas, na ordem razoável, com os argumentos corretos — e não só se a resposta final ficou boa. Trajetória ruim com resultado bom é sorte, custa caro em tokens e não generaliza. É também o que permite detectar o agente que entrou em laço e saiu por limite de iteração."},{"id":"lc-f7-04","titulo":"Métricas de qualidade e custo","prioridade":"fundamental","desc":"Groundedness, custo e latência.","detalhe":"Groundedness mede se a resposta se sustenta no contexto recuperado e é a métrica central de qualquer sistema com RAG. Acompanhe custo por requisição desde o primeiro dia: agentes têm custo variável, e um laço mal contido transforma centavos em dezenas de reais sem aviso. Latência vale no percentil, não na média."}]},{"id":"lc-g-f7-2","titulo":"Endurecer e entregar","topicos":[{"id":"lc-f7-05","titulo":"Resiliência","prioridade":"fundamental","desc":"Retries, timeouts, limites, cache e fallback.","detalhe":"Retry com backoff exponencial para 429 e 5xx; timeout em toda chamada externa; limite de iterações e de custo por requisição; fallback para um modelo alternativo quando o provedor cai. Cache de embeddings e de respostas idênticas corta custo de desenvolvimento de forma significativa, porque você reexecuta o mesmo caso dezenas de vezes."},{"id":"lc-f7-06","titulo":"Segurança","prioridade":"fundamental","desc":"Ferramentas, autorização, dados pessoais e prompt injection.","detalhe":"A regra que não se negocia: autorização é verificada no SEU código, nunca no prompt. Um modelo pode ser convencido a ignorar uma instrução; um `if` não. Some isso ao risco de injeção via documento recuperado (fase 3) e à exigência de aprovação humana para ação sensível (fase 5), e você tem as três camadas que sustentam um agente com acesso a ferramentas reais. Dados pessoais: minimize o que entra no prompt e no trace."},{"id":"lc-f7-07","titulo":"Testes","prioridade":"fundamental","desc":"Unitários de nós e integração do grafo.","detalhe":"Nó é função: teste com estado de entrada fixo e LLM simulado. Rota é função pura: teste cada caminho. Integração roda o grafo com simulações e verifica a sequência de nós executada. O objetivo é que a maior parte da suíte rode sem chamar um LLM real — rápida, barata e determinística. Essa é a última das cinco perguntas de fechamento de semana, e não por acaso."},{"id":"lc-f7-08","titulo":"Implantar depois de observar","prioridade":"fundamental","desc":"A ordem correta de colocar em produção.","detalhe":"Antes de implantar: trace ligado, métricas de custo e latência coletadas, dataset de avaliação passando, limites configurados e um caminho de rollback pronto. O projeto final pede diagrama do grafo, contrato de estado documentado e lista explícita de riscos e limitações — e essa lista é o que demonstra que você entendeu o sistema, mais ainda do que o sistema funcionando."}]}]}]},"PROJETOS":{"f0-prereq":["Criar um cliente mínimo para um modelo de chat que receba texto e devolva uma estrutura tipada: assunto, intenção e nível de urgência de uma mensagem."],"f1-fundamentos":["Construir um pipeline de triagem que classifique a solicitação, extraia campos para um schema, gere a resposta adequada à categoria e registre entradas, saídas e falhas."],"f2-agentes":["Criar um agente assistente com três ferramentas locais: consultar uma base de produtos, calcular um valor e registrar uma solicitação em armazenamento de teste.","Adicionar validação de argumentos, mensagens de erro úteis e confirmação antes de qualquer ação com efeito externo."],"f3-rag":["Construir um assistente para consultar um conjunto pequeno de documentos, apresentando as fontes recuperadas e admitindo quando não houver evidência suficiente."],"f4-grafos":["Implementar um workflow de pesquisa: recebe a pergunta, cria um plano, executa pesquisas em paralelo, verifica se as evidências bastam, repete a busca quando necessário e sintetiza a resposta.","Começar com funções determinísticas ou simuladas e só depois conectar o LLM."],"f5-persistencia":["Evoluir o workflow para preparar uma ação sensível, pausar antes de executá-la e permitir que uma pessoa aprove, altere ou rejeite.","Reiniciar o processo e confirmar que ele retoma usando o mesmo `thread_id`."],"f6-streaming":["Mostrar tokens e etapas conforme são produzidos.","Manter o histórico da thread.","Recordar uma preferência do usuário entre threads.","Encapsular pesquisa e revisão em subgrafos."],"f7-producao":["Projeto final — assistente de pesquisa e ação supervisionada: classifica a solicitação, recupera documentos, planeja e usa ferramentas, pede aprovação para ações sensíveis, mantém memória autorizada, transmite progresso, registra traces e é avaliado contra perguntas normais e cenários adversariais."]},"RECURSOS":[{"etapa":"f0-prereq","titulo":"LangChain Academy","url":"https://academy.langchain.com/","nota":"Curso oficial, bom ponto de partida"},{"etapa":"f1-fundamentos","titulo":"LangChain — visão geral","url":"https://docs.langchain.com/oss/python/langchain/overview","nota":"Componentes e Runnables"},{"etapa":"f2-agentes","titulo":"LangChain — agentes","url":"https://docs.langchain.com/oss/python/langchain/agents","nota":"`create_agent` e middleware"},{"etapa":"f2-agentes","titulo":"LangChain — ferramentas","url":"https://docs.langchain.com/oss/python/langchain/tools","nota":"Definição e schemas"},{"etapa":"f3-rag","titulo":"LangChain — recuperação","url":"https://docs.langchain.com/oss/python/langchain/retrieval","nota":"Retrievers e vector stores"},{"etapa":"f4-grafos","titulo":"LangGraph — visão geral","url":"https://docs.langchain.com/oss/python/langgraph/overview","nota":"Modelo mental"},{"etapa":"f4-grafos","titulo":"LangGraph — Graph API","url":"https://docs.langchain.com/oss/python/langgraph/graph-api","nota":"Referência do StateGraph"},{"etapa":"f4-grafos","titulo":"LangGraph — uso do Graph API","url":"https://docs.langchain.com/oss/python/langgraph/use-graph-api","nota":"Padrões de uso"},{"etapa":"f5-persistencia","titulo":"LangGraph — persistência","url":"https://docs.langchain.com/oss/python/langgraph/persistence","nota":"Checkpoints e threads"},{"etapa":"f5-persistencia","titulo":"LangGraph — interrupts","url":"https://docs.langchain.com/oss/python/langgraph/interrupts","nota":"Human-in-the-loop"},{"etapa":"f6-streaming","titulo":"LangGraph — streaming","url":"https://docs.langchain.com/oss/python/langgraph/streaming","nota":"Modos de transmissão"},{"etapa":"f6-streaming","titulo":"LangChain — memória de longo prazo","url":"https://docs.langchain.com/oss/python/langchain/long-term-memory","nota":"Stores e namespaces"},{"etapa":"f7-producao","titulo":"LangSmith","url":"https://docs.smith.langchain.com/","nota":"Tracing e avaliação"}],"LEGENDA":[{"chave":"fundamental","rotulo":"Fundamental","desc":"Ordem estrita. Não pule."},{"chave":"importante","rotulo":"Importante","desc":"Recomendado, mas a ordem é flexível."},{"chave":"opcional","rotulo":"Opcional","desc":"Pule sem culpa e volte depois."}],"ESTADOS":[{"chave":"pendente","rotulo":"Pendente"},{"chave":"estudando","rotulo":"Estudando"},{"chave":"feito","rotulo":"Feito"},{"chave":"pulado","rotulo":"Pulado"}],"CRITERIOS":["O que o framework resolveu por mim?","Que estado existe e quem o modifica?","O fluxo é determinístico ou decidido pelo modelo?","Como o sistema falha e como observo essa falha?","Eu conseguiria testar esta parte sem chamar um LLM real?"]}'::jsonb)
on conflict (id) do nothing;
